pub fn parseBulkIoWhereExpressionsAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
) ![]const db_mod.types.RelationalRowsExpressionCondition {
    const cursor = parser.Cursor.init(tokens, pos);
    if (!cursor.matchKeyword("where")) return &.{};

    var conditions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        plan_mod.freeExpressionConditions(alloc, conditions.items);
        conditions.deinit(alloc);
    }
    while (true) {
        const condition = try parseBulkIoWhereExpressionConditionAlloc(
            alloc,
            tokens,
            pos,
            schema,
            field_expression_qualifiers,
            returning_expression_qualifiers,
            defer_row_expression_field_validation,
        );
        var condition_transferred = false;
        errdefer if (!condition_transferred) plan_mod.freeExpressionCondition(alloc, condition);
        try conditions.append(alloc, condition);
        condition_transferred = true;
        if (!cursor.matchKeyword("and")) break;
    }
    if (cursor.matchToken(.semicolon) != null and !cursor.atEnd()) return error.UnsupportedSqlShape;
    if (!cursor.atEnd()) return error.UnsupportedSqlShape;
    return try conditions.toOwnedSlice(alloc);
}

fn parseBulkIoWhereExpressionConditionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    schema: runtime_schema.TableSchema,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
) !db_mod.types.RelationalRowsExpressionCondition {
    const parsed_field = try expr_generated.parseRowExpressionFieldOwnedAlloc(
        alloc,
        tokens,
        pos,
        schema,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    );
    defer alloc.free(parsed_field);
    const field = try binder.normalizeRowExpressionFieldAlloc(
        alloc,
        schema,
        parsed_field,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    );
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(field);

    const op = try expr_operator.parseComparisonOp(tokens, pos);
    const value_json = try value_mod.parseSqlUntypedValueJsonAlloc(alloc, tokens, pos);
    var value_transferred = false;
    errdefer if (!value_transferred) alloc.free(value_json);

    const rhs = try alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
    var rhs_transferred = false;
    errdefer if (!rhs_transferred) alloc.free(rhs);
    rhs[0] = .{
        .kind = .value,
        .value_json = value_json,
    };

    field_transferred = true;
    value_transferred = true;
    rhs_transferred = true;
    return .{
        .lhs = .{
            .kind = .field,
            .field = field,
        },
        .op = op,
        .rhs = rhs,
    };
}

fn freeSubqueryPredicates(alloc: std.mem.Allocator, values: []const db_mod.types.RelationalRowsSubqueryPredicate) void {
    for (values) |value| {
        if (value.lhs) |lhs| freeExpression(alloc, lhs);
        var query = value.query;
        query.deinit(alloc);
        if (value.output_field.len > 0) alloc.free(value.output_field);
        plan_mod.freeLateralCorrelations(alloc, value.correlations);
        if (value.correlations.len > 0) alloc.free(value.correlations);
        if (value.collation) |collation| alloc.free(collation);
    }
}

fn generatedSubqueryLhsExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    expression: *const generated_parser.GeneratedSqlExpressionAst,
    type_context: expr_type.RowExpressionTypeContext,
    hooks: expr_where_condition.ExpressionWhereConditionsParserOptions,
) !?db_mod.types.RelationalRowsExpression {
    const lhs_tokens = expression.left_tokens orelse return null;
    const field_tokens = if (expression.left_expression) |left_expression| blk: {
        if (left_expression.kind != .token_range) break :blk null;
        break :blk left_expression.tokens;
    } else lhs_tokens;
    if (field_tokens) |range| {
        if (range.end == range.start + 1 and range.end <= tokens.len and tokens[range.start].kind == .identifier) {
            const parsed_field = try grammar.normalizeSqlObjectIdentifierAlloc(alloc, tokens[range.start].text);
            defer alloc.free(parsed_field);
            const resolved = try binder.resolveRowExpressionFieldAlloc(
                alloc,
                type_context.schema,
                type_context.joined_source_schema,
                parsed_field,
                &.{},
                &.{},
                &.{},
                &.{},
                type_context.defer_row_expression_field_validation,
                .row,
            );
            return .{
                .kind = .field,
                .field = resolved.field,
                .field_source = resolved.source,
            };
        }
    }
    var pos = lhs_tokens.start;
    const lhs = try expr_row_parse.parseRowExpressionAlloc(
        alloc,
        tokens,
        &pos,
        type_context,
        hooks.row_expression_hooks,
        hooks.arithmetic_hooks,
        hooks.variadic_hooks,
    );
    errdefer freeExpression(alloc, lhs);
    if (pos != lhs_tokens.end) return error.UnsupportedSqlShape;
    return lhs;
}

fn generatedSubquerySourceContextAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    base_schema: runtime_schema.TableSchema,
    type_context: expr_type.RowExpressionTypeContext,
    available_ctes: []const db_mod.types.RelationalRowsCte,
    expression: *const generated_parser.GeneratedSqlExpressionAst,
    query: *db_mod.types.RelationalRowsQueryRequest,
) !expr_type.RowExpressionTypeContext {
    const source_tokens = expression.subquery_source_tokens orelse return error.UnsupportedSqlShape;
    var source_pos = source_tokens.start;
    const source_table = try plan_mod.parseTableAliasAlloc(alloc, tokens, &source_pos);
    defer plan_mod.freeTableAlias(alloc, source_table);
    if (source_pos != source_tokens.end) return error.UnsupportedSqlShape;

    var source_context = type_context;
    if (plan_mod.findCteByName(available_ctes, source_table.name) != null) {
        query.source_cte = try alloc.dupe(u8, source_table.name);
        errdefer {
            alloc.free(query.source_cte);
            query.source_cte = "";
        }
        const planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, base_schema, available_ctes);
        defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
        source_context.schema = relational_rows.rowsPlannedCteSchema(planned_ctes, source_table.name) orelse return error.UnsupportedSqlShape;
        source_context.joined_source_schema = null;
        source_context.defer_row_expression_field_validation = false;
    }
    return source_context;
}

fn generatedSubqueryQualifiedFieldFromSideAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    range: ?generated_parser.GeneratedSqlTokenRange,
    expression_kind: ?generated_parser.GeneratedSqlExpressionKind,
    expression: ?*const generated_parser.GeneratedSqlExpressionAst,
) !?plan_mod.QualifiedField {
    const field_range = range orelse return null;
    if (expression) |child| {
        if (child.kind != .token_range) return null;
        const child_range = child.tokens orelse return error.UnsupportedSqlShape;
        if (!generatedTokenRangeEqual(child_range, field_range)) return error.UnsupportedSqlShape;
    } else if (expression_kind) |kind| {
        if (kind != .token_range) return null;
    }
    var pos = field_range.start;
    const field = plan_mod.parseQualifiedFieldAlloc(alloc, tokens, &pos) catch |err| switch (err) {
        error.UnsupportedSqlShape => return null,
        else => return err,
    };
    errdefer plan_mod.freeQualifiedField(alloc, field);
    if (pos != field_range.end) return error.UnsupportedSqlShape;
    return field;
}

fn generatedSubqueryQualifierMatchesSource(source_table: plan_mod.TableAlias, qualifier: []const u8) bool {
    if (source_table.alias.len != 0 and std.ascii.eqlIgnoreCase(source_table.alias, qualifier)) return true;
    return std.ascii.eqlIgnoreCase(source_table.name, qualifier);
}

fn generatedSubqueryCorrelationFromQualifiedFieldsAlloc(
    alloc: std.mem.Allocator,
    outer_schema: runtime_schema.TableSchema,
    inner_schema: runtime_schema.TableSchema,
    source_table: plan_mod.TableAlias,
    left: plan_mod.QualifiedField,
    right: plan_mod.QualifiedField,
) !?db_mod.types.RelationalRowsLateralCorrelation {
    const left_inner = generatedSubqueryQualifierMatchesSource(source_table, left.qualifier);
    const right_inner = generatedSubqueryQualifierMatchesSource(source_table, right.qualifier);
    if (left_inner == right_inner) return null;
    const inner_field = if (left_inner) left.field else right.field;
    const outer_field = if (left_inner) right.field else left.field;
    if (binder.relationalColumnForField(inner_schema, inner_field, null) == null) return error.InvalidSqlCatalog;
    if (binder.relationalColumnForField(outer_schema, outer_field, null) == null) return error.InvalidSqlCatalog;
    return .{
        .left_field = try alloc.dupe(u8, outer_field),
        .right_field = try alloc.dupe(u8, inner_field),
    };
}

fn generatedSubqueryCorrelationWhereAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    outer_schema: runtime_schema.TableSchema,
    inner_schema: runtime_schema.TableSchema,
    source_table: plan_mod.TableAlias,
    expression: ?*const generated_parser.GeneratedSqlExpressionAst,
) !?db_mod.types.RelationalRowsLateralCorrelation {
    const where_expression = expression orelse return null;
    if (where_expression.kind == .grouped) {
        const inner = where_expression.inner_expression orelse return error.UnsupportedSqlShape;
        if (where_expression.inner_expression_kind != null and where_expression.inner_expression_kind.? != inner.kind) return error.UnsupportedSqlShape;
        const inner_tokens = where_expression.inner_tokens orelse return error.UnsupportedSqlShape;
        const inner_expression_tokens = inner.tokens orelse return error.UnsupportedSqlShape;
        if (!generatedTokenRangeEqual(inner_expression_tokens, inner_tokens)) return error.UnsupportedSqlShape;
        return try generatedSubqueryCorrelationWhereAlloc(
            alloc,
            tokens,
            outer_schema,
            inner_schema,
            source_table,
            inner,
        );
    }
    if (where_expression.kind != .comparison) return null;
    const operator_tokens = where_expression.operator_tokens orelse return error.UnsupportedSqlShape;
    if (operator_tokens.end != operator_tokens.start + 1 or tokens[operator_tokens.start].kind != .eq) return null;
    const left = (try generatedSubqueryQualifiedFieldFromSideAlloc(
        alloc,
        tokens,
        where_expression.left_tokens,
        where_expression.left_expression_kind,
        where_expression.left_expression,
    )) orelse return null;
    defer plan_mod.freeQualifiedField(alloc, left);
    const right = (try generatedSubqueryQualifiedFieldFromSideAlloc(
        alloc,
        tokens,
        where_expression.right_tokens,
        where_expression.right_expression_kind,
        where_expression.right_expression,
    )) orelse return null;
    defer plan_mod.freeQualifiedField(alloc, right);
    return try generatedSubqueryCorrelationFromQualifiedFieldsAlloc(
        alloc,
        outer_schema,
        inner_schema,
        source_table,
        left,
        right,
    );
}

fn appendGeneratedSubqueryCorrelationAlloc(
    alloc: std.mem.Allocator,
    correlations: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsLateralCorrelation),
    correlation: db_mod.types.RelationalRowsLateralCorrelation,
) !void {
    var correlation_transferred = false;
    errdefer if (!correlation_transferred) {
        alloc.free(correlation.left_field);
        alloc.free(correlation.right_field);
    };
    try correlations.append(alloc, correlation);
    correlation_transferred = true;
}

fn parseGeneratedSubqueryProjectionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    expression: *const generated_parser.GeneratedSqlExpressionAst,
    type_context: expr_type.RowExpressionTypeContext,
    query: *db_mod.types.RelationalRowsQueryRequest,
) ![]const u8 {
    const projection_tokens = expression.subquery_projection_tokens orelse return error.UnsupportedSqlShape;
    if (expression.subquery_projection_items.count != 1 or expression.subquery_projection_items.expression_items.len != 1) return error.UnsupportedSqlShape;
    const item_tokens = expression.subquery_projection_items.expression_items[0];
    if (item_tokens.start < projection_tokens.start or item_tokens.end > projection_tokens.end) return error.UnsupportedSqlShape;
    if (expression.subquery_projection_items.expressions.len != 1) return error.UnsupportedSqlShape;
    const generated_projection = expression.subquery_projection_items.expressions[0];
    if (generated_projection.kind != .token_range) return error.UnsupportedSqlShape;
    const generated_projection_tokens = generated_projection.tokens orelse return error.UnsupportedSqlShape;
    if (!generatedTokenRangeEqual(generated_projection_tokens, item_tokens)) return error.UnsupportedSqlShape;
    if (item_tokens.end != item_tokens.start + 1 or item_tokens.end > tokens.len or tokens[item_tokens.start].kind != .identifier) return error.UnsupportedSqlShape;
    const parsed_field = try alloc.dupe(u8, tokens[item_tokens.start].text);
    defer alloc.free(parsed_field);
    const resolved = try binder.resolveRowExpressionFieldAlloc(
        alloc,
        type_context.schema,
        type_context.joined_source_schema,
        parsed_field,
        &.{},
        &.{},
        &.{},
        &.{},
        type_context.defer_row_expression_field_validation,
        .row,
    );
    var field_transferred = false;
    errdefer if (!field_transferred) alloc.free(resolved.field);
    const projected: db_mod.types.RelationalRowsExpression = .{
        .kind = .field,
        .field = resolved.field,
        .field_source = resolved.source,
    };
    field_transferred = true;
    errdefer freeExpression(alloc, projected);

    const alias_tokens = if (expression.subquery_projection_items.alias_name_items.len == 1)
        expression.subquery_projection_items.alias_name_items[0]
    else
        null;
    const output = if (alias_tokens) |alias_range| blk: {
        if (alias_range.end != alias_range.start + 1 or alias_range.end > tokens.len) return error.UnsupportedSqlShape;
        break :blk try alloc.dupe(u8, tokens[alias_range.start].text);
    } else if (projected.kind == .field and projected.field.len != 0)
        try alloc.dupe(u8, projected.field)
    else
        try alloc.dupe(u8, expr_type.rowExpressionDefaultOutputName(projected.kind));
    errdefer alloc.free(output);

    query.select_all = false;
    if (projected.kind == .field and std.mem.eql(u8, output, projected.field)) {
        const select = try alloc.alloc([]const u8, 1);
        errdefer alloc.free(select);
        select[0] = try alloc.dupe(u8, projected.field);
        query.select = select;
        freeExpression(alloc, projected);
    } else {
        const projections = try alloc.alloc(db_mod.types.RelationalRowsExpressionProjection, 1);
        errdefer alloc.free(projections);
        projections[0] = .{
            .output = try alloc.dupe(u8, output),
            .expression = projected,
        };
        query.expressions = projections;
    }
    return output;
}

fn parseGeneratedSubqueryWhereItemAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    item_tokens: generated_parser.GeneratedSqlTokenRange,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    type_context: expr_type.RowExpressionTypeContext,
    predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
    json_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate),
    json_path_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate),
    json_path_exists: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate),
    array_any: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate),
    array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate),
    array_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate),
    in_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate),
    text_patterns: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate),
    or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    access_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
    access_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
    expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
    expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    expression_array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate),
    subquery_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsSubqueryPredicate),
    realtime_ns: u64,
    fixed_binary_hooks: expr_row_parse.FixedBinaryRowExpressionParserOptions,
    bare_boolean_hooks: expr_predicate.BareBooleanWhereExpressionParserOptions,
    expression_alternatives_hooks: expr_where_condition.ExpressionWhereConditionAlternativesParserOptions,
    expression_condition_hooks: expr_where_condition.ExpressionWhereConditionsParserOptions,
    available_ctes: []const db_mod.types.RelationalRowsCte,
    generated_expression_ast: *const generated_parser.GeneratedSqlExpressionAst,
) !void {
    if (item_tokens.start >= item_tokens.end or item_tokens.end > tokens.len) return error.UnsupportedSqlShape;
    var item_pos = item_tokens.start;
    try parseWhereAlloc(
        alloc,
        tokens[0..item_tokens.end],
        &item_pos,
        params,
        schema,
        type_context,
        &.{},
        &.{},
        false,
        predicates,
        json_contains,
        json_path_eq,
        json_path_exists,
        array_any,
        array_contains,
        array_eq,
        in_predicates,
        text_patterns,
        or_predicates,
        not_predicates,
        access_or_predicates,
        access_not_predicates,
        expression_predicates,
        expression_or_predicates,
        expression_not_predicates,
        expression_array_contains,
        subquery_predicates,
        realtime_ns,
        fixed_binary_hooks,
        bare_boolean_hooks,
        expression_alternatives_hooks,
        expression_condition_hooks,
        available_ctes,
        generated_expression_ast,
    );
    if (item_pos != item_tokens.end) return error.UnsupportedSqlShape;
}

fn parseGeneratedSubqueryRequestAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    type_context: expr_type.RowExpressionTypeContext,
    available_ctes: []const db_mod.types.RelationalRowsCte,
    expression: *const generated_parser.GeneratedSqlExpressionAst,
    need_output: bool,
    realtime_ns: u64,
    fixed_binary_hooks: expr_row_parse.FixedBinaryRowExpressionParserOptions,
    bare_boolean_hooks: expr_predicate.BareBooleanWhereExpressionParserOptions,
    expression_alternatives_hooks: expr_where_condition.ExpressionWhereConditionAlternativesParserOptions,
    expression_condition_hooks: expr_where_condition.ExpressionWhereConditionsParserOptions,
) anyerror!ParsedGeneratedSubqueryRequest {
    if (expression.subquery_read_kind != .query or
        expression.subquery_set_operation_tokens != null or
        !generatedSubqueryTailIsLowerable(expression.subquery_tail)) return error.UnsupportedSqlShape;
    _ = expression.subquery_select_tokens orelse return error.UnsupportedSqlShape;
    var query = db_mod.types.RelationalRowsQueryRequest{ .select_all = true };
    errdefer query.deinit(alloc);
    const subquery_type_context = try generatedSubquerySourceContextAlloc(
        alloc,
        tokens,
        schema,
        type_context,
        available_ctes,
        expression,
        &query,
    );
    const source_tokens = expression.subquery_source_tokens orelse return error.UnsupportedSqlShape;
    var source_pos = source_tokens.start;
    const source_table = try plan_mod.parseTableAliasAlloc(alloc, tokens, &source_pos);
    defer plan_mod.freeTableAlias(alloc, source_table);
    if (source_pos != source_tokens.end) return error.UnsupportedSqlShape;

    var correlations = std.ArrayListUnmanaged(db_mod.types.RelationalRowsLateralCorrelation).empty;
    errdefer {
        plan_mod.freeLateralCorrelations(alloc, correlations.items);
        correlations.deinit(alloc);
    }
    const output_field = if (need_output)
        try parseGeneratedSubqueryProjectionAlloc(alloc, tokens, expression, subquery_type_context, &query)
    else
        "";
    errdefer if (output_field.len > 0) alloc.free(output_field);

    if (expression.subquery_where_tokens) |where_tokens| {
        const where_expression = expression.subquery_where_expression orelse return error.UnsupportedSqlShape;
        const where_expression_tokens = where_expression.tokens orelse return error.UnsupportedSqlShape;
        if (!generatedTokenRangeEqual(where_expression_tokens, where_tokens)) return error.UnsupportedSqlShape;

        var predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
        errdefer {
            freeRelationalChecks(alloc, predicates.items);
            predicates.deinit(alloc);
        }
        var json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
        errdefer {
            freeJsonContains(alloc, json_contains.items);
            json_contains.deinit(alloc);
        }
        var json_path_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate).empty;
        errdefer {
            freeJsonPathEq(alloc, json_path_eq.items);
            json_path_eq.deinit(alloc);
        }
        var json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
        errdefer {
            freeJsonPathExists(alloc, json_path_exists.items);
            json_path_exists.deinit(alloc);
        }
        var array_any = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate).empty;
        errdefer {
            freeArrayAny(alloc, array_any.items);
            array_any.deinit(alloc);
        }
        var array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
        errdefer {
            freeArrayContains(alloc, array_contains.items);
            array_contains.deinit(alloc);
        }
        var array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
        errdefer {
            freeArrayEq(alloc, array_eq.items);
            array_eq.deinit(alloc);
        }
        var in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
        errdefer {
            freeInPredicates(alloc, in_predicates.items);
            in_predicates.deinit(alloc);
        }
        var text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
        errdefer {
            freeTextPatterns(alloc, text_patterns.items);
            text_patterns.deinit(alloc);
        }
        var or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
        errdefer {
            freePredicateGroups(alloc, or_predicates.items);
            or_predicates.deinit(alloc);
        }
        var not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
        errdefer {
            freePredicateGroups(alloc, not_predicates.items);
            not_predicates.deinit(alloc);
        }
        var access_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
        errdefer {
            freeAccessPredicateGroups(alloc, access_or_predicates.items);
            access_or_predicates.deinit(alloc);
        }
        var access_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
        errdefer {
            freeAccessPredicateGroups(alloc, access_not_predicates.items);
            access_not_predicates.deinit(alloc);
        }
        var expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
        errdefer {
            freeExpressionConditions(alloc, expression_predicates.items);
            expression_predicates.deinit(alloc);
        }
        var expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
        errdefer {
            freeExpressionPredicateGroups(alloc, expression_or_predicates.items);
            expression_or_predicates.deinit(alloc);
        }
        var expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
        errdefer {
            freeExpressionPredicateGroups(alloc, expression_not_predicates.items);
            expression_not_predicates.deinit(alloc);
        }
        var expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
        errdefer {
            freeExpressionArrayContains(alloc, expression_array_contains.items);
            expression_array_contains.deinit(alloc);
        }
        var subquery_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsSubqueryPredicate).empty;
        errdefer {
            freeSubqueryPredicates(alloc, subquery_predicates.items);
            subquery_predicates.deinit(alloc);
        }

        if (where_expression.kind == .logical_and) {
            const condition_items = where_expression.boolean_condition_items;
            if (condition_items.items.len != condition_items.count or condition_items.expressions.len != condition_items.count) return error.UnsupportedSqlShape;
            for (condition_items.expressions, 0..) |*condition_expression, condition_index| {
                const condition_tokens = condition_items.items[condition_index];
                const condition_expression_tokens = condition_expression.tokens orelse return error.UnsupportedSqlShape;
                if (!generatedTokenRangeEqual(condition_expression_tokens, condition_tokens)) return error.UnsupportedSqlShape;
                const correlation = try generatedSubqueryCorrelationWhereAlloc(
                    alloc,
                    tokens,
                    type_context.schema,
                    subquery_type_context.schema,
                    source_table,
                    condition_expression,
                );
                if (correlation) |value| {
                    try appendGeneratedSubqueryCorrelationAlloc(alloc, &correlations, value);
                    continue;
                }
                try parseGeneratedSubqueryWhereItemAlloc(
                    alloc,
                    tokens,
                    condition_tokens,
                    params,
                    schema,
                    subquery_type_context,
                    &predicates,
                    &json_contains,
                    &json_path_eq,
                    &json_path_exists,
                    &array_any,
                    &array_contains,
                    &array_eq,
                    &in_predicates,
                    &text_patterns,
                    &or_predicates,
                    &not_predicates,
                    &access_or_predicates,
                    &access_not_predicates,
                    &expression_predicates,
                    &expression_or_predicates,
                    &expression_not_predicates,
                    &expression_array_contains,
                    &subquery_predicates,
                    realtime_ns,
                    fixed_binary_hooks,
                    bare_boolean_hooks,
                    expression_alternatives_hooks,
                    expression_condition_hooks,
                    available_ctes,
                    condition_expression,
                );
            }
        } else if (try generatedSubqueryCorrelationWhereAlloc(
            alloc,
            tokens,
            type_context.schema,
            subquery_type_context.schema,
            source_table,
            where_expression,
        )) |correlation| {
            try appendGeneratedSubqueryCorrelationAlloc(alloc, &correlations, correlation);
        } else {
            var where_pos = where_tokens.start;
            try parseWhereAlloc(
                alloc,
                tokens,
                &where_pos,
                params,
                schema,
                subquery_type_context,
                &.{},
                &.{},
                false,
                &predicates,
                &json_contains,
                &json_path_eq,
                &json_path_exists,
                &array_any,
                &array_contains,
                &array_eq,
                &in_predicates,
                &text_patterns,
                &or_predicates,
                &not_predicates,
                &access_or_predicates,
                &access_not_predicates,
                &expression_predicates,
                &expression_or_predicates,
                &expression_not_predicates,
                &expression_array_contains,
                &subquery_predicates,
                realtime_ns,
                fixed_binary_hooks,
                bare_boolean_hooks,
                expression_alternatives_hooks,
                expression_condition_hooks,
                available_ctes,
                expression.subquery_where_expression,
            );
            if (where_pos != where_tokens.end) return error.UnsupportedSqlShape;
        }
        query.predicates = try predicates.toOwnedSlice(alloc);
        query.json_contains = try json_contains.toOwnedSlice(alloc);
        query.json_path_eq = try json_path_eq.toOwnedSlice(alloc);
        query.json_path_exists = try json_path_exists.toOwnedSlice(alloc);
        query.array_any = try array_any.toOwnedSlice(alloc);
        query.array_contains = try array_contains.toOwnedSlice(alloc);
        query.array_eq = try array_eq.toOwnedSlice(alloc);
        query.in_predicates = try in_predicates.toOwnedSlice(alloc);
        query.text_patterns = try text_patterns.toOwnedSlice(alloc);
        query.or_predicates = try or_predicates.toOwnedSlice(alloc);
        query.not_predicates = try not_predicates.toOwnedSlice(alloc);
        query.access_or_predicates = try access_or_predicates.toOwnedSlice(alloc);
        query.access_not_predicates = try access_not_predicates.toOwnedSlice(alloc);
        query.expression_predicates = try expression_predicates.toOwnedSlice(alloc);
        query.expression_or_predicates = try expression_or_predicates.toOwnedSlice(alloc);
        query.expression_not_predicates = try expression_not_predicates.toOwnedSlice(alloc);
        query.expression_array_contains = try expression_array_contains.toOwnedSlice(alloc);
        query.subquery_predicates = try subquery_predicates.toOwnedSlice(alloc);
    }

    const out = ParsedGeneratedSubqueryRequest{
        .query = query,
        .output_field = output_field,
        .correlations = try correlations.toOwnedSlice(alloc),
    };
    query = .{};
    correlations = .empty;
    return out;
}

fn parseGeneratedSubqueryWherePredicateAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    type_context: expr_type.RowExpressionTypeContext,
    available_ctes: []const db_mod.types.RelationalRowsCte,
    subquery_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsSubqueryPredicate),
    realtime_ns: u64,
    fixed_binary_hooks: expr_row_parse.FixedBinaryRowExpressionParserOptions,
    bare_boolean_hooks: expr_predicate.BareBooleanWhereExpressionParserOptions,
    expression_alternatives_hooks: expr_where_condition.ExpressionWhereConditionAlternativesParserOptions,
    expression_condition_hooks: expr_where_condition.ExpressionWhereConditionsParserOptions,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !bool {
    const expression = (try expr_subquery.generatedPredicateAt(tokens, pos.*, generated_expression_ast)) orelse return false;
    const expression_tokens = expression.tokens orelse return error.UnsupportedSqlShape;
    const need_output = switch (expression.kind) {
        .exists_subquery, .not_exists_subquery => false,
        else => true,
    };
    const right_expression = expression.right_expression orelse return error.UnsupportedSqlShape;
    var subquery = try parseGeneratedSubqueryRequestAlloc(
        alloc,
        tokens,
        params,
        schema,
        type_context,
        available_ctes,
        right_expression,
        need_output,
        realtime_ns,
        fixed_binary_hooks,
        bare_boolean_hooks,
        expression_alternatives_hooks,
        expression_condition_hooks,
    );
    errdefer subquery.deinit(alloc);
    const lhs = try generatedSubqueryLhsExpressionAlloc(alloc, tokens, expression, type_context, expression_condition_hooks);
    var lhs_transferred = false;
    errdefer if (!lhs_transferred) if (lhs) |value| freeExpression(alloc, value);
    const predicate = db_mod.types.RelationalRowsSubqueryPredicate{
        .kind = try expr_subquery.predicateKind(expression),
        .lhs = lhs,
        .op = try expr_subquery.comparisonOp(tokens, expression),
        .negated = expr_subquery.predicateNegated(expression),
        .quantifier = try expr_subquery.quantifier(tokens, expression),
        .query = subquery.query,
        .output_field = subquery.output_field,
        .correlations = subquery.correlations,
        .collation = null,
    };
    lhs_transferred = true;
    subquery.query = .{};
    subquery.output_field = "";
    subquery.correlations = &.{};
    try subquery_predicates.append(alloc, predicate);
    pos.* = expression_tokens.end;
    return true;
}

fn generatedProjectionAliasOutputAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    list: generated_parser.GeneratedSqlListAst,
    index: usize,
    item_range: generated_parser.GeneratedSqlTokenRange,
    expression_range: generated_parser.GeneratedSqlTokenRange,
) !?[]const u8 {
    if (list.alias_items.len != list.count or list.alias_name_items.len != list.count) return error.UnsupportedSqlShape;
    const alias_range = list.alias_items[index] orelse return null;
    const alias_name_range = list.alias_name_items[index] orelse return error.UnsupportedSqlShape;
    if (alias_range.start < expression_range.end or alias_range.end != item_range.end or alias_range.end > tokens.len) return error.UnsupportedSqlShape;
    if (alias_name_range.start < alias_range.start or alias_name_range.end != alias_range.end or alias_name_range.start >= alias_name_range.end) return error.UnsupportedSqlShape;
    if (tokens[alias_range.start].matchesKeywordTag(.as)) {
        if (alias_name_range.start != alias_range.start + 1) return error.UnsupportedSqlShape;
    } else if (alias_name_range.start != alias_range.start) {
        return error.UnsupportedSqlShape;
    }
    if (alias_name_range.end != alias_name_range.start + 1) return error.UnsupportedSqlShape;
    return try alloc.dupe(u8, tokens[alias_name_range.start].text);
}

fn parseGeneratedScalarSubquerySelectListAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    type_context: expr_type.RowExpressionTypeContext,
    available_ctes: []const db_mod.types.RelationalRowsCte,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
    realtime_ns: u64,
    fixed_binary_hooks: expr_row_parse.FixedBinaryRowExpressionParserOptions,
    bare_boolean_hooks: expr_predicate.BareBooleanWhereExpressionParserOptions,
    expression_alternatives_hooks: expr_where_condition.ExpressionWhereConditionAlternativesParserOptions,
    expression_condition_hooks: expr_where_condition.ExpressionWhereConditionsParserOptions,
) !?plan_mod.SelectList {
    const read = generated_read_ast orelse return null;
    const projection_tokens = read.projection_tokens orelse return null;
    if (projection_tokens.start != pos.*) return null;
    try expr_generated_validate.validateGeneratedProjectionListForClause(tokens, projection_tokens, read.projection_items);

    var has_scalar_subquery = false;
    for (read.projection_items.expressions) |expression| {
        if (expression.kind == .subquery) has_scalar_subquery = true;
    }
    if (!has_scalar_subquery) return null;
    if (read.projection_items.count != read.projection_items.items.len or
        read.projection_items.count != read.projection_items.expression_items.len or
        read.projection_items.count != read.projection_items.expressions.len) return error.UnsupportedSqlShape;

    var fields = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        strings.freeStringSlice(alloc, fields.items);
        fields.deinit(alloc);
    }
    var field_aliases = std.ArrayListUnmanaged(db_mod.types.RelationalRowsFieldAliasProjection).empty;
    errdefer {
        plan_mod.freeFieldAliasProjections(alloc, field_aliases.items);
        field_aliases.deinit(alloc);
    }
    var scalar_subqueries = std.ArrayListUnmanaged(db_mod.types.RelationalRowsScalarSubqueryProjection).empty;
    errdefer {
        for (scalar_subqueries.items) |projection| plan_mod.freeScalarSubqueryProjection(alloc, projection);
        scalar_subqueries.deinit(alloc);
    }
    var outputs = std.ArrayListUnmanaged(ast.SelectOutputRef).empty;
    errdefer outputs.deinit(alloc);

    for (read.projection_items.items, 0..) |item_range, index| {
        const expression = &read.projection_items.expressions[index];
        try expr_generated_validate.validateGeneratedExpressionPayloads(tokens, expression.*);

        const expression_range = read.projection_items.expression_items[index];
        const expression_tokens = expression.tokens orelse return error.UnsupportedSqlShape;
        if (!generatedTokenRangeEqual(expression_tokens, expression_range)) return error.UnsupportedSqlShape;
        if (expression_range.start < item_range.start or expression_range.end > item_range.end) return error.UnsupportedSqlShape;

        if (expression.kind == .token_range) {
            var field_pos = expression_range.start;
            const parsed_field = try expr_generated.parseRowExpressionFieldOwnedAlloc(
                alloc,
                tokens,
                &field_pos,
                type_context.schema,
                &.{},
                &.{},
                type_context.defer_row_expression_field_validation,
            );
            defer alloc.free(parsed_field);
            if (field_pos != expression_range.end) return error.UnsupportedSqlShape;
            const field = try binder.normalizeRowExpressionFieldAlloc(
                alloc,
                type_context.schema,
                parsed_field,
                &.{},
                &.{},
                type_context.defer_row_expression_field_validation,
            );
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            const alias = try generatedProjectionAliasOutputAlloc(alloc, tokens, read.projection_items, index, item_range, expression_range);
            var alias_transferred = false;
            errdefer if (!alias_transferred) if (alias) |output| alloc.free(output);
            if (alias) |output| {
                if (std.mem.eql(u8, output, field)) {
                    alloc.free(output);
                    alias_transferred = true;
                    try outputs.append(alloc, .{ .kind = .field, .index = fields.items.len });
                    try fields.append(alloc, field);
                    field_transferred = true;
                } else {
                    try outputs.append(alloc, .{ .kind = .field_alias, .index = field_aliases.items.len });
                    try field_aliases.append(alloc, .{ .field = field, .output = output });
                    field_transferred = true;
                    alias_transferred = true;
                }
            } else {
                if (item_range.end != expression_range.end) return error.UnsupportedSqlShape;
                try outputs.append(alloc, .{ .kind = .field, .index = fields.items.len });
                try fields.append(alloc, field);
                field_transferred = true;
            }
            continue;
        }
        if (expression.kind != .subquery) return error.UnsupportedSqlShape;

        const output = (try generatedProjectionAliasOutputAlloc(alloc, tokens, read.projection_items, index, item_range, expression_range)) orelse return error.UnsupportedSqlShape;
        var output_transferred = false;
        errdefer if (!output_transferred) alloc.free(output);

        var subquery = try parseGeneratedSubqueryRequestAlloc(
            alloc,
            tokens,
            params,
            schema,
            type_context,
            available_ctes,
            expression,
            true,
            realtime_ns,
            fixed_binary_hooks,
            bare_boolean_hooks,
            expression_alternatives_hooks,
            expression_condition_hooks,
        );
        errdefer subquery.deinit(alloc);

        const projection = db_mod.types.RelationalRowsScalarSubqueryProjection{
            .output = output,
            .query = subquery.query,
            .output_field = subquery.output_field,
        };
        subquery.query = .{};
        subquery.output_field = "";
        output_transferred = true;
        try outputs.append(alloc, .{ .kind = .scalar_subquery, .index = scalar_subqueries.items.len });
        try scalar_subqueries.append(alloc, projection);
    }

    try expr_projection.validateSelectListOutputs(schema, false, fields.items, &.{}, &.{}, &.{}, field_aliases.items, &.{}, scalar_subqueries.items);

    const owned_fields = try fields.toOwnedSlice(alloc);
    var fields_transferred = false;
    errdefer if (!fields_transferred) strings.freeStringSlice(alloc, owned_fields);
    const owned_field_aliases = try field_aliases.toOwnedSlice(alloc);
    var field_aliases_transferred = false;
    errdefer if (!field_aliases_transferred) plan_mod.freeFieldAliasProjections(alloc, owned_field_aliases);
    const owned_scalar_subqueries = try scalar_subqueries.toOwnedSlice(alloc);
    var scalar_transferred = false;
    errdefer if (!scalar_transferred) plan_mod.freeScalarSubqueryProjections(alloc, owned_scalar_subqueries);
    const owned_outputs = try outputs.toOwnedSlice(alloc);

    fields_transferred = true;
    field_aliases_transferred = true;
    pos.* = projection_tokens.end;
    scalar_transferred = true;
    return .{
        .fields = owned_fields,
        .field_aliases = owned_field_aliases,
        .scalar_subqueries = owned_scalar_subqueries,
        .outputs = owned_outputs,
    };
}

pub fn parseWhereAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    schema: runtime_schema.TableSchema,
    type_context: expr_type.RowExpressionTypeContext,
    field_expression_qualifiers: []const []const u8,
    returning_expression_qualifiers: []const []const u8,
    defer_row_expression_field_validation: bool,
    predicates: *std.ArrayListUnmanaged(runtime_schema.RelationalCheck),
    json_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate),
    json_path_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate),
    json_path_exists: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate),
    array_any: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate),
    array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate),
    array_eq: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate),
    in_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate),
    text_patterns: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate),
    or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup),
    access_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
    access_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup),
    expression_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition),
    expression_or_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    expression_not_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup),
    expression_array_contains: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate),
    subquery_predicates: *std.ArrayListUnmanaged(db_mod.types.RelationalRowsSubqueryPredicate),
    realtime_ns: u64,
    fixed_binary_hooks: expr_row_parse.FixedBinaryRowExpressionParserOptions,
    bare_boolean_hooks: expr_predicate.BareBooleanWhereExpressionParserOptions,
    expression_alternatives_hooks: expr_where_condition.ExpressionWhereConditionAlternativesParserOptions,
    expression_condition_hooks: expr_where_condition.ExpressionWhereConditionsParserOptions,
    available_ctes: []const db_mod.types.RelationalRowsCte,
    generated_expression_ast: ?*const generated_parser.GeneratedSqlExpressionAst,
) !void {
    if (try parseGeneratedSubqueryWherePredicateAlloc(
        alloc,
        tokens,
        pos,
        params,
        schema,
        type_context,
        available_ctes,
        subquery_predicates,
        realtime_ns,
        fixed_binary_hooks,
        bare_boolean_hooks,
        expression_alternatives_hooks,
        expression_condition_hooks,
        generated_expression_ast,
    )) return;
    if (expr_predicate.canParseBareBooleanWhereExpression(tokens, pos.*, schema)) {
        var generated_bare_boolean_hooks = bare_boolean_hooks;
        generated_bare_boolean_hooks.generated_expression_ast = generated_expression_ast;
        try expr_predicate.parseBareBooleanWhereExpressionAlloc(alloc, tokens, pos, type_context, expression_predicates, generated_bare_boolean_hooks);
        return;
    }
    if (parser.hasTopLevelOrBeforeTailToken(tokens, pos.*, expr_token.sqlWhereTailClauseKeywordToken)) {
        if (expr_predicate.whereTopLevelOrHasExpressionPredicateStart(tokens, pos.*)) {
            try expr_where_condition.parseExpressionOrWhereWithGeneratedAlloc(alloc, tokens, pos, params, type_context, defer_row_expression_field_validation, expression_or_predicates, expression_alternatives_hooks, generated_expression_ast);
        } else if (expr_predicate.whereTopLevelOrHasAccessPredicate(tokens, pos.*)) {
            try expr_predicate.parseAccessOrWhereAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, access_or_predicates, realtime_ns, generated_expression_ast);
        } else {
            try expr_predicate.parseScalarOrWhereAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, or_predicates, realtime_ns, generated_expression_ast);
        }
        return;
    }
    if (!expr_predicate.canParseAccessNotWhere(tokens, pos.*) and try expr_predicate.whereHasArrayOverlapPredicateAlloc(
        alloc,
        tokens,
        pos,
        schema,
        field_expression_qualifiers,
        returning_expression_qualifiers,
        defer_row_expression_field_validation,
    )) {
        try expr_predicate.parseAccessOrWhereAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, access_or_predicates, realtime_ns, generated_expression_ast);
        return;
    }
    while (true) {
        if (expr_predicate.canParseScalarNotWhere(tokens, pos.*)) {
            const generated_condition_expression = try expr_generated_validate.generatedPredicateExpressionAtStart(tokens, pos.*, generated_expression_ast);
            try expr_predicate.parseScalarNotWhereAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, not_predicates, realtime_ns, generated_condition_expression);
        } else if (expr_predicate.canParseExpressionNotWhere(tokens, pos.*)) {
            try expr_where_condition.parseExpressionNotWhereWithGeneratedAlloc(alloc, tokens, pos, params, type_context, defer_row_expression_field_validation, expression_not_predicates, expression_alternatives_hooks, generated_expression_ast);
        } else if (expr_predicate.canParseAccessNotWhere(tokens, pos.*)) {
            const generated_condition_expression = try expr_generated_validate.generatedPredicateExpressionAtStart(tokens, pos.*, generated_expression_ast);
            try expr_predicate.parseAccessNotWhereAlloc(alloc, tokens, pos, params, schema, field_expression_qualifiers, returning_expression_qualifiers, defer_row_expression_field_validation, access_not_predicates, realtime_ns, generated_condition_expression);
        } else if (expr_token.peekStringToArrayFunctionCall(tokens, pos.*)) {
            if (expr_predicate.stringToArrayPredicateIsContainment(tokens, pos.*)) {
                const operator_token_index = expr_predicate.stringToArrayContainmentOperatorTokenIndex(tokens, pos.*) orelse return error.UnsupportedSqlShape;
                try expr_generated_validate.validateGeneratedSingleOperatorPredicateIdentity(try expr_generated_validate.generatedPredicateExpressionAtStart(tokens, pos.*, generated_expression_ast), .contains, tokens, operator_token_index);
                const predicate = try expr_predicate.parseExpressionArrayContainsPredicateAlloc(
                    alloc,
                    tokens,
                    pos,
                    params,
                    type_context,
                    fixed_binary_hooks,
                );
                var predicate_transferred = false;
                errdefer if (!predicate_transferred) freeExpressionArrayContainsOne(alloc, predicate);
                try expression_array_contains.append(alloc, predicate);
                predicate_transferred = true;
            } else {
                try expr_where_condition.parseExpressionWhereConditionsAlloc(
                    alloc,
                    tokens,
                    pos,
                    params,
                    type_context,
                    defer_row_expression_field_validation,
                    expression_predicates,
                    expression_or_predicates,
                    expression_not_predicates,
                    expression_condition_hooks,
                );
            }
        } else if (expr_predicate.canParseBareBooleanWhereExpression(tokens, pos.*, schema)) {
            var generated_bare_boolean_hooks = bare_boolean_hooks;
            generated_bare_boolean_hooks.generated_expression_ast = try expr_generated_validate.generatedPredicateExpressionAtStart(tokens, pos.*, generated_expression_ast);
            try expr_predicate.parseBareBooleanWhereExpressionAlloc(alloc, tokens, pos, type_context, expression_predicates, generated_bare_boolean_hooks);
        } else if (expr_predicate.parenthesizedWhereHasTopLevelOr(tokens, pos.*)) {
            try expr_where_condition.parseExpressionOrWhereWithGeneratedAlloc(alloc, tokens, pos, params, type_context, defer_row_expression_field_validation, expression_or_predicates, expression_alternatives_hooks, generated_expression_ast);
        } else if (try expr_predicate.canParseExpressionWhereCondition(
            alloc,
            tokens,
            pos.*,
            schema,
            field_expression_qualifiers,
            returning_expression_qualifiers,
            defer_row_expression_field_validation,
        )) {
            var expression_condition_hooks_with_generated = expression_condition_hooks;
            expression_condition_hooks_with_generated.generated_expression_ast = try expr_generated_validate.generatedPredicateExpressionAtStart(tokens, pos.*, generated_expression_ast);
            try expr_where_condition.parseExpressionWhereConditionsAlloc(
                alloc,
                tokens,
                pos,
                params,
                type_context,
                defer_row_expression_field_validation,
                expression_predicates,
                expression_or_predicates,
                expression_not_predicates,
                expression_condition_hooks_with_generated,
            );
        } else {
            const generated_atom_expression = try expr_generated_validate.generatedPredicateExpressionAtStart(tokens, pos.*, generated_expression_ast);
            try expr_predicate.parseWhereAtomAlloc(
                alloc,
                tokens,
                pos,
                params,
                schema,
                field_expression_qualifiers,
                returning_expression_qualifiers,
                defer_row_expression_field_validation,
                predicates,
                json_contains,
                json_path_eq,
                json_path_exists,
                array_any,
                array_contains,
                array_eq,
                in_predicates,
                text_patterns,
                or_predicates,
                false,
                realtime_ns,
                generated_atom_expression,
            );
        }
        if (!parser.matchKeyword(tokens, pos, "and")) break;
    }
}

pub const RecursiveCteMemberProjectionExpressionParserOptions = struct {
    type_context: expr_type.RowExpressionTypeContext,
    row_expression_hooks: expr_row_parse.RowExpressionParserHooks,
    arithmetic_hooks: expr_row_parse.ArithmeticExpressionParserHooks,
    variadic_hooks: expr_row_parse.VariadicRowExpressionParserHooks,
};

pub fn parseRecursiveCteMemberProjectionExpressionAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: RecursiveCteMemberProjectionExpressionParserOptions,
) !plan_mod.RecursiveCteMemberProjectionExpression {
    const expression = try expr_row_parse.parseRowExpressionAlloc(
        alloc,
        tokens,
        pos,
        options.type_context,
        options.row_expression_hooks,
        options.arithmetic_hooks,
        options.variadic_hooks,
    );
    const default_output = if (expression.kind == .field and expression.field.len != 0)
        expression.field
    else
        expr_type.rowExpressionDefaultOutputName(expression.kind);
    return .{
        .expression = expression,
        .default_output = default_output,
    };
}

pub const RecursiveCteMemberJoinOnParserOptions = struct {
    params: []const value_mod.SqlValue = &.{},
    schema: runtime_schema.TableSchema,
    joined_source_schema: ?runtime_schema.TableSchema,
    join_type: db_mod.types.RelationalRowsJoinType,
    left_alias: []const u8,
    right_alias: []const u8,
    string_to_array_predicate_is_containment: bool = false,
    expression_where_options: JoinedMutationExpressionWhereConditionParserOptions,
    realtime_ns: u64,
};

pub fn parseRecursiveCteMemberJoinOnAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: RecursiveCteMemberJoinOnParserOptions,
) ![]const db_mod.types.RelationalRowsJoinOn {
    var on = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJoinOn).empty;
    errdefer {
        plan_mod.freeJoinOn(alloc, on.items);
        on.deinit(alloc);
    }
    var left_predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    defer {
        freeRelationalChecks(alloc, left_predicates.items);
        left_predicates.deinit(alloc);
    }
    var right_predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    defer {
        freeRelationalChecks(alloc, right_predicates.items);
        right_predicates.deinit(alloc);
    }
    var on_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    defer {
        freeExpressionConditions(alloc, on_expression_predicates.items);
        on_expression_predicates.deinit(alloc);
    }
    var on_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    defer {
        freeExpressionPredicateGroups(alloc, on_expression_or_predicates.items);
        on_expression_or_predicates.deinit(alloc);
    }
    var on_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    defer {
        freeExpressionPredicateGroups(alloc, on_expression_not_predicates.items);
        on_expression_not_predicates.deinit(alloc);
    }
    var on_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    defer {
        freeExpressionArrayContains(alloc, on_expression_array_contains.items);
        on_expression_array_contains.deinit(alloc);
    }

    var targets = JoinOnPredicateTargets{
        .on = &on,
        .left_predicates = &left_predicates,
        .right_predicates = &right_predicates,
        .on_expression_predicates = &on_expression_predicates,
        .on_expression_or_predicates = &on_expression_or_predicates,
        .on_expression_not_predicates = &on_expression_not_predicates,
        .on_expression_array_contains = &on_expression_array_contains,
    };
    try parseJoinOnAlloc(
        alloc,
        tokens,
        pos,
        options.params,
        options.schema,
        options.joined_source_schema,
        options.join_type,
        options.left_alias,
        options.right_alias,
        options.string_to_array_predicate_is_containment,
        &targets,
        options.expression_where_options,
        options.realtime_ns,
        null,
    );
    if (left_predicates.items.len != 0 or right_predicates.items.len != 0 or
        on_expression_predicates.items.len != 0 or on_expression_or_predicates.items.len != 0 or
        on_expression_not_predicates.items.len != 0 or on_expression_array_contains.items.len != 0)
    {
        return error.UnsupportedSqlShape;
    }
    return try on.toOwnedSlice(alloc);
}

fn parenthesizedExpressionOrWhereCanStartAt(tokens: []const Token, pos: usize) bool {
    if (pos >= tokens.len or tokens[pos].kind != .lparen) return false;
    const inner = parser.predicateStartIndexAfterOpenParens(tokens, pos);
    if (!expr_parse.expressionCanStartAt(tokens, inner) and !expr_operator.jsonExtractExpressionPredicateCanStartAt(tokens, inner)) return false;

    var depth: usize = 0;
    var index = pos;
    while (index < tokens.len) : (index += 1) {
        const token = tokens[index];
        switch (token.kind) {
            .lparen => depth += 1,
            .rparen => {
                if (depth == 0) return false;
                depth -= 1;
                if (depth == 0) return false;
            },
            .identifier => if (depth == 1 and token.matchesKeywordTag(.@"or")) return true,
            .semicolon => return false,
            else => {},
        }
    }
    return false;
}

pub fn parseJoinedMutationExpressionWhereConditionWithContextAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    side: expr_predicate.JoinedMutationExpressionSide,
    targets: *JoinWherePredicateTargets,
    target_alias: []const u8,
    source_alias: []const u8,
    options: JoinedMutationExpressionWhereConditionParserOptions,
) !void {
    const previous_select_context = options.select_context_hooks.get_context(options.select_context_hooks.ptr);
    const previous_joined_context = options.joined_context_hooks.get_context(options.joined_context_hooks.ptr);
    const target_qualifiers = [_][]const u8{target_alias};
    const source_qualifiers = [_][]const u8{source_alias};
    const single_side = switch (side) {
        .single => |single| single,
        .mixed => null,
    };

    var select_context = previous_select_context;
    if (single_side) |single| {
        const qualifiers = [_][]const u8{if (single == .left) target_alias else source_alias};
        select_context.schema = if (single == .left) previous_select_context.schema else options.joined_source_schema orelse previous_select_context.schema;
        select_context.field_expression_qualifiers = qualifiers[0..];
    }
    select_context.defer_row_expression_field_validation = true;
    options.select_context_hooks.set_context(options.select_context_hooks.ptr, select_context);
    defer options.select_context_hooks.set_context(options.select_context_hooks.ptr, previous_select_context);

    var restore_joined_context = false;
    if (single_side == null) {
        var joined_context = previous_joined_context;
        joined_context.joined_target_expression_qualifiers = target_qualifiers[0..];
        joined_context.joined_source_expression_qualifiers = source_qualifiers[0..];
        joined_context.defer_row_expression_field_validation = true;
        options.joined_context_hooks.set_context(options.joined_context_hooks.ptr, joined_context);
        restore_joined_context = true;
    }
    defer if (restore_joined_context) options.joined_context_hooks.set_context(options.joined_context_hooks.ptr, previous_joined_context);

    const expression_predicates = if (single_side) |single| if (single == .left) targets.left_expression_predicates else targets.right_expression_predicates else targets.match_expression_predicates;
    const expression_or_predicates = if (single_side) |single| if (single == .left) targets.left_expression_or_predicates else targets.right_expression_or_predicates else targets.match_expression_or_predicates;
    const expression_not_predicates = if (single_side) |single| if (single == .left) targets.left_expression_not_predicates else targets.right_expression_not_predicates else targets.match_expression_not_predicates;
    const expression_array_contains = if (single_side) |single| if (single == .left) targets.left_expression_array_contains else targets.right_expression_array_contains else targets.match_expression_array_contains;

    var restore_expression_select_context = false;
    var previous_expression_select_context: expr_row_parse.SelectParserContext = undefined;
    if (options.expression_condition_hooks.select_context_hooks) |hooks| {
        previous_expression_select_context = hooks.get_context(hooks.ptr);
        hooks.set_context(hooks.ptr, select_context);
        restore_expression_select_context = true;
    }
    defer if (restore_expression_select_context) if (options.expression_condition_hooks.select_context_hooks) |hooks| hooks.set_context(hooks.ptr, previous_expression_select_context);

    var restore_alternatives_select_context = false;
    var previous_alternatives_select_context: expr_row_parse.SelectParserContext = undefined;
    if (options.alternatives_hooks.select_context_hooks) |hooks| {
        previous_alternatives_select_context = hooks.get_context(hooks.ptr);
        hooks.set_context(hooks.ptr, select_context);
        restore_alternatives_select_context = true;
    }
    defer if (restore_alternatives_select_context) if (options.alternatives_hooks.select_context_hooks) |hooks| hooks.set_context(hooks.ptr, previous_alternatives_select_context);

    var restore_expression_joined_context = false;
    var previous_expression_joined_context: expr_row_parse.JoinedExpressionParserContext = undefined;
    var restore_alternatives_joined_context = false;
    var previous_alternatives_joined_context: expr_row_parse.JoinedExpressionParserContext = undefined;
    if (single_side == null) {
        var joined_context = previous_joined_context;
        joined_context.joined_target_expression_qualifiers = target_qualifiers[0..];
        joined_context.joined_source_expression_qualifiers = source_qualifiers[0..];
        joined_context.defer_row_expression_field_validation = true;
        if (options.expression_condition_hooks.joined_context_hooks) |hooks| {
            previous_expression_joined_context = hooks.get_context(hooks.ptr);
            hooks.set_context(hooks.ptr, joined_context);
            restore_expression_joined_context = true;
        }
        if (options.alternatives_hooks.joined_context_hooks) |hooks| {
            previous_alternatives_joined_context = hooks.get_context(hooks.ptr);
            hooks.set_context(hooks.ptr, joined_context);
            restore_alternatives_joined_context = true;
        }
    }
    defer if (restore_expression_joined_context) if (options.expression_condition_hooks.joined_context_hooks) |hooks| hooks.set_context(hooks.ptr, previous_expression_joined_context);
    defer if (restore_alternatives_joined_context) if (options.alternatives_hooks.joined_context_hooks) |hooks| hooks.set_context(hooks.ptr, previous_alternatives_joined_context);

    var expression_type_context = options.select_context_hooks.row_expression_type_context(options.select_context_hooks.ptr);
    expression_type_context.defer_row_expression_field_validation = true;

    if (expr_predicate.canParseExpressionNotWhere(tokens, pos.*)) {
        try expr_where_condition.parseExpressionNotWhereWithGeneratedAlloc(
            alloc,
            tokens,
            pos,
            options.params,
            expression_type_context,
            true,
            expression_not_predicates,
            options.alternatives_hooks,
            options.generated_expression_ast,
        );
        return;
    }

    if (expr_predicate.stringToArrayPredicateIsContainment(tokens, pos.*)) {
        const operator_token_index = expr_predicate.stringToArrayContainmentOperatorTokenIndex(tokens, pos.*) orelse return error.UnsupportedSqlShape;
        try expr_generated_validate.validateGeneratedSingleOperatorPredicateIdentity(options.generated_expression_ast, .contains, tokens, operator_token_index);
        const predicate = try expr_predicate.parseExpressionArrayContainsPredicateAlloc(alloc, tokens, pos, options.params, expression_type_context, options.fixed_binary_hooks);
        var predicate_transferred = false;
        errdefer if (!predicate_transferred) freeExpressionArrayContainsOne(alloc, predicate);
        try expression_array_contains.append(alloc, predicate);
        predicate_transferred = true;
        return;
    }

    if (parser.hasTopLevelOrBeforeTailToken(tokens, pos.*, expr_token.sqlWhereTailClauseKeywordToken) or parenthesizedExpressionOrWhereCanStartAt(tokens, pos.*)) {
        try expr_where_condition.parseExpressionOrWhereWithGeneratedAlloc(
            alloc,
            tokens,
            pos,
            options.params,
            expression_type_context,
            true,
            expression_or_predicates,
            options.alternatives_hooks,
            options.generated_expression_ast,
        );
        return;
    }

    const current_context = options.select_context_hooks.get_context(options.select_context_hooks.ptr);
    if (expr_predicate.canParseBareBooleanWhereExpression(tokens, pos.*, current_context.schema)) {
        var generated_bare_boolean_hooks = options.bare_boolean_hooks;
        generated_bare_boolean_hooks.generated_expression_ast = options.generated_expression_ast;
        try expr_predicate.parseBareBooleanWhereExpressionAlloc(alloc, tokens, pos, expression_type_context, expression_predicates, generated_bare_boolean_hooks);
        return;
    }

    try expr_where_condition.parseExpressionWhereConditionsAlloc(
        alloc,
        tokens,
        pos,
        options.params,
        expression_type_context,
        true,
        expression_predicates,
        expression_or_predicates,
        expression_not_predicates,
        blk: {
            var expression_condition_hooks = options.expression_condition_hooks;
            expression_condition_hooks.generated_expression_ast = options.generated_expression_ast;
            break :blk expression_condition_hooks;
        },
    );
}

fn parseIdentifierOwnedAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
) ![]const u8 {
    const token = parser.matchToken(tokens, pos, .identifier) orelse return error.UnsupportedSqlShape;
    return try alloc.dupe(u8, token.text);
}

const DirectGraphTableFunctionSource = struct {
    cte: db_mod.types.RelationalRowsCte,
    table_ref: plan_mod.TableAlias,
    function_start: usize,
    source_end: usize,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        var cte = self.cte;
        cte.deinit(alloc);
        plan_mod.freeTableAlias(alloc, self.table_ref);
        self.* = undefined;
    }
};

const GeneratedGraphTableFunctionSource = struct {
    antfly_item: generated_parser.GeneratedSqlAntflyTableFunctionAst,
    graph_item: generated_parser.GeneratedSqlGraphTableFunctionAst,
};

fn cloneTableAliasAlloc(alloc: std.mem.Allocator, value: plan_mod.TableAlias) !plan_mod.TableAlias {
    const name = try alloc.dupe(u8, value.name);
    var name_transferred = false;
    errdefer if (!name_transferred) alloc.free(name);
    const alias = try alloc.dupe(u8, value.alias);
    var alias_transferred = false;
    errdefer if (!alias_transferred) alloc.free(alias);
    name_transferred = true;
    alias_transferred = true;
    return .{ .name = name, .alias = alias };
}

fn generatedGraphTableFunctionSourceAt(
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
    function_start: usize,
) ?GeneratedGraphTableFunctionSource {
    const read = generated_read_ast orelse return null;
    for (read.source_graph_function_items) |graph_item| {
        if (graph_item.tokens.start != function_start) continue;
        for (read.source_antfly_function_items) |antfly_item| {
            if (antfly_item.tokens.start == graph_item.tokens.start and
                antfly_item.tokens.end == graph_item.tokens.end)
            {
                return .{
                    .antfly_item = antfly_item,
                    .graph_item = graph_item,
                };
            }
        }
    }
    return null;
}

fn parseGraphTableFunctionSourceAtAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    function_start: usize,
    default_alias: []const u8,
    available_ctes: []const db_mod.types.RelationalRowsCte,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
) !?DirectGraphTableFunctionSource {
    if (function_start + 1 >= tokens.len) return null;
    if (tokens[function_start].kind != .identifier or tokens[function_start + 1].kind != .lparen) return null;
    const function = query_function.antflyQueryFunctionFromSqlToken(tokens[function_start]) orelse return null;
    switch (function) {
        .graph_traverse, .graph_neighbors, .graph_shortest_path, .graph_k_shortest_paths, .graph_match => {},
        .graph_metric, .graph_metric_rerank => {},
        else => return null,
    }
    const close_index = parser.findMatchingRParenIndex(tokens, function_start + 1) orelse return error.UnsupportedSqlShape;
    const function_end = close_index + 1;

    var alias_pos = function_end;
    const explicit_alias = parser.matchKeywordTag(tokens, &alias_pos, .as);
    const alias_source = if (explicit_alias) blk: {
        if (alias_pos >= tokens.len or tokens[alias_pos].kind != .identifier) return error.UnsupportedSqlShape;
        const alias = tokens[alias_pos].text;
        alias_pos += 1;
        break :blk alias;
    } else if (alias_pos < tokens.len and
        tokens[alias_pos].kind == .identifier and
        !plan_mod.selectSourceAliasTailKeyword(tokens[alias_pos]))
    blk: {
        const alias = tokens[alias_pos].text;
        alias_pos += 1;
        break :blk alias;
    } else default_alias;

    if (plan_mod.findCteByName(available_ctes, alias_source) != null) return error.UnsupportedSqlShape;

    const generated_source = generatedGraphTableFunctionSourceAt(generated_read_ast, function_start) orelse return error.UnsupportedSqlShape;
    const table_function = try query_function.lowerAntflyGraphTableFunctionGeneratedAstAlloc(alloc, tokens, generated_source.antfly_item, generated_source.graph_item);
    var table_function_transferred = false;
    errdefer if (!table_function_transferred) {
        var owned = table_function;
        owned.deinit(alloc);
    };

    const cte_name = try alloc.dupe(u8, alias_source);
    var cte_name_transferred = false;
    errdefer if (!cte_name_transferred) alloc.free(cte_name);
    const table_name = try alloc.dupe(u8, alias_source);
    var table_name_transferred = false;
    errdefer if (!table_name_transferred) alloc.free(table_name);
    const table_alias = try alloc.dupe(u8, alias_source);
    var table_alias_transferred = false;
    errdefer if (!table_alias_transferred) alloc.free(table_alias);

    table_function_transferred = true;
    cte_name_transferred = true;
    table_name_transferred = true;
    table_alias_transferred = true;
    return .{
        .cte = .{
            .name = cte_name,
            .table_function = table_function,
        },
        .table_ref = .{
            .name = table_name,
            .alias = table_alias,
        },
        .function_start = function_start,
        .source_end = alias_pos,
    };
}

fn parseDirectGraphTableFunctionSourceAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    select_body_pos: usize,
    available_ctes: []const db_mod.types.RelationalRowsCte,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
) !?DirectGraphTableFunctionSource {
    const from_index = parser.findTopLevelKeywordFromIndex(tokens, select_body_pos, "from") orelse return null;
    return try parseGraphTableFunctionSourceAtAlloc(alloc, tokens, from_index + 1, "__antfly_graph_table_function", available_ctes, generated_read_ast);
}

fn appendGeneratedQualifierIfMissingAlloc(
    alloc: std.mem.Allocator,
    qualifiers: *std.ArrayListUnmanaged([]const u8),
    qualifier: []const u8,
) !void {
    if (qualifier.len == 0) return;
    for (qualifiers.items) |existing| {
        if (std.mem.eql(u8, existing, qualifier)) return;
    }
    const owned = try alloc.dupe(u8, qualifier);
    errdefer alloc.free(owned);
    try qualifiers.append(alloc, owned);
}

fn appendGeneratedSourceAliasQualifiersAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    qualifiers: *std.ArrayListUnmanaged([]const u8),
    source_tokens: generated_parser.GeneratedSqlTokenRange,
    table_tokens: ?generated_parser.GeneratedSqlTokenRange,
    alias_name_tokens: ?generated_parser.GeneratedSqlTokenRange,
) !void {
    const table = table_tokens orelse return error.UnsupportedSqlShape;
    if (source_tokens.start >= source_tokens.end or source_tokens.end > tokens.len) return error.UnsupportedSqlShape;
    if (table.end != table.start + 1 or table.end > source_tokens.end) return error.UnsupportedSqlShape;
    if (tokens[table.start].kind != .identifier) return error.UnsupportedSqlShape;
    const table_name = try grammar.normalizeSqlObjectIdentifierAlloc(alloc, tokens[table.start].text);
    defer alloc.free(table_name);
    try appendGeneratedQualifierIfMissingAlloc(alloc, qualifiers, table_name);

    if (alias_name_tokens) |alias| {
        if (alias.end != alias.start + 1 or alias.end > source_tokens.end) return error.UnsupportedSqlShape;
        if (tokens[alias.start].kind != .identifier) return error.UnsupportedSqlShape;
        try appendGeneratedQualifierIfMissingAlloc(alloc, qualifiers, tokens[alias.start].text);
    }
}

fn appendGeneratedSetOperationRightJoinQualifiersAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    qualifiers: *std.ArrayListUnmanaged([]const u8),
    read: *const generated_parser.GeneratedSqlReadAst,
) !bool {
    if (read.kind != .set_operation or read.set_operation.right_join_items.len == 0) return false;
    const set_operation = read.set_operation;
    if (set_operation.right_source_table_tokens == null) return false;
    const right_source = set_operation.right_source_tokens orelse return error.UnsupportedSqlShape;
    try appendGeneratedSourceAliasQualifiersAlloc(
        alloc,
        tokens,
        qualifiers,
        right_source,
        set_operation.right_source_table_tokens,
        set_operation.right_source_alias_name_tokens,
    );
    for (set_operation.right_join_items, 0..) |join, index| {
        if (index == 0) {
            try appendGeneratedSourceAliasQualifiersAlloc(alloc, tokens, qualifiers, join.left_tokens, join.left_table_tokens, join.left_alias_name_tokens);
        }
        try appendGeneratedSourceAliasQualifiersAlloc(alloc, tokens, qualifiers, join.right_tokens, join.right_table_tokens, join.right_alias_name_tokens);
    }
    return qualifiers.items.len != 0;
}

fn freeGeneratedQualifiers(alloc: std.mem.Allocator, qualifiers: []const []const u8) void {
    for (qualifiers) |qualifier| alloc.free(@constCast(qualifier));
}

pub fn parseSelectAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: SelectParserOptions,
) !plan_mod.LoweredSelect {
    if (options.generated_read_ast) |read| try generated_read_validate.validateGeneratedReadAstPayloads(tokens, read.*);
    try parser.expectKeyword(tokens, pos, "select");

    const initial_context = options.context_hooks.get_context(options.context_hooks.ptr);
    defer options.context_hooks.set_context(options.context_hooks.ptr, initial_context);
    var current_context = initial_context;

    var direct_graph_source = try parseDirectGraphTableFunctionSourceAlloc(alloc, tokens, pos.*, options.available_ctes, options.generated_read_ast);
    var direct_graph_source_transferred = false;
    defer if (!direct_graph_source_transferred) {
        if (direct_graph_source) |*source| source.deinit(alloc);
    };

    const inferred_table_ref = if (direct_graph_source) |source|
        try cloneTableAliasAlloc(alloc, source.table_ref)
    else if (try generated_read_validate.inferGeneratedTableAliasFromReadSourceAlloc(alloc, tokens, pos.*, options.generated_read_ast, options.allow_select_set_result_tail_boundary)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.inferSelectSourceAliasAlloc(alloc, tokens, pos.*);
    defer if (inferred_table_ref) |value| plan_mod.freeTableAlias(alloc, value);
    var inferred_qualifiers: [2][]const u8 = undefined;
    var generated_join_qualifiers = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        freeGeneratedQualifiers(alloc, generated_join_qualifiers.items);
        generated_join_qualifiers.deinit(alloc);
    }
    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
    if (inferred_table_ref) |value| {
        inferred_qualifiers = .{ value.name, value.alias };
        if (if (options.allow_select_set_result_tail_boundary) if (options.generated_read_ast) |read|
            try appendGeneratedSetOperationRightJoinQualifiersAlloc(alloc, tokens, &generated_join_qualifiers, read)
        else
            false else false)
        {
            current_context.field_expression_qualifiers = generated_join_qualifiers.items;
            if (initial_context.joined_source_schema) |source_schema| current_context.schema = source_schema;
        } else {
            current_context.field_expression_qualifiers = inferred_qualifiers[0..];
        }
        if (direct_graph_source != null or plan_mod.findCteByName(options.available_ctes, value.name) != null) {
            const ctes = if (direct_graph_source) |*source| source_ctes: {
                const implicit_ctes = [_]db_mod.types.RelationalRowsCte{source.cte};
                break :source_ctes implicit_ctes[0..];
            } else options.available_ctes;
            planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, initial_context.schema, ctes);
            current_context.schema = relational_rows.rowsPlannedCteSchema(planned_ctes, value.name) orelse return error.UnsupportedSqlShape;
            current_context.defer_row_expression_field_validation = true;
        }
        options.context_hooks.set_context(options.context_hooks.ptr, current_context);
    }

    const generated_distinct = try generated_read_validate.generatedDistinctClauseEnd(tokens, pos.*, options.generated_read_ast, options.allow_select_set_result_tail_boundary);
    const distinct_on = try expr_order.parseOptionalDistinctOnAlloc(
        alloc,
        tokens,
        pos,
        options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
        options.row_expression_hooks,
        options.arithmetic_hooks,
        options.variadic_hooks,
    );
    errdefer freeExpressionSlice(alloc, distinct_on);
    if (generated_distinct) |distinct| {
        if (distinct.kind != .distinct_on or pos.* != distinct.end) return error.UnsupportedSqlShape;
    } else if (distinct_on.len > 0 and options.generated_read_ast != null) {
        return error.UnsupportedSqlShape;
    }
    _ = parser.matchKeyword(tokens, pos, "all");

    const generated_projection_end = try generated_read_validate.generatedProjectionClauseEnd(tokens, pos.*, options.generated_read_ast, options.allow_select_set_result_tail_boundary);
    const select = (try parseGeneratedScalarSubquerySelectListAlloc(
        alloc,
        tokens,
        pos,
        options.params,
        current_context.schema,
        options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
        options.available_ctes,
        options.generated_read_ast,
        options.realtime_ns,
        options.fixed_binary_hooks,
        options.bare_boolean_hooks,
        options.expression_alternatives_hooks,
        options.expression_condition_hooks,
    )) orelse try expr_projection.parseSelectListAlloc(
        alloc,
        tokens,
        pos,
        .{
            .params = options.params,
            .output_schema = current_context.schema,
            .select_item_schema = current_context.schema,
            .function_bindings = options.function_bindings,
            .type_context = options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
            .field_expression_qualifiers = current_context.field_expression_qualifiers,
            .returning_expression_qualifiers = current_context.returning_expression_qualifiers,
            .defer_row_expression_field_validation = current_context.defer_row_expression_field_validation,
            .field_source = options.field_source,
            .select_item_options = options.select_item_options,
            .generated_read_ast = options.generated_read_ast,
            .allow_generated_projection_fallback = options.allow_select_set_result_tail_boundary,
        },
    );
    errdefer strings.freeStringSlice(alloc, select.fields);
    errdefer plan_mod.freeJsonExtract(alloc, select.json_extract);
    errdefer plan_mod.freeArrayLengthProjections(alloc, select.array_length);
    errdefer plan_mod.freeCoalesceProjections(alloc, select.coalesce);
    errdefer plan_mod.freeFieldAliasProjections(alloc, select.field_aliases);
    errdefer freeExpressionProjections(alloc, select.expressions);
    errdefer plan_mod.freeScalarSubqueryProjections(alloc, select.scalar_subqueries);
    defer if (select.outputs.len > 0) alloc.free(select.outputs);
    if (generated_projection_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }

    try parser.expectKeyword(tokens, pos, "from");
    const source_start = pos.*;
    const generated_source_end = try generated_read_validate.generatedSourceClauseEnd(tokens, source_start, options.generated_read_ast, options.allow_select_set_result_tail_boundary);
    const table_ref = if (direct_graph_source) |source| table_ref: {
        if (pos.* != source.function_start) return error.UnsupportedSqlShape;
        pos.* = source.source_end;
        break :table_ref try cloneTableAliasAlloc(alloc, source.table_ref);
    } else if (try generated_read_validate.generatedTableAliasFromReadSourceAlloc(alloc, tokens, pos, options.generated_read_ast, options.allow_select_set_result_tail_boundary)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    errdefer alloc.free(table_ref.name);
    defer alloc.free(table_ref.alias);
    if (inferred_table_ref) |value| {
        if (!std.mem.eql(u8, table_ref.name, value.name) or !std.mem.eql(u8, table_ref.alias, value.alias)) return error.UnsupportedSqlShape;
    } else {
        inferred_qualifiers = .{ table_ref.name, table_ref.alias };
        current_context.field_expression_qualifiers = inferred_qualifiers[0..];
    }
    try generated_read_validate.validateGeneratedSingleSourceAliasForParsedTable(tokens, options.generated_read_ast, source_start, pos.*);
    if (generated_source_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }
    const source_is_cte = direct_graph_source != null or plan_mod.findCteByName(options.available_ctes, table_ref.name) != null;
    if (source_is_cte) current_context.defer_row_expression_field_validation = true;
    options.context_hooks.set_context(options.context_hooks.ptr, current_context);
    const system_time_as_of = try expr_parse.parseOptionalSystemTimeAsOf(tokens, pos);
    try generated_read_validate.validateGeneratedSystemTimeForParsedSource(tokens, options.generated_read_ast, source_start, generated_source_end orelse pos.*, pos.*, system_time_as_of);

    var predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, predicates.items);
        predicates.deinit(alloc);
    }
    var json_path_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate).empty;
    errdefer {
        freeJsonPathEq(alloc, json_path_eq.items);
        json_path_eq.deinit(alloc);
    }
    var json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, json_contains.items);
        json_contains.deinit(alloc);
    }
    var json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, json_path_exists.items);
        json_path_exists.deinit(alloc);
    }
    var array_any = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate).empty;
    errdefer {
        freeArrayAny(alloc, array_any.items);
        array_any.deinit(alloc);
    }
    var array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, array_contains.items);
        array_contains.deinit(alloc);
    }
    var array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, array_eq.items);
        array_eq.deinit(alloc);
    }
    var in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, in_predicates.items);
        in_predicates.deinit(alloc);
    }
    var text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, text_patterns.items);
        text_patterns.deinit(alloc);
    }
    var or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    errdefer {
        freePredicateGroups(alloc, or_predicates.items);
        or_predicates.deinit(alloc);
    }
    var not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    errdefer {
        freePredicateGroups(alloc, not_predicates.items);
        not_predicates.deinit(alloc);
    }
    var access_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
    errdefer {
        freeAccessPredicateGroups(alloc, access_or_predicates.items);
        access_or_predicates.deinit(alloc);
    }
    var access_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
    errdefer {
        freeAccessPredicateGroups(alloc, access_not_predicates.items);
        access_not_predicates.deinit(alloc);
    }
    var expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, expression_predicates.items);
        expression_predicates.deinit(alloc);
    }
    var expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_or_predicates.items);
        expression_or_predicates.deinit(alloc);
    }
    var expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_not_predicates.items);
        expression_not_predicates.deinit(alloc);
    }
    var expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, expression_array_contains.items);
        expression_array_contains.deinit(alloc);
    }
    var subquery_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsSubqueryPredicate).empty;
    errdefer {
        freeSubqueryPredicates(alloc, subquery_predicates.items);
        subquery_predicates.deinit(alloc);
    }
    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }

    var row_claim: ?db_mod.types.RowClaimRequest = null;
    var limit: ?u32 = null;
    var offset: u32 = 0;

    while (!parser.atEnd(tokens, pos.*)) {
        if (parser.matchKeyword(tokens, pos, "where")) {
            const keyword_index = pos.* - 1;
            const generated_where_end = try generated_read_validate.generatedWhereClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast, options.allow_select_set_result_tail_boundary);
            const generated_where_expression = try generated_read_validate.requireGeneratedWhereExpressionForClause(pos.*, options.generated_read_ast, options.allow_select_set_result_tail_boundary, generated_where_end);
            const where_context = options.context_hooks.get_context(options.context_hooks.ptr);
            try parseWhereAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                where_context.schema,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                where_context.field_expression_qualifiers,
                where_context.returning_expression_qualifiers,
                where_context.defer_row_expression_field_validation,
                &predicates,
                &json_contains,
                &json_path_eq,
                &json_path_exists,
                &array_any,
                &array_contains,
                &array_eq,
                &in_predicates,
                &text_patterns,
                &or_predicates,
                &not_predicates,
                &access_or_predicates,
                &access_not_predicates,
                &expression_predicates,
                &expression_or_predicates,
                &expression_not_predicates,
                &expression_array_contains,
                &subquery_predicates,
                options.realtime_ns,
                options.fixed_binary_hooks,
                options.bare_boolean_hooks,
                options.expression_alternatives_hooks,
                options.expression_condition_hooks,
                options.available_ctes,
                generated_where_expression,
            );
            if (generated_where_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (options.allow_select_set_result_tail_boundary and grammar.nextIsSelectSetResultTailKeyword(tokens, pos.*)) {
            break;
        } else if (options.allow_select_set_result_tail_boundary and grammar.nextIsSelectSetResultTailKeyword(tokens, pos.*)) {
            break;
        } else if (parser.matchKeyword(tokens, pos, "order")) {
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_order_end = try generated_read_validate.generatedOrderClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            const order_context = options.context_hooks.get_context(options.context_hooks.ptr);
            try expr_order.parseSelectOutputByAlloc(
                alloc,
                tokens,
                pos,
                &order_by,
                select,
                .{
                    .schema = order_context.schema,
                    .function_bindings = options.function_bindings,
                    .field_expression_qualifiers = order_context.field_expression_qualifiers,
                    .returning_expression_qualifiers = order_context.returning_expression_qualifiers,
                    .defer_row_expression_field_validation = order_context.defer_row_expression_field_validation,
                    .type_context = options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                    .order_expression_hooks = options.order_expression_hooks,
                    .generated_read_ast = options.generated_read_ast,
                },
            );
            if (generated_order_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
            if (distinct_on.len > 0) try expr_order.validateDistinctOnOrder(distinct_on, order_by.items);
        } else if (parser.matchKeyword(tokens, pos, "limit")) {
            const keyword_index = pos.* - 1;
            limit = (try generated_read_validate.parseLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "offset")) {
            const keyword_index = pos.* - 1;
            offset = try generated_read_validate.parseOffsetValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast);
        } else if (parser.matchKeyword(tokens, pos, "fetch")) {
            const keyword_index = pos.* - 1;
            limit = (try generated_read_validate.parseFetchLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "for")) {
            const allowed_targets = [_][]const u8{ table_ref.name, table_ref.alias };
            const keyword_index = pos.* - 1;
            row_claim = if (try row_claim_mod.parseGeneratedReadRowClaimForClauseAlloc(alloc, tokens, keyword_index, pos, &allowed_targets, options.generated_read_ast)) |generated_claim|
                generated_claim
            else if (options.generated_read_ast != null)
                return error.UnsupportedSqlShape
            else
                row_claim_mod.sqlRowClaimForClause(try grammar.parseCheckedForRowClaimClauseAlloc(alloc, tokens, pos, &allowed_targets));
        } else if (parser.matchToken(tokens, pos, .semicolon) != null) {
            if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
        } else if (options.allow_select_set_boundary and grammar.nextIsSelectSetOperationKeyword(tokens, pos.*)) {
            break;
        } else if (expr_parse.nextIsUnsupportedQueryKeyword(tokens, pos.*)) {
            return error.UnsupportedSqlShape;
        } else {
            return error.UnsupportedSqlShape;
        }
    }
    if (distinct_on.len > 0) {
        if (row_claim != null) return error.UnsupportedSqlShape;
        if (order_by.items.len == 0) return error.UnsupportedSqlShape;
        try expr_order.validateDistinctOnOrder(distinct_on, order_by.items);
    }
    const ctes = if (direct_graph_source) |*source| ctes: {
        const out = try alloc.alloc(db_mod.types.RelationalRowsCte, 1);
        out[0] = source.cte;
        source.cte = .{ .name = "" };
        direct_graph_source_transferred = true;
        plan_mod.freeTableAlias(alloc, source.table_ref);
        source.table_ref = .{ .name = "", .alias = "" };
        break :ctes out;
    } else &.{};

    return .{
        .table_name = table_ref.name,
        .ctes = ctes,
        .query = .{
            .predicates = try predicates.toOwnedSlice(alloc),
            .array_any = try array_any.toOwnedSlice(alloc),
            .array_contains = try array_contains.toOwnedSlice(alloc),
            .array_eq = try array_eq.toOwnedSlice(alloc),
            .in_predicates = try in_predicates.toOwnedSlice(alloc),
            .json_contains = try json_contains.toOwnedSlice(alloc),
            .json_path_eq = try json_path_eq.toOwnedSlice(alloc),
            .json_path_exists = try json_path_exists.toOwnedSlice(alloc),
            .text_patterns = try text_patterns.toOwnedSlice(alloc),
            .or_predicates = try or_predicates.toOwnedSlice(alloc),
            .not_predicates = try not_predicates.toOwnedSlice(alloc),
            .access_or_predicates = try access_or_predicates.toOwnedSlice(alloc),
            .access_not_predicates = try access_not_predicates.toOwnedSlice(alloc),
            .expression_predicates = try expression_predicates.toOwnedSlice(alloc),
            .expression_or_predicates = try expression_or_predicates.toOwnedSlice(alloc),
            .expression_not_predicates = try expression_not_predicates.toOwnedSlice(alloc),
            .expression_array_contains = try expression_array_contains.toOwnedSlice(alloc),
            .subquery_predicates = try subquery_predicates.toOwnedSlice(alloc),
            .select = select.fields,
            .json_extract = select.json_extract,
            .array_length = select.array_length,
            .coalesce = select.coalesce,
            .field_aliases = select.field_aliases,
            .expressions = select.expressions,
            .scalar_subqueries = select.scalar_subqueries,
            .select_all = select.select_all,
            .distinct_on_expressions = distinct_on,
            .order_by = try order_by.toOwnedSlice(alloc),
            .row_claim = row_claim,
            .limit = limit,
            .offset = offset,
        },
        .select_outputs = try plan_mod.cloneSelectOutputsAlloc(alloc, select.outputs),
        .system_time_as_of_sequence = system_time_as_of.sequence,
        .system_time_as_of_timestamp_ns = system_time_as_of.timestamp_ns,
    };
}

pub fn parseAggregateAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: AggregateParserOptions,
) !plan_mod.LoweredAggregate {
    if (options.generated_read_ast) |read| try generated_read_validate.validateGeneratedReadAstPayloads(tokens, read.*);
    try parser.expectKeyword(tokens, pos, "select");

    const initial_context = options.context_hooks.get_context(options.context_hooks.ptr);
    defer options.context_hooks.set_context(options.context_hooks.ptr, initial_context);
    var current_context = initial_context;

    var direct_graph_source = try parseDirectGraphTableFunctionSourceAlloc(alloc, tokens, pos.*, options.available_ctes, options.generated_read_ast);
    var direct_graph_source_transferred = false;
    defer if (!direct_graph_source_transferred) {
        if (direct_graph_source) |*source| source.deinit(alloc);
    };

    const inferred_table_ref = if (direct_graph_source) |source|
        try cloneTableAliasAlloc(alloc, source.table_ref)
    else if (try generated_read_validate.inferGeneratedTableAliasFromReadSourceAlloc(alloc, tokens, pos.*, options.generated_read_ast, false)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.inferSelectSourceAliasAlloc(alloc, tokens, pos.*);
    defer if (inferred_table_ref) |value| plan_mod.freeTableAlias(alloc, value);
    var inferred_qualifiers: [2][]const u8 = undefined;
    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
    if (inferred_table_ref) |value| {
        inferred_qualifiers = .{ value.name, value.alias };
        current_context.field_expression_qualifiers = inferred_qualifiers[0..];
        if (direct_graph_source != null or plan_mod.findCteByName(options.available_ctes, value.name) != null) {
            const ctes = if (direct_graph_source) |*source| source_ctes: {
                const implicit_ctes = [_]db_mod.types.RelationalRowsCte{source.cte};
                break :source_ctes implicit_ctes[0..];
            } else options.available_ctes;
            planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, initial_context.schema, ctes);
            current_context.schema = relational_rows.rowsPlannedCteSchema(planned_ctes, value.name) orelse return error.UnsupportedSqlShape;
            current_context.defer_row_expression_field_validation = true;
        }
        options.context_hooks.set_context(options.context_hooks.ptr, current_context);
    }

    const generated_distinct = try generated_read_validate.generatedDistinctClauseEnd(tokens, pos.*, options.generated_read_ast, false);
    const select_distinct = parser.matchKeyword(tokens, pos, "distinct");
    if (select_distinct and parser.peekKeyword(tokens, pos.*, "on")) return error.UnsupportedSqlShape;
    if (generated_distinct) |distinct| {
        if (distinct.kind != .plain or pos.* != distinct.end) return error.UnsupportedSqlShape;
    } else if (select_distinct and options.generated_read_ast != null) {
        return error.UnsupportedSqlShape;
    }

    const select_context = options.context_hooks.get_context(options.context_hooks.ptr);
    const generated_projection_end = try generated_read_validate.generatedProjectionClauseEnd(tokens, pos.*, options.generated_read_ast, false);
    const select = try expr_aggregate.parseSelectListAlloc(
        alloc,
        tokens,
        pos,
        options.params,
        select_context.schema,
        options.function_bindings,
        options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
        select_context.field_expression_qualifiers,
        select_context.returning_expression_qualifiers,
        select_context.defer_row_expression_field_validation,
        options.field_source,
        options.generated_read_ast,
        options.aggregate_spec_options,
        options.select_item_options,
    );
    var select_group_expressions_transferred = false;
    defer {
        strings.freeStringSlice(alloc, select.group_fields);
        if (!select_group_expressions_transferred) freeExpressionProjections(alloc, select.group_expressions);
        if (select.outputs.len > 0) alloc.free(select.outputs);
    }
    errdefer {
        plan_mod.freeAggregateSpecs(alloc, select.aggregations);
        if (select.aggregations.len > 0) alloc.free(select.aggregations);
    }
    if (generated_projection_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }
    const distinct_group_only = select_distinct and select.aggregations.len == 0;
    if (distinct_group_only) {
        if (select.group_fields.len == 0 and select.group_expressions.len == 0) return error.UnsupportedSqlShape;
    } else if (select.aggregations.len == 0) return error.UnsupportedSqlShape;

    try parser.expectKeyword(tokens, pos, "from");
    const source_start = pos.*;
    const generated_source_end = try generated_read_validate.generatedSourceClauseEnd(tokens, source_start, options.generated_read_ast, false);
    const table_ref = if (direct_graph_source) |source| table_ref: {
        if (pos.* != source.function_start) return error.UnsupportedSqlShape;
        pos.* = source.source_end;
        break :table_ref try cloneTableAliasAlloc(alloc, source.table_ref);
    } else if (try generated_read_validate.generatedTableAliasFromReadSourceAlloc(alloc, tokens, pos, options.generated_read_ast, false)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    errdefer alloc.free(table_ref.name);
    defer alloc.free(table_ref.alias);
    if (inferred_table_ref) |value| {
        if (!std.mem.eql(u8, table_ref.name, value.name) or !std.mem.eql(u8, table_ref.alias, value.alias)) return error.UnsupportedSqlShape;
    } else {
        inferred_qualifiers = .{ table_ref.name, table_ref.alias };
        current_context.field_expression_qualifiers = inferred_qualifiers[0..];
    }
    try generated_read_validate.validateGeneratedSingleSourceAliasForParsedTable(tokens, options.generated_read_ast, source_start, pos.*);
    if (generated_source_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }
    const source_is_cte = direct_graph_source != null or plan_mod.findCteByName(options.available_ctes, table_ref.name) != null;
    if (source_is_cte) current_context.defer_row_expression_field_validation = true;
    options.context_hooks.set_context(options.context_hooks.ptr, current_context);

    var predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, predicates.items);
        predicates.deinit(alloc);
    }
    var json_path_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate).empty;
    errdefer {
        freeJsonPathEq(alloc, json_path_eq.items);
        json_path_eq.deinit(alloc);
    }
    var json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, json_contains.items);
        json_contains.deinit(alloc);
    }
    var json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, json_path_exists.items);
        json_path_exists.deinit(alloc);
    }
    var array_any = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate).empty;
    errdefer {
        freeArrayAny(alloc, array_any.items);
        array_any.deinit(alloc);
    }
    var array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, array_contains.items);
        array_contains.deinit(alloc);
    }
    var array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, array_eq.items);
        array_eq.deinit(alloc);
    }
    var in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, in_predicates.items);
        in_predicates.deinit(alloc);
    }
    var text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, text_patterns.items);
        text_patterns.deinit(alloc);
    }
    var or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    errdefer {
        freePredicateGroups(alloc, or_predicates.items);
        or_predicates.deinit(alloc);
    }
    var not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    errdefer {
        freePredicateGroups(alloc, not_predicates.items);
        not_predicates.deinit(alloc);
    }
    var access_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
    errdefer {
        freeAccessPredicateGroups(alloc, access_or_predicates.items);
        access_or_predicates.deinit(alloc);
    }
    var access_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
    errdefer {
        freeAccessPredicateGroups(alloc, access_not_predicates.items);
        access_not_predicates.deinit(alloc);
    }
    var expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, expression_predicates.items);
        expression_predicates.deinit(alloc);
    }
    var expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_or_predicates.items);
        expression_or_predicates.deinit(alloc);
    }
    var expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_not_predicates.items);
        expression_not_predicates.deinit(alloc);
    }
    var expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, expression_array_contains.items);
        expression_array_contains.deinit(alloc);
    }
    var subquery_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsSubqueryPredicate).empty;
    errdefer {
        freeSubqueryPredicates(alloc, subquery_predicates.items);
        subquery_predicates.deinit(alloc);
    }
    var group_by = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (group_by.items) |field| alloc.free(field);
        group_by.deinit(alloc);
    }
    var group_expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionProjection).empty;
    defer {
        for (group_expressions.items) |projection| freeExpressionProjection(alloc, projection);
        group_expressions.deinit(alloc);
    }
    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }
    var having_predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, having_predicates.items);
        having_predicates.deinit(alloc);
    }
    var having_expressions = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, having_expressions.items);
        having_expressions.deinit(alloc);
    }
    var having_any = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, having_any.items);
        having_any.deinit(alloc);
    }
    var having_not = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, having_not.items);
        having_not.deinit(alloc);
    }

    var limit: ?u32 = null;
    var offset: u32 = 0;
    while (!parser.atEnd(tokens, pos.*)) {
        if (parser.matchKeyword(tokens, pos, "where")) {
            const keyword_index = pos.* - 1;
            const generated_where_end = try generated_read_validate.generatedWhereClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast, false);
            const generated_where_expression = try generated_read_validate.requireGeneratedWhereExpressionForClause(pos.*, options.generated_read_ast, false, generated_where_end);
            const where_context = options.context_hooks.get_context(options.context_hooks.ptr);
            try parseWhereAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                where_context.schema,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                where_context.field_expression_qualifiers,
                where_context.returning_expression_qualifiers,
                where_context.defer_row_expression_field_validation,
                &predicates,
                &json_contains,
                &json_path_eq,
                &json_path_exists,
                &array_any,
                &array_contains,
                &array_eq,
                &in_predicates,
                &text_patterns,
                &or_predicates,
                &not_predicates,
                &access_or_predicates,
                &access_not_predicates,
                &expression_predicates,
                &expression_or_predicates,
                &expression_not_predicates,
                &expression_array_contains,
                &subquery_predicates,
                options.realtime_ns,
                options.fixed_binary_hooks,
                options.bare_boolean_hooks,
                options.expression_alternatives_hooks,
                options.expression_condition_hooks,
                options.available_ctes,
                generated_where_expression,
            );
            if (generated_where_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "group")) {
            if (distinct_group_only) return error.UnsupportedSqlShape;
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_group_end = try generated_read_validate.generatedGroupClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            const group_context = options.context_hooks.get_context(options.context_hooks.ptr);
            try expr_aggregate.parseGroupByAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                group_context.schema,
                options.function_bindings,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                group_context.field_expression_qualifiers,
                group_context.returning_expression_qualifiers,
                group_context.defer_row_expression_field_validation,
                options.field_source,
                &group_by,
                &group_expressions,
                select,
                options.select_item_options,
                options.generated_read_ast,
            );
            if (generated_group_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "having")) {
            if (distinct_group_only) return error.UnsupportedSqlShape;
            const keyword_index = pos.* - 1;
            const generated_having_end = try generated_read_validate.generatedHavingClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            const generated_having_expression: ?*const generated_parser.GeneratedSqlExpressionAst = if (generated_having_end != null) blk: {
                const generated_read = options.generated_read_ast orelse return error.UnsupportedSqlShape;
                break :blk &generated_read.having_expression;
            } else null;
            try expr_aggregate.parseHavingAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                options.context_hooks.get_context(options.context_hooks.ptr).schema,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                &having_predicates,
                &having_expressions,
                &having_any,
                &having_not,
                select.group_fields,
                select.group_expressions,
                select.aggregations,
                options.output_field_options,
                .{
                    .params = options.output_field_condition_options.params,
                    .output_field_options = options.output_field_options,
                },
                .{
                    .context_hooks = options.context_hooks,
                    .case_expression_hooks = options.case_expression_hooks,
                },
                .{
                    .context_hooks = options.context_hooks,
                    .bare_boolean_hooks = options.bare_boolean_hooks,
                },
                generated_having_expression,
            );
            if (generated_having_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "order")) {
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_order_end = try generated_read_validate.generatedOrderClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            try expr_order.parseAggregateByAlloc(
                alloc,
                tokens,
                pos,
                options.context_hooks.get_context(options.context_hooks.ptr).schema,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                &order_by,
                select.group_fields,
                select.group_expressions,
                select.aggregations,
                options.output_field_options,
                blk: {
                    var order_options = options.output_order_expression_options;
                    order_options.generated_read_ast = options.generated_read_ast;
                    break :blk order_options;
                },
            );
            if (generated_order_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "limit")) {
            const keyword_index = pos.* - 1;
            limit = (try generated_read_validate.parseLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "offset")) {
            const keyword_index = pos.* - 1;
            offset = try generated_read_validate.parseOffsetValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast);
        } else if (parser.matchKeyword(tokens, pos, "fetch")) {
            const keyword_index = pos.* - 1;
            limit = (try generated_read_validate.parseFetchLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchToken(tokens, pos, .semicolon) != null) {
            if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
        } else if (expr_parse.nextIsUnsupportedQueryKeyword(tokens, pos.*)) {
            return error.UnsupportedSqlShape;
        } else {
            return error.UnsupportedSqlShape;
        }
    }

    if (distinct_group_only) {
        if (group_by.items.len != 0 or having_predicates.items.len != 0 or having_expressions.items.len != 0 or having_any.items.len != 0 or having_not.items.len != 0) return error.UnsupportedSqlShape;
    } else {
        try expr_aggregate.validateGroupBy(select.group_fields, select.group_expressions, group_by.items, group_expressions.items);
    }

    const owned_group_by = if (distinct_group_only)
        try strings.cloneStringSlice(alloc, select.group_fields)
    else
        try group_by.toOwnedSlice(alloc);
    var group_by_transferred = false;
    errdefer if (!group_by_transferred) strings.freeStringSlice(alloc, owned_group_by);
    const owned_group_expressions = select.group_expressions;

    const aggregate_request = db_mod.types.RelationalRowsAggregateRequest{
        .source = .{
            .predicates = try predicates.toOwnedSlice(alloc),
            .array_any = try array_any.toOwnedSlice(alloc),
            .array_contains = try array_contains.toOwnedSlice(alloc),
            .array_eq = try array_eq.toOwnedSlice(alloc),
            .in_predicates = try in_predicates.toOwnedSlice(alloc),
            .json_contains = try json_contains.toOwnedSlice(alloc),
            .json_path_eq = try json_path_eq.toOwnedSlice(alloc),
            .json_path_exists = try json_path_exists.toOwnedSlice(alloc),
            .text_patterns = try text_patterns.toOwnedSlice(alloc),
            .or_predicates = try or_predicates.toOwnedSlice(alloc),
            .not_predicates = try not_predicates.toOwnedSlice(alloc),
            .access_or_predicates = try access_or_predicates.toOwnedSlice(alloc),
            .access_not_predicates = try access_not_predicates.toOwnedSlice(alloc),
            .expression_predicates = try expression_predicates.toOwnedSlice(alloc),
            .expression_or_predicates = try expression_or_predicates.toOwnedSlice(alloc),
            .expression_not_predicates = try expression_not_predicates.toOwnedSlice(alloc),
            .expression_array_contains = try expression_array_contains.toOwnedSlice(alloc),
            .subquery_predicates = try subquery_predicates.toOwnedSlice(alloc),
            .select_all = true,
        },
        .group_by = owned_group_by,
        .group_expressions = owned_group_expressions,
        .aggregations = select.aggregations,
        .having_predicates = try having_predicates.toOwnedSlice(alloc),
        .having_expressions = try having_expressions.toOwnedSlice(alloc),
        .having_any = try having_any.toOwnedSlice(alloc),
        .having_not = try having_not.toOwnedSlice(alloc),
        .order_by = try order_by.toOwnedSlice(alloc),
        .limit = limit,
        .offset = offset,
    };
    group_by_transferred = true;
    select_group_expressions_transferred = true;
    const ctes = if (direct_graph_source) |*source| ctes: {
        const out = try alloc.alloc(db_mod.types.RelationalRowsCte, 1);
        out[0] = source.cte;
        source.cte = .{ .name = "" };
        direct_graph_source_transferred = true;
        plan_mod.freeTableAlias(alloc, source.table_ref);
        source.table_ref = .{ .name = "", .alias = "" };
        break :ctes out;
    } else &.{};

    return .{
        .table_name = table_ref.name,
        .ctes = ctes,
        .aggregate = aggregate_request,
    };
}

pub fn parseWindowSelectAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: WindowParserOptions,
) !plan_mod.LoweredWindowPlan {
    if (options.generated_read_ast) |read| try generated_read_validate.validateGeneratedReadAstPayloads(tokens, read.*);
    try parser.expectKeyword(tokens, pos, "select");

    const initial_context = options.context_hooks.get_context(options.context_hooks.ptr);
    defer options.context_hooks.set_context(options.context_hooks.ptr, initial_context);
    var current_context = initial_context;

    var direct_graph_source = try parseDirectGraphTableFunctionSourceAlloc(alloc, tokens, pos.*, options.available_ctes, options.generated_read_ast);
    var direct_graph_source_transferred = false;
    defer if (!direct_graph_source_transferred) {
        if (direct_graph_source) |*source| source.deinit(alloc);
    };

    const inferred_table_ref = if (direct_graph_source) |source|
        try cloneTableAliasAlloc(alloc, source.table_ref)
    else if (try generated_read_validate.inferGeneratedTableAliasFromReadSourceAlloc(alloc, tokens, pos.*, options.generated_read_ast, false)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.inferSelectSourceAliasAlloc(alloc, tokens, pos.*);
    defer if (inferred_table_ref) |value| plan_mod.freeTableAlias(alloc, value);
    var inferred_qualifiers: [2][]const u8 = undefined;
    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
    if (inferred_table_ref) |value| {
        inferred_qualifiers = .{ value.name, value.alias };
        current_context.field_expression_qualifiers = inferred_qualifiers[0..];
        if (direct_graph_source != null or plan_mod.findCteByName(options.available_ctes, value.name) != null) {
            const ctes = if (direct_graph_source) |*source| source_ctes: {
                const implicit_ctes = [_]db_mod.types.RelationalRowsCte{source.cte};
                break :source_ctes implicit_ctes[0..];
            } else options.available_ctes;
            planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, initial_context.schema, ctes);
            current_context.schema = relational_rows.rowsPlannedCteSchema(planned_ctes, value.name) orelse return error.UnsupportedSqlShape;
            current_context.defer_row_expression_field_validation = true;
        }
        options.context_hooks.set_context(options.context_hooks.ptr, current_context);
    }

    const parsed_named_windows = try expr_window.parseTopLevelNamedWindowSpecsAlloc(
        alloc,
        tokens,
        pos.*,
        options.params,
        .{
            .schema = current_context.schema,
            .field_expression_qualifiers = current_context.field_expression_qualifiers,
            .returning_expression_qualifiers = current_context.returning_expression_qualifiers,
            .defer_row_expression_field_validation = current_context.defer_row_expression_field_validation,
            .type_context = options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
            .function_bindings = options.function_bindings,
            .order_expression_hooks = options.order_expression_hooks,
        },
        options.generated_read_ast,
    );
    defer plan_mod.freeNamedWindowSpecs(alloc, parsed_named_windows);
    const previous_named_window_specs = options.named_window_hooks.get_specs(options.named_window_hooks.ptr);
    options.named_window_hooks.set_specs(options.named_window_hooks.ptr, parsed_named_windows);
    defer options.named_window_hooks.set_specs(options.named_window_hooks.ptr, previous_named_window_specs);

    const generated_projection_end = try generated_read_validate.generatedProjectionClauseEnd(tokens, pos.*, options.generated_read_ast, false);
    const select = try expr_window.parseSelectListAlloc(
        alloc,
        tokens,
        pos,
        .{
            .params = options.params,
            .schema = current_context.schema,
            .type_context = options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
            .field_expression_qualifiers = current_context.field_expression_qualifiers,
            .returning_expression_qualifiers = current_context.returning_expression_qualifiers,
            .defer_row_expression_field_validation = current_context.defer_row_expression_field_validation,
            .named_window_specs = options.named_window_hooks.get_specs(options.named_window_hooks.ptr),
            .function_bindings = options.function_bindings,
            .order_expression_hooks = options.order_expression_hooks,
            .window_definition_options = .{
                .schema = current_context.schema,
                .field_expression_qualifiers = current_context.field_expression_qualifiers,
                .returning_expression_qualifiers = current_context.returning_expression_qualifiers,
                .defer_row_expression_field_validation = current_context.defer_row_expression_field_validation,
                .type_context = options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                .function_bindings = options.function_bindings,
                .order_expression_hooks = options.order_expression_hooks,
            },
            .window_spec_options = options.window_spec_options,
            .generated_read_ast = options.generated_read_ast,
        },
    );
    defer if (select.outputs.len > 0) alloc.free(select.outputs);
    errdefer strings.freeStringSlice(alloc, select.fields);
    errdefer if (select.windows.len > 0) alloc.free(select.windows);
    errdefer plan_mod.freeWindowSpecs(alloc, select.windows);
    if (generated_projection_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }
    if (select.windows.len == 0) return error.UnsupportedSqlShape;

    try parser.expectKeyword(tokens, pos, "from");
    const source_start = pos.*;
    const generated_source_end = try generated_read_validate.generatedSourceClauseEnd(tokens, source_start, options.generated_read_ast, false);
    const table_ref = if (direct_graph_source) |source| table_ref: {
        if (pos.* != source.function_start) return error.UnsupportedSqlShape;
        pos.* = source.source_end;
        break :table_ref try cloneTableAliasAlloc(alloc, source.table_ref);
    } else if (try generated_read_validate.generatedTableAliasFromReadSourceAlloc(alloc, tokens, pos, options.generated_read_ast, false)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    errdefer alloc.free(table_ref.name);
    defer alloc.free(table_ref.alias);
    if (inferred_table_ref) |value| {
        if (!std.mem.eql(u8, table_ref.name, value.name) or !std.mem.eql(u8, table_ref.alias, value.alias)) return error.UnsupportedSqlShape;
    } else {
        inferred_qualifiers = .{ table_ref.name, table_ref.alias };
        current_context.field_expression_qualifiers = inferred_qualifiers[0..];
    }
    try generated_read_validate.validateGeneratedSingleSourceAliasForParsedTable(tokens, options.generated_read_ast, source_start, pos.*);
    if (generated_source_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }
    const source_is_cte = direct_graph_source != null or plan_mod.findCteByName(options.available_ctes, table_ref.name) != null;
    if (source_is_cte) current_context.defer_row_expression_field_validation = true;
    options.context_hooks.set_context(options.context_hooks.ptr, current_context);

    var predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, predicates.items);
        predicates.deinit(alloc);
    }
    var json_path_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathEqPredicate).empty;
    errdefer {
        freeJsonPathEq(alloc, json_path_eq.items);
        json_path_eq.deinit(alloc);
    }
    var json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, json_contains.items);
        json_contains.deinit(alloc);
    }
    var json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, json_path_exists.items);
        json_path_exists.deinit(alloc);
    }
    var array_any = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate).empty;
    errdefer {
        freeArrayAny(alloc, array_any.items);
        array_any.deinit(alloc);
    }
    var array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, array_contains.items);
        array_contains.deinit(alloc);
    }
    var array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, array_eq.items);
        array_eq.deinit(alloc);
    }
    var in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, in_predicates.items);
        in_predicates.deinit(alloc);
    }
    var text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, text_patterns.items);
        text_patterns.deinit(alloc);
    }
    var or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    errdefer {
        freePredicateGroups(alloc, or_predicates.items);
        or_predicates.deinit(alloc);
    }
    var not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsPredicateGroup).empty;
    errdefer {
        freePredicateGroups(alloc, not_predicates.items);
        not_predicates.deinit(alloc);
    }
    var access_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
    errdefer {
        freeAccessPredicateGroups(alloc, access_or_predicates.items);
        access_or_predicates.deinit(alloc);
    }
    var access_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup).empty;
    errdefer {
        freeAccessPredicateGroups(alloc, access_not_predicates.items);
        access_not_predicates.deinit(alloc);
    }
    var expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, expression_predicates.items);
        expression_predicates.deinit(alloc);
    }
    var expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_or_predicates.items);
        expression_or_predicates.deinit(alloc);
    }
    var expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_not_predicates.items);
        expression_not_predicates.deinit(alloc);
    }
    var expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, expression_array_contains.items);
        expression_array_contains.deinit(alloc);
    }
    var subquery_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsSubqueryPredicate).empty;
    errdefer {
        freeSubqueryPredicates(alloc, subquery_predicates.items);
        subquery_predicates.deinit(alloc);
    }
    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }

    var limit: ?u32 = null;
    var offset: u32 = 0;
    while (!parser.atEnd(tokens, pos.*)) {
        if (parser.matchKeyword(tokens, pos, "where")) {
            const keyword_index = pos.* - 1;
            const generated_where_end = try generated_read_validate.generatedWhereClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast, false);
            const generated_where_expression = try generated_read_validate.requireGeneratedWhereExpressionForClause(pos.*, options.generated_read_ast, false, generated_where_end);
            const where_context = options.context_hooks.get_context(options.context_hooks.ptr);
            try parseWhereAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                where_context.schema,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                where_context.field_expression_qualifiers,
                where_context.returning_expression_qualifiers,
                where_context.defer_row_expression_field_validation,
                &predicates,
                &json_contains,
                &json_path_eq,
                &json_path_exists,
                &array_any,
                &array_contains,
                &array_eq,
                &in_predicates,
                &text_patterns,
                &or_predicates,
                &not_predicates,
                &access_or_predicates,
                &access_not_predicates,
                &expression_predicates,
                &expression_or_predicates,
                &expression_not_predicates,
                &expression_array_contains,
                &subquery_predicates,
                options.realtime_ns,
                options.fixed_binary_hooks,
                options.bare_boolean_hooks,
                options.expression_alternatives_hooks,
                options.expression_condition_hooks,
                options.available_ctes,
                generated_where_expression,
            );
            if (generated_where_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "window")) {
            const keyword_index = pos.* - 1;
            const generated_window_end = try generated_read_validate.generatedWindowClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            const end = expr_window.topLevelClauseEnd(tokens, pos.*);
            var window_pos: usize = pos.*;
            const window_context = options.context_hooks.get_context(options.context_hooks.ptr);
            var generated_window_options = expr_window.WindowDefinitionParserOptions{
                .schema = window_context.schema,
                .field_expression_qualifiers = window_context.field_expression_qualifiers,
                .returning_expression_qualifiers = window_context.returning_expression_qualifiers,
                .defer_row_expression_field_validation = window_context.defer_row_expression_field_validation,
                .type_context = options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                .function_bindings = options.function_bindings,
                .order_expression_hooks = options.order_expression_hooks,
            };
            if (options.generated_read_ast) |read| generated_window_options.generated_window_items = read.window_items;
            const discarded_named_windows = try expr_window.parseNamedWindowSpecsAlloc(
                alloc,
                tokens,
                &window_pos,
                end,
                options.params,
                generated_window_options,
            );
            defer plan_mod.freeNamedWindowSpecs(alloc, discarded_named_windows);
            pos.* = end;
            if (generated_window_end) |generated_end| {
                if (pos.* != generated_end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "order")) {
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_order_end = try generated_read_validate.generatedOrderClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            try expr_order.parseWindowOutputByAlloc(
                alloc,
                tokens,
                pos,
                options.context_hooks.get_context(options.context_hooks.ptr).schema,
                options.context_hooks.row_expression_type_context(options.context_hooks.ptr),
                &order_by,
                select,
                blk: {
                    var order_options = options.output_order_expression_options;
                    order_options.generated_read_ast = options.generated_read_ast;
                    break :blk order_options;
                },
            );
            if (generated_order_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "limit")) {
            const keyword_index = pos.* - 1;
            limit = (try generated_read_validate.parseLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "offset")) {
            const keyword_index = pos.* - 1;
            offset = try generated_read_validate.parseOffsetValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast);
        } else if (parser.matchKeyword(tokens, pos, "fetch")) {
            const keyword_index = pos.* - 1;
            limit = (try generated_read_validate.parseFetchLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "for")) {
            return error.UnsupportedSqlShape;
        } else if (parser.matchToken(tokens, pos, .semicolon) != null) {
            if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
        } else if (expr_parse.nextIsUnsupportedQueryKeyword(tokens, pos.*)) {
            return error.UnsupportedSqlShape;
        } else {
            return error.UnsupportedSqlShape;
        }
    }

    const ctes = if (direct_graph_source) |*source| ctes: {
        const out = try alloc.alloc(db_mod.types.RelationalRowsCte, 1);
        out[0] = source.cte;
        source.cte = .{ .name = "" };
        direct_graph_source_transferred = true;
        plan_mod.freeTableAlias(alloc, source.table_ref);
        source.table_ref = .{ .name = "", .alias = "" };
        break :ctes out;
    } else &.{};

    return .{
        .table_name = table_ref.name,
        .plan = .{
            .ctes = ctes,
            .window = .{
                .source = .{
                    .predicates = try predicates.toOwnedSlice(alloc),
                    .array_any = try array_any.toOwnedSlice(alloc),
                    .array_contains = try array_contains.toOwnedSlice(alloc),
                    .array_eq = try array_eq.toOwnedSlice(alloc),
                    .in_predicates = try in_predicates.toOwnedSlice(alloc),
                    .json_contains = try json_contains.toOwnedSlice(alloc),
                    .json_path_eq = try json_path_eq.toOwnedSlice(alloc),
                    .json_path_exists = try json_path_exists.toOwnedSlice(alloc),
                    .text_patterns = try text_patterns.toOwnedSlice(alloc),
                    .or_predicates = try or_predicates.toOwnedSlice(alloc),
                    .not_predicates = try not_predicates.toOwnedSlice(alloc),
                    .access_or_predicates = try access_or_predicates.toOwnedSlice(alloc),
                    .access_not_predicates = try access_not_predicates.toOwnedSlice(alloc),
                    .expression_predicates = try expression_predicates.toOwnedSlice(alloc),
                    .expression_or_predicates = try expression_or_predicates.toOwnedSlice(alloc),
                    .expression_not_predicates = try expression_not_predicates.toOwnedSlice(alloc),
                    .expression_array_contains = try expression_array_contains.toOwnedSlice(alloc),
                    .subquery_predicates = try subquery_predicates.toOwnedSlice(alloc),
                    .select_all = true,
                },
                .windows = select.windows,
                .select = select.fields,
                .select_all = select.select_all,
                .order_by = try order_by.toOwnedSlice(alloc),
                .limit = limit,
                .offset = offset,
            },
        },
    };
}

pub fn parseJoinAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: JoinParserOptions,
) !plan_mod.LoweredJoin {
    if (options.generated_read_ast) |read| try generated_read_validate.validateGeneratedReadAstPayloads(tokens, read.*);
    try generated_read_validate.validateGeneratedJoinExecutableContract(options.generated_read_ast, tokens, .join);
    try parser.expectKeyword(tokens, pos, "select");

    const generated_projection_end = try generated_read_validate.generatedProjectionClauseEnd(tokens, pos.*, options.generated_read_ast, false);
    const raw_select = if (try generated_read_validate.generatedJoinProjectionListAlloc(alloc, options.generated_read_ast, tokens, pos)) |generated_projection|
        generated_projection
    else
        try plan_mod.parseJoinProjectionListAlloc(alloc, tokens, pos);
    defer plan_mod.freeQualifiedProjections(alloc, raw_select);
    if (generated_projection_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }

    try parser.expectKeyword(tokens, pos, "from");
    const left_tokens_start = pos.*;
    var left_graph_source = try parseGraphTableFunctionSourceAtAlloc(alloc, tokens, pos.*, "__antfly_graph_join_left", options.available_ctes, options.generated_read_ast);
    var left_graph_source_transferred = false;
    defer if (!left_graph_source_transferred) {
        if (left_graph_source) |*source| source.deinit(alloc);
    };
    const left_table = if (left_graph_source) |source| table_ref: {
        pos.* = source.source_end;
        break :table_ref try cloneTableAliasAlloc(alloc, source.table_ref);
    } else if (try generated_read_validate.generatedTableAliasFromJoinSideAlloc(alloc, tokens, pos, options.generated_read_ast, .left)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    defer plan_mod.freeTableAlias(alloc, left_table);
    const operator_tokens_start = pos.*;

    const natural_join = parser.matchKeyword(tokens, pos, "natural");
    const cross_join = if (natural_join) false else parser.matchKeyword(tokens, pos, "cross");
    const logical_join_kind: generated_parser.GeneratedSqlJoinKind = if (natural_join) blk: {
        try parser.expectKeyword(tokens, pos, "join");
        break :blk .inner;
    } else if (cross_join) blk: {
        try parser.expectKeyword(tokens, pos, "join");
        break :blk .inner;
    } else if (parser.matchKeyword(tokens, pos, "left")) blk: {
        _ = parser.matchKeyword(tokens, pos, "outer");
        try parser.expectKeyword(tokens, pos, "join");
        break :blk .left;
    } else if (parser.matchKeyword(tokens, pos, "right")) blk: {
        _ = parser.matchKeyword(tokens, pos, "outer");
        try parser.expectKeyword(tokens, pos, "join");
        break :blk .right;
    } else if (parser.matchKeyword(tokens, pos, "full")) blk: {
        _ = parser.matchKeyword(tokens, pos, "outer");
        try parser.expectKeyword(tokens, pos, "join");
        break :blk .full;
    } else blk: {
        _ = parser.matchKeyword(tokens, pos, "inner");
        try parser.expectKeyword(tokens, pos, "join");
        break :blk .inner;
    };
    const join_type = try joinKindPhysicalType(logical_join_kind);
    const normalize_right_join = logical_join_kind == .right;
    const right_tokens_start = pos.*;

    var right_graph_source = try parseGraphTableFunctionSourceAtAlloc(alloc, tokens, pos.*, "__antfly_graph_join", options.available_ctes, options.generated_read_ast);
    var right_graph_source_transferred = false;
    defer if (!right_graph_source_transferred) {
        if (right_graph_source) |*source| source.deinit(alloc);
    };
    const right_table = if (right_graph_source) |source| table_ref: {
        pos.* = source.source_end;
        break :table_ref try cloneTableAliasAlloc(alloc, source.table_ref);
    } else if (try generated_read_validate.generatedTableAliasFromJoinSideAlloc(alloc, tokens, pos, options.generated_read_ast, .right)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    defer plan_mod.freeTableAlias(alloc, right_table);
    const condition_tokens_start = pos.*;
    if (std.mem.eql(u8, left_table.alias, right_table.alias)) return error.UnsupportedSqlShape;

    const left_table_name_source = if (left_graph_source) |source| switch (source.cte.table_function.?) {
        .graph_query => |graph_query| graph_query.table_name,
        .graph_metric_query => |graph_metric_query| graph_metric_query.table_name,
        .graph_metric_rerank_query => |graph_metric_rerank_query| graph_metric_rerank_query.table_name,
    } else left_table.name;
    const right_table_name_source = if (right_graph_source) |source| switch (source.cte.table_function.?) {
        .graph_query => |graph_query| graph_query.table_name,
        .graph_metric_query => |graph_metric_query| graph_metric_query.table_name,
        .graph_metric_rerank_query => |graph_metric_rerank_query| graph_metric_rerank_query.table_name,
    } else right_table.name;
    if (left_graph_source != null and !std.mem.eql(u8, left_table_name_source, right_table_name_source)) return error.UnsupportedSqlShape;
    if (right_graph_source) |source| {
        const graph_table_name = switch (source.cte.table_function.?) {
            .graph_query => |graph_query| graph_query.table_name,
            .graph_metric_query => |graph_metric_query| graph_metric_query.table_name,
            .graph_metric_rerank_query => |graph_metric_rerank_query| graph_metric_rerank_query.table_name,
        };
        if (!std.mem.eql(u8, left_table_name_source, graph_table_name)) return error.UnsupportedSqlShape;
    }

    const initial_context = options.context_hooks.get_context(options.context_hooks.ptr);
    defer options.context_hooks.set_context(options.context_hooks.ptr, initial_context);
    var current_context = initial_context;
    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
    var available_ctes = options.available_ctes;
    var available_ctes_owned = false;
    defer if (available_ctes_owned) alloc.free(available_ctes);
    const implicit_graph_cte_count: usize = @as(usize, if (left_graph_source != null) 1 else 0) + @as(usize, if (right_graph_source != null) 1 else 0);
    if (implicit_graph_cte_count != 0) {
        const combined = try alloc.alloc(db_mod.types.RelationalRowsCte, options.available_ctes.len + implicit_graph_cte_count);
        @memcpy(combined[0..options.available_ctes.len], options.available_ctes);
        var combined_index = options.available_ctes.len;
        if (left_graph_source) |source| {
            combined[combined_index] = source.cte;
            combined_index += 1;
        }
        if (right_graph_source) |source| {
            combined[combined_index] = source.cte;
            combined_index += 1;
        }
        available_ctes = combined;
        available_ctes_owned = true;
    }
    if (available_ctes.len != 0) {
        const cte_base_schema = initial_context.joined_source_schema orelse initial_context.schema;
        planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, cte_base_schema, available_ctes);
    }
    const left_cte_schema = relational_rows.rowsPlannedCteSchema(planned_ctes, left_table.name);
    const right_cte_schema = relational_rows.rowsPlannedCteSchema(planned_ctes, right_table.name);
    current_context.schema = left_cte_schema orelse initial_context.schema;
    current_context.joined_source_schema = right_cte_schema orelse initial_context.joined_source_schema orelse initial_context.schema;
    const right_join_parse_schema_swap = normalize_right_join and left_cte_schema == null and right_cte_schema == null;
    const join_parse_left_schema = if (right_join_parse_schema_swap) current_context.joined_source_schema orelse current_context.schema else current_context.schema;
    const join_parse_right_schema: ?runtime_schema.TableSchema = if (right_join_parse_schema_swap) current_context.schema else current_context.joined_source_schema;
    options.context_hooks.set_context(options.context_hooks.ptr, current_context);

    var on = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJoinOn).empty;
    errdefer {
        plan_mod.freeJoinOn(alloc, on.items);
        on.deinit(alloc);
    }
    var left_predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, left_predicates.items);
        left_predicates.deinit(alloc);
    }
    var right_predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, right_predicates.items);
        right_predicates.deinit(alloc);
    }
    var left_json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, left_json_contains.items);
        left_json_contains.deinit(alloc);
    }
    var right_json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, right_json_contains.items);
        right_json_contains.deinit(alloc);
    }
    var left_json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, left_json_path_exists.items);
        left_json_path_exists.deinit(alloc);
    }
    var right_json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, right_json_path_exists.items);
        right_json_path_exists.deinit(alloc);
    }
    var left_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, left_array_contains.items);
        left_array_contains.deinit(alloc);
    }
    var right_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, right_array_contains.items);
        right_array_contains.deinit(alloc);
    }
    var left_array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, left_array_eq.items);
        left_array_eq.deinit(alloc);
    }
    var right_array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, right_array_eq.items);
        right_array_eq.deinit(alloc);
    }
    var left_in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, left_in_predicates.items);
        left_in_predicates.deinit(alloc);
    }
    var right_in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, right_in_predicates.items);
        right_in_predicates.deinit(alloc);
    }
    var left_text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, left_text_patterns.items);
        left_text_patterns.deinit(alloc);
    }
    var right_text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, right_text_patterns.items);
        right_text_patterns.deinit(alloc);
    }
    var left_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, left_expression_predicates.items);
        left_expression_predicates.deinit(alloc);
    }
    var right_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, right_expression_predicates.items);
        right_expression_predicates.deinit(alloc);
    }
    var left_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, left_expression_or_predicates.items);
        left_expression_or_predicates.deinit(alloc);
    }
    var right_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, right_expression_or_predicates.items);
        right_expression_or_predicates.deinit(alloc);
    }
    var left_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, left_expression_not_predicates.items);
        left_expression_not_predicates.deinit(alloc);
    }
    var right_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, right_expression_not_predicates.items);
        right_expression_not_predicates.deinit(alloc);
    }
    var left_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, left_expression_array_contains.items);
        left_expression_array_contains.deinit(alloc);
    }
    var right_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, right_expression_array_contains.items);
        right_expression_array_contains.deinit(alloc);
    }
    var match_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, match_expression_predicates.items);
        match_expression_predicates.deinit(alloc);
    }
    var on_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, on_expression_predicates.items);
        on_expression_predicates.deinit(alloc);
    }
    var on_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, on_expression_or_predicates.items);
        on_expression_or_predicates.deinit(alloc);
    }
    var on_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, on_expression_not_predicates.items);
        on_expression_not_predicates.deinit(alloc);
    }
    var on_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, on_expression_array_contains.items);
        on_expression_array_contains.deinit(alloc);
    }
    var match_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, match_expression_or_predicates.items);
        match_expression_or_predicates.deinit(alloc);
    }
    var match_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, match_expression_not_predicates.items);
        match_expression_not_predicates.deinit(alloc);
    }
    var match_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, match_expression_array_contains.items);
        match_expression_array_contains.deinit(alloc);
    }

    if (cross_join) {
        try generated_read_validate.validateGeneratedSingleConditionlessJoinForClause(
            options.generated_read_ast,
            .join,
            tokens,
            .{ .start = left_tokens_start, .end = operator_tokens_start },
            .{ .start = operator_tokens_start, .end = right_tokens_start },
            .cross,
            .{ .start = right_tokens_start, .end = condition_tokens_start },
        );
    } else if (natural_join) {
        try appendNaturalJoinColumnsAlloc(alloc, join_parse_left_schema, join_parse_right_schema, &on);
        try generated_read_validate.validateGeneratedSingleConditionlessJoinForClause(
            options.generated_read_ast,
            .join,
            tokens,
            .{ .start = left_tokens_start, .end = operator_tokens_start },
            .{ .start = operator_tokens_start, .end = right_tokens_start },
            .natural,
            .{ .start = right_tokens_start, .end = condition_tokens_start },
        );
    } else if (parser.matchKeyword(tokens, pos, "on")) {
        const predicate_tokens_start = pos.*;
        var on_targets = JoinOnPredicateTargets{
            .on = &on,
            .left_predicates = &left_predicates,
            .right_predicates = &right_predicates,
            .on_expression_predicates = &on_expression_predicates,
            .on_expression_or_predicates = &on_expression_or_predicates,
            .on_expression_not_predicates = &on_expression_not_predicates,
            .on_expression_array_contains = &on_expression_array_contains,
        };
        const generated_on_expression = try generated_read_validate.generatedSingleJoinPredicateExpression(options.generated_read_ast);
        try parseJoinOnAlloc(
            alloc,
            tokens,
            pos,
            options.params,
            join_parse_left_schema,
            join_parse_right_schema,
            join_type,
            left_table.alias,
            right_table.alias,
            options.string_to_array_predicate_is_containment,
            &on_targets,
            options.expression_where_options,
            options.realtime_ns,
            generated_on_expression,
        );
        try generated_read_validate.validateGeneratedSingleJoinForClauseKind(
            options.generated_read_ast,
            .join,
            tokens,
            .{ .start = left_tokens_start, .end = operator_tokens_start },
            .{ .start = operator_tokens_start, .end = right_tokens_start },
            logical_join_kind,
            .{ .start = right_tokens_start, .end = condition_tokens_start },
            .{ .start = condition_tokens_start, .end = pos.* },
            .{ .start = predicate_tokens_start, .end = pos.* },
        );
    } else if (parser.matchKeyword(tokens, pos, "using")) {
        try parser.expectToken(tokens, pos, .lparen);
        const column_tokens_start = pos.*;
        const using_columns = if (try generated_read_validate.generatedJoinUsingColumnsAlloc(alloc, options.generated_read_ast, .join, tokens, pos)) |generated_columns|
            generated_columns
        else
            try grammar.parseIdentifierListAlloc(alloc, tokens, pos);
        defer strings.freeStringSlice(alloc, using_columns);
        const column_tokens_end = pos.*;
        try parser.expectToken(tokens, pos, .rparen);
        try appendJoinUsingColumnsAlloc(alloc, using_columns, join_parse_left_schema, join_parse_right_schema, &on);
        try generated_read_validate.validateGeneratedSingleJoinUsingForClauseKind(
            options.generated_read_ast,
            .join,
            tokens,
            .{ .start = left_tokens_start, .end = operator_tokens_start },
            .{ .start = operator_tokens_start, .end = right_tokens_start },
            logical_join_kind,
            .{ .start = right_tokens_start, .end = condition_tokens_start },
            .{ .start = condition_tokens_start, .end = pos.* },
            .{ .start = column_tokens_start, .end = column_tokens_end },
        );
    } else {
        return error.UnsupportedSqlShape;
    }

    var select = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJoinProjection).empty;
    errdefer {
        plan_mod.freeJoinProjections(alloc, select.items);
        select.deinit(alloc);
    }
    try binder.resolveJoinProjectionsAlloc(alloc, join_parse_left_schema, join_parse_right_schema, raw_select, left_table.alias, right_table.alias, &select);

    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }

    var limit: ?u32 = null;
    var offset: u32 = 0;
    while (!parser.atEnd(tokens, pos.*)) {
        if (parser.matchKeyword(tokens, pos, "where")) {
            const keyword_index = pos.* - 1;
            const generated_where_end = try generated_read_validate.generatedWhereClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast, false);
            const generated_where_expression = try generated_read_validate.requireGeneratedWhereExpressionForClause(pos.*, options.generated_read_ast, false, generated_where_end);
            var where_targets = JoinWherePredicateTargets{
                .left_predicates = &left_predicates,
                .right_predicates = &right_predicates,
                .left_json_contains = &left_json_contains,
                .right_json_contains = &right_json_contains,
                .left_json_path_exists = &left_json_path_exists,
                .right_json_path_exists = &right_json_path_exists,
                .left_array_contains = &left_array_contains,
                .right_array_contains = &right_array_contains,
                .left_array_eq = &left_array_eq,
                .right_array_eq = &right_array_eq,
                .left_in_predicates = &left_in_predicates,
                .right_in_predicates = &right_in_predicates,
                .left_text_patterns = &left_text_patterns,
                .right_text_patterns = &right_text_patterns,
                .left_expression_predicates = &left_expression_predicates,
                .right_expression_predicates = &right_expression_predicates,
                .left_expression_or_predicates = &left_expression_or_predicates,
                .right_expression_or_predicates = &right_expression_or_predicates,
                .left_expression_not_predicates = &left_expression_not_predicates,
                .right_expression_not_predicates = &right_expression_not_predicates,
                .left_expression_array_contains = &left_expression_array_contains,
                .right_expression_array_contains = &right_expression_array_contains,
                .match_expression_predicates = &match_expression_predicates,
                .match_expression_or_predicates = &match_expression_or_predicates,
                .match_expression_not_predicates = &match_expression_not_predicates,
                .match_expression_array_contains = &match_expression_array_contains,
            };
            try parseJoinWhereAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                join_parse_left_schema,
                join_parse_right_schema,
                left_table.alias,
                right_table.alias,
                options.string_to_array_predicate_is_containment,
                &where_targets,
                options.expression_where_options,
                options.realtime_ns,
                generated_where_expression,
            );
            if (generated_where_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "order")) {
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_order_end = try generated_read_validate.generatedOrderClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            try expr_order.parseJoinByAlloc(
                alloc,
                tokens,
                pos,
                current_context.schema,
                &order_by,
                select.items,
                blk: {
                    var order_options = options.output_order_expression_options;
                    order_options.generated_read_ast = options.generated_read_ast;
                    break :blk order_options;
                },
            );
            if (generated_order_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "limit")) {
            const keyword_index = pos.* - 1;
            limit = (try generated_read_validate.parseLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "offset")) {
            const keyword_index = pos.* - 1;
            offset = try generated_read_validate.parseOffsetValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast);
        } else if (parser.matchKeyword(tokens, pos, "fetch")) {
            const keyword_index = pos.* - 1;
            limit = (try generated_read_validate.parseFetchLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchToken(tokens, pos, .semicolon) != null) {
            if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
        } else if (expr_parse.nextIsUnsupportedQueryKeyword(tokens, pos.*)) {
            return error.UnsupportedSqlShape;
        } else {
            return error.UnsupportedSqlShape;
        }
    }

    if (normalize_right_join and
        (on_expression_predicates.items.len != 0 or
            on_expression_or_predicates.items.len != 0 or
            on_expression_not_predicates.items.len != 0 or
            on_expression_array_contains.items.len != 0 or
            match_expression_predicates.items.len != 0 or
            match_expression_or_predicates.items.len != 0 or
            match_expression_not_predicates.items.len != 0 or
            match_expression_array_contains.items.len != 0))
    {
        return error.UnsupportedSqlShape;
    }

    var left_table_name = try alloc.dupe(u8, left_table_name_source);
    var left_table_name_transferred = false;
    errdefer if (!left_table_name_transferred) alloc.free(left_table_name);
    var right_table_name = try alloc.dupe(u8, right_table_name_source);
    var right_table_name_transferred = false;
    errdefer if (!right_table_name_transferred) alloc.free(right_table_name);
    const left_source_cte = if (left_graph_source) |source| try alloc.dupe(u8, source.cte.name) else "";
    var left_source_cte_transferred = false;
    errdefer if (!left_source_cte_transferred and left_source_cte.len > 0) alloc.free(left_source_cte);
    const right_source_cte = if (right_graph_source) |source| try alloc.dupe(u8, source.cte.name) else "";
    var right_source_cte_transferred = false;
    errdefer if (!right_source_cte_transferred and right_source_cte.len > 0) alloc.free(right_source_cte);

    var join_request = db_mod.types.RelationalRowsJoinRequest{
        .left = .{
            .source_cte = left_source_cte,
            .predicates = try left_predicates.toOwnedSlice(alloc),
            .json_contains = try left_json_contains.toOwnedSlice(alloc),
            .json_path_exists = try left_json_path_exists.toOwnedSlice(alloc),
            .array_contains = try left_array_contains.toOwnedSlice(alloc),
            .array_eq = try left_array_eq.toOwnedSlice(alloc),
            .in_predicates = try left_in_predicates.toOwnedSlice(alloc),
            .text_patterns = try left_text_patterns.toOwnedSlice(alloc),
            .expression_predicates = try left_expression_predicates.toOwnedSlice(alloc),
            .expression_or_predicates = try left_expression_or_predicates.toOwnedSlice(alloc),
            .expression_not_predicates = try left_expression_not_predicates.toOwnedSlice(alloc),
            .expression_array_contains = try left_expression_array_contains.toOwnedSlice(alloc),
            .select_all = true,
        },
        .right = .{
            .source_cte = right_source_cte,
            .predicates = try right_predicates.toOwnedSlice(alloc),
            .json_contains = try right_json_contains.toOwnedSlice(alloc),
            .json_path_exists = try right_json_path_exists.toOwnedSlice(alloc),
            .array_contains = try right_array_contains.toOwnedSlice(alloc),
            .array_eq = try right_array_eq.toOwnedSlice(alloc),
            .in_predicates = try right_in_predicates.toOwnedSlice(alloc),
            .text_patterns = try right_text_patterns.toOwnedSlice(alloc),
            .expression_predicates = try right_expression_predicates.toOwnedSlice(alloc),
            .expression_or_predicates = try right_expression_or_predicates.toOwnedSlice(alloc),
            .expression_not_predicates = try right_expression_not_predicates.toOwnedSlice(alloc),
            .expression_array_contains = try right_expression_array_contains.toOwnedSlice(alloc),
            .select_all = true,
        },
        .on = try on.toOwnedSlice(alloc),
        .on_expression_predicates = try on_expression_predicates.toOwnedSlice(alloc),
        .on_expression_or_predicates = try on_expression_or_predicates.toOwnedSlice(alloc),
        .on_expression_not_predicates = try on_expression_not_predicates.toOwnedSlice(alloc),
        .on_expression_array_contains = try on_expression_array_contains.toOwnedSlice(alloc),
        .match_expression_predicates = try match_expression_predicates.toOwnedSlice(alloc),
        .match_expression_or_predicates = try match_expression_or_predicates.toOwnedSlice(alloc),
        .match_expression_not_predicates = try match_expression_not_predicates.toOwnedSlice(alloc),
        .match_expression_array_contains = try match_expression_array_contains.toOwnedSlice(alloc),
        .join_type = join_type,
        .select = try select.toOwnedSlice(alloc),
        .order_by = try order_by.toOwnedSlice(alloc),
        .limit = limit,
        .offset = offset,
    };
    if (normalize_right_join) {
        normalizeRightJoinRequest(&join_request);
        const physical_right_table_name = left_table_name;
        left_table_name = right_table_name;
        right_table_name = physical_right_table_name;
    }
    left_table_name_transferred = true;
    right_table_name_transferred = true;
    left_source_cte_transferred = true;
    right_source_cte_transferred = true;
    const ctes = if (implicit_graph_cte_count != 0) ctes: {
        const out = try alloc.alloc(db_mod.types.RelationalRowsCte, implicit_graph_cte_count);
        var out_index: usize = 0;
        if (left_graph_source) |*source| {
            out[out_index] = source.cte;
            out_index += 1;
            source.cte = .{ .name = "" };
            plan_mod.freeTableAlias(alloc, source.table_ref);
            source.table_ref = .{ .name = "", .alias = "" };
            left_graph_source_transferred = true;
        }
        if (right_graph_source) |*source| {
            out[out_index] = source.cte;
            out_index += 1;
            source.cte = .{ .name = "" };
            plan_mod.freeTableAlias(alloc, source.table_ref);
            source.table_ref = .{ .name = "", .alias = "" };
            right_graph_source_transferred = true;
        }
        break :ctes out;
    } else &.{};
    return .{
        .left_table_name = left_table_name,
        .right_table_name = right_table_name,
        .ctes = ctes,
        .join = join_request,
    };
}

fn freeSelectListAlloc(alloc: std.mem.Allocator, select: plan_mod.SelectList) void {
    strings.freeStringSlice(alloc, select.fields);
    plan_mod.freeJsonExtract(alloc, select.json_extract);
    plan_mod.freeArrayLengthProjections(alloc, select.array_length);
    plan_mod.freeCoalesceProjections(alloc, select.coalesce);
    plan_mod.freeFieldAliasProjections(alloc, select.field_aliases);
    plan_mod.freeExpressionProjections(alloc, select.expressions);
    plan_mod.freeScalarSubqueryProjections(alloc, select.scalar_subqueries);
    if (select.outputs.len > 0) alloc.free(select.outputs);
}

pub fn parseLateralSubqueryAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: LateralSubqueryParserOptions,
) !plan_mod.LateralSubquery {
    if (options.generated_read_ast) |read| try generated_read_validate.validateGeneratedReadAstPayloads(tokens, read.*);
    try parser.expectKeyword(tokens, pos, "select");
    const inferred_table_ref: ?plan_mod.TableAlias = if (try generated_read_validate.inferGeneratedTableAliasFromReadSourceAlloc(alloc, tokens, pos.*, options.generated_read_ast, false)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.inferSelectSourceAliasAlloc(alloc, tokens, pos.*);
    defer if (inferred_table_ref) |value| plan_mod.freeTableAlias(alloc, value);

    const initial_context = options.context_hooks.get_context(options.context_hooks.ptr);
    defer options.context_hooks.set_context(options.context_hooks.ptr, initial_context);
    const left_schema = initial_context.schema;
    const right_base_schema = initial_context.joined_source_schema orelse initial_context.schema;

    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
    var right_parse_schema = right_base_schema;
    if (inferred_table_ref) |value| {
        if (plan_mod.findCteByName(options.available_ctes, value.name) != null) {
            planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, right_base_schema, options.available_ctes);
            right_parse_schema = relational_rows.rowsPlannedCteSchema(planned_ctes, value.name) orelse return error.UnsupportedSqlShape;
        }
    }

    options.context_hooks.set_context(options.context_hooks.ptr, .{
        .schema = right_parse_schema,
        .joined_source_schema = right_parse_schema,
    });
    const select_context = options.context_hooks.get_context(options.context_hooks.ptr);
    const generated_projection_end = try generated_read_validate.generatedProjectionClauseEnd(tokens, pos.*, options.generated_read_ast, false);
    const select = try expr_projection.parseSelectListAlloc(
        alloc,
        tokens,
        pos,
        .{
            .params = options.params,
            .output_schema = right_parse_schema,
            .select_item_schema = select_context.schema,
            .function_bindings = options.function_bindings,
            .type_context = .{
                .alloc = alloc,
                .schema = select_context.schema,
                .joined_source_schema = select_context.joined_source_schema,
            },
            .field_source = options.field_source,
            .select_item_options = options.select_item_options,
            .generated_read_ast = options.generated_read_ast,
        },
    );
    defer freeSelectListAlloc(alloc, select);
    if (generated_projection_end) |end| {
        if (pos.* != end) return error.UnsupportedSqlShape;
    }
    const output_columns = try expr_projection.selectOutputColumnsAlloc(alloc, .{
        .alloc = alloc,
        .schema = right_parse_schema,
        .joined_source_schema = right_parse_schema,
    }, select);
    errdefer ddl_plan.freeDdlRelationalColumns(alloc, output_columns);

    options.context_hooks.set_context(options.context_hooks.ptr, .{
        .schema = left_schema,
        .joined_source_schema = right_parse_schema,
    });
    if (select.select_all) return error.UnsupportedSqlShape;

    try parser.expectKeyword(tokens, pos, "from");
    const right_table = if (try generated_read_validate.generatedTableAliasFromReadSourceAlloc(alloc, tokens, pos, options.generated_read_ast, false)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    errdefer plan_mod.freeTableAlias(alloc, right_table);
    if (inferred_table_ref) |value| {
        if (!std.mem.eql(u8, right_table.name, value.name) or !std.mem.eql(u8, right_table.alias, value.alias)) return error.UnsupportedSqlShape;
    }

    var predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, predicates.items);
        predicates.deinit(alloc);
    }
    var json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, json_contains.items);
        json_contains.deinit(alloc);
    }
    var json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, json_path_exists.items);
        json_path_exists.deinit(alloc);
    }
    var array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, array_contains.items);
        array_contains.deinit(alloc);
    }
    var array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, array_eq.items);
        array_eq.deinit(alloc);
    }
    var in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, in_predicates.items);
        in_predicates.deinit(alloc);
    }
    var text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, text_patterns.items);
        text_patterns.deinit(alloc);
    }
    var expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, expression_predicates.items);
        expression_predicates.deinit(alloc);
    }
    var expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_or_predicates.items);
        expression_or_predicates.deinit(alloc);
    }
    var expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, expression_not_predicates.items);
        expression_not_predicates.deinit(alloc);
    }
    var expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, expression_array_contains.items);
        expression_array_contains.deinit(alloc);
    }
    var match_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, match_expression_predicates.items);
        match_expression_predicates.deinit(alloc);
    }
    var match_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, match_expression_or_predicates.items);
        match_expression_or_predicates.deinit(alloc);
    }
    var match_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, match_expression_not_predicates.items);
        match_expression_not_predicates.deinit(alloc);
    }
    var match_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, match_expression_array_contains.items);
        match_expression_array_contains.deinit(alloc);
    }
    var correlations = std.ArrayListUnmanaged(db_mod.types.RelationalRowsLateralCorrelation).empty;
    errdefer {
        plan_mod.freeLateralCorrelations(alloc, correlations.items);
        correlations.deinit(alloc);
    }
    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }

    var limit: ?u32 = null;
    var offset: u32 = 0;
    while (!parser.atEnd(tokens, pos.*)) {
        if (parser.matchKeyword(tokens, pos, "where")) {
            const keyword_index = pos.* - 1;
            const generated_where_end = try generated_read_validate.generatedWhereClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast, false);
            const generated_where_expression = try generated_read_validate.requireGeneratedWhereExpressionForClause(pos.*, options.generated_read_ast, false, generated_where_end);
            var targets = LateralWherePredicateTargets{
                .predicates = &predicates,
                .json_contains = &json_contains,
                .json_path_exists = &json_path_exists,
                .array_contains = &array_contains,
                .array_eq = &array_eq,
                .in_predicates = &in_predicates,
                .text_patterns = &text_patterns,
                .expression_predicates = &expression_predicates,
                .expression_or_predicates = &expression_or_predicates,
                .expression_not_predicates = &expression_not_predicates,
                .expression_array_contains = &expression_array_contains,
                .match_expression_predicates = &match_expression_predicates,
                .match_expression_or_predicates = &match_expression_or_predicates,
                .match_expression_not_predicates = &match_expression_not_predicates,
                .match_expression_array_contains = &match_expression_array_contains,
                .correlations = &correlations,
            };
            try parseLateralWhereAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                left_schema,
                right_parse_schema,
                options.left_alias,
                right_table.alias,
                expr_predicate.stringToArrayPredicateIsContainment(tokens, pos.*),
                &targets,
                options.expression_where_options,
                options.realtime_ns,
                generated_where_expression,
            );
            if (generated_where_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "order")) {
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_order_end = try generated_read_validate.generatedOrderClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            try expr_order.parseSelectOutputByAlloc(
                alloc,
                tokens,
                pos,
                &order_by,
                select,
                .{
                    .schema = left_schema,
                    .function_bindings = options.function_bindings,
                    .field_expression_qualifiers = &.{},
                    .returning_expression_qualifiers = &.{},
                    .defer_row_expression_field_validation = false,
                    .type_context = .{ .alloc = alloc, .schema = left_schema },
                    .order_expression_hooks = options.order_expression_hooks,
                    .generated_read_ast = options.generated_read_ast,
                },
            );
            if (generated_order_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "limit")) {
            const keyword_index = pos.* - 1;
            limit = (try generated_read_validate.parseLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "offset")) {
            const keyword_index = pos.* - 1;
            offset = try generated_read_validate.parseOffsetValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast);
        } else if (parser.matchKeyword(tokens, pos, "fetch")) {
            const keyword_index = pos.* - 1;
            limit = (try generated_read_validate.parseFetchLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else {
            return error.UnsupportedSqlShape;
        }
    }
    if (limit == null or correlations.items.len == 0) return error.UnsupportedSqlShape;

    return .{
        .table = right_table,
        .output_columns = output_columns,
        .predicates = try predicates.toOwnedSlice(alloc),
        .json_contains = try json_contains.toOwnedSlice(alloc),
        .json_path_exists = try json_path_exists.toOwnedSlice(alloc),
        .array_contains = try array_contains.toOwnedSlice(alloc),
        .array_eq = try array_eq.toOwnedSlice(alloc),
        .in_predicates = try in_predicates.toOwnedSlice(alloc),
        .text_patterns = try text_patterns.toOwnedSlice(alloc),
        .expression_predicates = try expression_predicates.toOwnedSlice(alloc),
        .expression_or_predicates = try expression_or_predicates.toOwnedSlice(alloc),
        .expression_not_predicates = try expression_not_predicates.toOwnedSlice(alloc),
        .expression_array_contains = try expression_array_contains.toOwnedSlice(alloc),
        .match_expression_predicates = try match_expression_predicates.toOwnedSlice(alloc),
        .match_expression_or_predicates = try match_expression_or_predicates.toOwnedSlice(alloc),
        .match_expression_not_predicates = try match_expression_not_predicates.toOwnedSlice(alloc),
        .match_expression_array_contains = try match_expression_array_contains.toOwnedSlice(alloc),
        .correlations = try correlations.toOwnedSlice(alloc),
        .order_by = try order_by.toOwnedSlice(alloc),
        .limit = limit,
        .offset = offset,
    };
}

pub fn parseLateralAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    options: LateralParserOptions,
) !plan_mod.LoweredLateralPlan {
    if (options.generated_read_ast) |read| try generated_read_validate.validateGeneratedReadAstPayloads(tokens, read.*);
    try generated_read_validate.validateGeneratedJoinExecutableContract(options.generated_read_ast, tokens, .lateral);
    try parser.expectKeyword(tokens, pos, "select");

    const raw_select = if (try generated_read_validate.generatedJoinProjectionListAlloc(alloc, options.generated_read_ast, tokens, pos)) |generated_projections|
        generated_projections
    else
        try plan_mod.parseJoinProjectionListAlloc(alloc, tokens, pos);
    defer plan_mod.freeQualifiedProjections(alloc, raw_select);

    try parser.expectKeyword(tokens, pos, "from");
    const left_tokens_start = pos.*;
    const left_table = if (try generated_read_validate.generatedTableAliasFromJoinSideAlloc(alloc, tokens, pos, options.generated_read_ast, .left)) |generated_table_ref|
        generated_table_ref
    else
        try plan_mod.parseTableAliasAlloc(alloc, tokens, pos);
    defer plan_mod.freeTableAlias(alloc, left_table);
    const operator_tokens_start = pos.*;

    const initial_context = options.context_hooks.get_context(options.context_hooks.ptr);
    defer options.context_hooks.set_context(options.context_hooks.ptr, initial_context);
    var planned_ctes: []relational_rows.RowsPlannedCte = &.{};
    defer relational_rows.freeRowsPlannedCtes(alloc, planned_ctes);
    if (options.available_ctes.len != 0) {
        const cte_base_schema = initial_context.joined_source_schema orelse initial_context.schema;
        planned_ctes = try relational_rows.planRowsCteOutputsAlloc(alloc, cte_base_schema, options.available_ctes);
    }
    const left_source_schema = relational_rows.rowsPlannedCteSchema(planned_ctes, left_table.name) orelse initial_context.schema;
    const right_source_schema = initial_context.joined_source_schema orelse initial_context.schema;
    var current_context = JoinParserContext{
        .schema = left_source_schema,
        .joined_source_schema = right_source_schema,
    };
    options.context_hooks.set_context(options.context_hooks.ptr, current_context);

    try parser.expectKeyword(tokens, pos, "left");
    _ = parser.matchKeyword(tokens, pos, "outer");
    try parser.expectKeyword(tokens, pos, "join");
    const right_tokens_start = pos.*;
    try parser.expectKeyword(tokens, pos, "lateral");
    try parser.expectToken(tokens, pos, .lparen);
    const close_index = (parser.findMatchingRParenAfterOpenIndex(tokens, pos.*) orelse return error.UnsupportedSqlShape);
    const generated_lateral_subquery_read_ast = try generated_read_validate.generatedLateralSubqueryReadAstForRange(options.generated_read_ast, pos.*, close_index);
    var lateral_subquery = try options.subquery_hooks.parse_subquery(
        options.subquery_hooks.ptr,
        tokens[pos.*..close_index],
        left_source_schema,
        right_source_schema,
        left_table.alias,
        options.available_ctes,
        generated_lateral_subquery_read_ast,
    );
    errdefer plan_mod.freeLateralSubquery(alloc, lateral_subquery);
    pos.* = close_index + 1;

    const lateral_alias = if (try generated_read_validate.generatedLateralAliasAlloc(alloc, tokens, pos, options.generated_read_ast)) |generated_alias|
        generated_alias
    else
        try grammar.parseRequiredAliasAlloc(alloc, tokens, pos);
    defer alloc.free(lateral_alias);
    const condition_tokens_start = pos.*;

    current_context.joined_source_schema = .{
        .storage_mode = .relational,
        .relational_columns = lateral_subquery.output_columns,
    };
    options.context_hooks.set_context(options.context_hooks.ptr, current_context);

    try parser.expectKeyword(tokens, pos, "on");
    const predicate_tokens_start = pos.*;
    try parser.expectKeyword(tokens, pos, "true");
    try generated_read_validate.validateGeneratedSingleJoinForClause(
        options.generated_read_ast,
        .lateral,
        tokens,
        .{ .start = left_tokens_start, .end = operator_tokens_start },
        .{ .start = operator_tokens_start, .end = right_tokens_start },
        .left,
        .{ .start = right_tokens_start, .end = condition_tokens_start },
        .{ .start = condition_tokens_start, .end = pos.* },
        .{ .start = predicate_tokens_start, .end = pos.* },
    );

    var left_predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    errdefer {
        freeRelationalChecks(alloc, left_predicates.items);
        left_predicates.deinit(alloc);
    }
    var left_json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    errdefer {
        freeJsonContains(alloc, left_json_contains.items);
        left_json_contains.deinit(alloc);
    }
    var left_json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    errdefer {
        freeJsonPathExists(alloc, left_json_path_exists.items);
        left_json_path_exists.deinit(alloc);
    }
    var left_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    errdefer {
        freeArrayContains(alloc, left_array_contains.items);
        left_array_contains.deinit(alloc);
    }
    var left_array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    errdefer {
        freeArrayEq(alloc, left_array_eq.items);
        left_array_eq.deinit(alloc);
    }
    var left_in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    errdefer {
        freeInPredicates(alloc, left_in_predicates.items);
        left_in_predicates.deinit(alloc);
    }
    var left_text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    errdefer {
        freeTextPatterns(alloc, left_text_patterns.items);
        left_text_patterns.deinit(alloc);
    }
    var left_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, left_expression_predicates.items);
        left_expression_predicates.deinit(alloc);
    }
    var left_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, left_expression_or_predicates.items);
        left_expression_or_predicates.deinit(alloc);
    }
    var left_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, left_expression_not_predicates.items);
        left_expression_not_predicates.deinit(alloc);
    }
    var left_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, left_expression_array_contains.items);
        left_expression_array_contains.deinit(alloc);
    }
    var unsupported_right_predicates = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    defer {
        freeRelationalChecks(alloc, unsupported_right_predicates.items);
        unsupported_right_predicates.deinit(alloc);
    }
    var unsupported_right_json_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate).empty;
    defer {
        freeJsonContains(alloc, unsupported_right_json_contains.items);
        unsupported_right_json_contains.deinit(alloc);
    }
    var unsupported_right_json_path_exists = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonPathExistsPredicate).empty;
    defer {
        freeJsonPathExists(alloc, unsupported_right_json_path_exists.items);
        unsupported_right_json_path_exists.deinit(alloc);
    }
    var unsupported_right_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayContainsPredicate).empty;
    defer {
        freeArrayContains(alloc, unsupported_right_array_contains.items);
        unsupported_right_array_contains.deinit(alloc);
    }
    var unsupported_right_array_eq = std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayEqPredicate).empty;
    defer {
        freeArrayEq(alloc, unsupported_right_array_eq.items);
        unsupported_right_array_eq.deinit(alloc);
    }
    var unsupported_right_in_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate).empty;
    defer {
        freeInPredicates(alloc, unsupported_right_in_predicates.items);
        unsupported_right_in_predicates.deinit(alloc);
    }
    var unsupported_right_text_patterns = std.ArrayListUnmanaged(db_mod.types.RelationalRowsTextPatternPredicate).empty;
    defer {
        freeTextPatterns(alloc, unsupported_right_text_patterns.items);
        unsupported_right_text_patterns.deinit(alloc);
    }
    var unsupported_right_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    defer {
        freeExpressionConditions(alloc, unsupported_right_expression_predicates.items);
        unsupported_right_expression_predicates.deinit(alloc);
    }
    var unsupported_right_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    defer {
        freeExpressionPredicateGroups(alloc, unsupported_right_expression_or_predicates.items);
        unsupported_right_expression_or_predicates.deinit(alloc);
    }
    var unsupported_right_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    defer {
        freeExpressionPredicateGroups(alloc, unsupported_right_expression_not_predicates.items);
        unsupported_right_expression_not_predicates.deinit(alloc);
    }
    var unsupported_right_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    defer {
        freeExpressionArrayContains(alloc, unsupported_right_expression_array_contains.items);
        unsupported_right_expression_array_contains.deinit(alloc);
    }
    var match_expression_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition).empty;
    errdefer {
        freeExpressionConditions(alloc, match_expression_predicates.items);
        match_expression_predicates.deinit(alloc);
    }
    var match_expression_or_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, match_expression_or_predicates.items);
        match_expression_or_predicates.deinit(alloc);
    }
    var match_expression_not_predicates = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup).empty;
    errdefer {
        freeExpressionPredicateGroups(alloc, match_expression_not_predicates.items);
        match_expression_not_predicates.deinit(alloc);
    }
    var match_expression_array_contains = std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionArrayContainsPredicate).empty;
    errdefer {
        freeExpressionArrayContains(alloc, match_expression_array_contains.items);
        match_expression_array_contains.deinit(alloc);
    }
    var select = std.ArrayListUnmanaged(db_mod.types.RelationalRowsJoinProjection).empty;
    errdefer {
        plan_mod.freeJoinProjections(alloc, select.items);
        select.deinit(alloc);
    }
    try binder.resolveJoinProjectionsAlloc(alloc, current_context.schema, current_context.joined_source_schema, raw_select, left_table.alias, lateral_alias, &select);

    var order_by = std.ArrayListUnmanaged(db_mod.types.RelationalRowsQueryOrder).empty;
    errdefer {
        freeOrderBy(alloc, order_by.items);
        order_by.deinit(alloc);
    }
    var limit: ?u32 = null;
    var offset: u32 = 0;
    while (!parser.atEnd(tokens, pos.*)) {
        if (parser.matchKeyword(tokens, pos, "where")) {
            const keyword_index = pos.* - 1;
            const generated_where_end = try generated_read_validate.generatedWhereClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast, false);
            const generated_where_expression = try generated_read_validate.requireGeneratedWhereExpressionForClause(pos.*, options.generated_read_ast, false, generated_where_end);
            var where_targets = JoinWherePredicateTargets{
                .left_predicates = &left_predicates,
                .right_predicates = &unsupported_right_predicates,
                .left_json_contains = &left_json_contains,
                .right_json_contains = &unsupported_right_json_contains,
                .left_json_path_exists = &left_json_path_exists,
                .right_json_path_exists = &unsupported_right_json_path_exists,
                .left_array_contains = &left_array_contains,
                .right_array_contains = &unsupported_right_array_contains,
                .left_array_eq = &left_array_eq,
                .right_array_eq = &unsupported_right_array_eq,
                .left_in_predicates = &left_in_predicates,
                .right_in_predicates = &unsupported_right_in_predicates,
                .left_text_patterns = &left_text_patterns,
                .right_text_patterns = &unsupported_right_text_patterns,
                .left_expression_predicates = &left_expression_predicates,
                .right_expression_predicates = &unsupported_right_expression_predicates,
                .left_expression_or_predicates = &left_expression_or_predicates,
                .right_expression_or_predicates = &unsupported_right_expression_or_predicates,
                .left_expression_not_predicates = &left_expression_not_predicates,
                .right_expression_not_predicates = &unsupported_right_expression_not_predicates,
                .left_expression_array_contains = &left_expression_array_contains,
                .right_expression_array_contains = &unsupported_right_expression_array_contains,
                .match_expression_predicates = &match_expression_predicates,
                .match_expression_or_predicates = &match_expression_or_predicates,
                .match_expression_not_predicates = &match_expression_not_predicates,
                .match_expression_array_contains = &match_expression_array_contains,
            };
            try parseJoinWhereAlloc(
                alloc,
                tokens,
                pos,
                options.params,
                current_context.schema,
                current_context.joined_source_schema,
                left_table.alias,
                lateral_alias,
                options.string_to_array_predicate_is_containment,
                &where_targets,
                options.expression_where_options,
                options.realtime_ns,
                generated_where_expression,
            );
            if (generated_where_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
            if (unsupported_right_predicates.items.len != 0 or
                unsupported_right_json_contains.items.len != 0 or
                unsupported_right_json_path_exists.items.len != 0 or
                unsupported_right_array_contains.items.len != 0 or
                unsupported_right_array_eq.items.len != 0 or
                unsupported_right_in_predicates.items.len != 0 or
                unsupported_right_text_patterns.items.len != 0 or
                unsupported_right_expression_predicates.items.len != 0 or
                unsupported_right_expression_or_predicates.items.len != 0 or
                unsupported_right_expression_not_predicates.items.len != 0 or
                unsupported_right_expression_array_contains.items.len != 0) return error.UnsupportedSqlShape;
        } else if (parser.matchKeyword(tokens, pos, "order")) {
            const keyword_index = pos.* - 1;
            try parser.expectKeyword(tokens, pos, "by");
            const generated_order_end = try generated_read_validate.generatedOrderClauseEnd(tokens, keyword_index, pos.*, options.generated_read_ast);
            try expr_order.parseJoinByAlloc(
                alloc,
                tokens,
                pos,
                current_context.schema,
                &order_by,
                select.items,
                blk: {
                    var order_options = options.output_order_expression_options;
                    order_options.generated_read_ast = options.generated_read_ast;
                    break :blk order_options;
                },
            );
            if (generated_order_end) |end| {
                if (pos.* != end) return error.UnsupportedSqlShape;
            }
        } else if (parser.matchKeyword(tokens, pos, "limit")) {
            const keyword_index = pos.* - 1;
            limit = (try generated_read_validate.parseLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchKeyword(tokens, pos, "offset")) {
            const keyword_index = pos.* - 1;
            offset = try generated_read_validate.parseOffsetValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast);
        } else if (parser.matchKeyword(tokens, pos, "fetch")) {
            const keyword_index = pos.* - 1;
            limit = (try generated_read_validate.parseFetchLimitValueForClause(tokens, keyword_index, pos, options.params, options.generated_read_ast)).value;
        } else if (parser.matchToken(tokens, pos, .semicolon) != null) {
            if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
        } else {
            return error.UnsupportedSqlShape;
        }
    }

    if (lateral_subquery.match_expression_predicates.len > 0) {
        try match_expression_predicates.appendSlice(alloc, lateral_subquery.match_expression_predicates);
        alloc.free(lateral_subquery.match_expression_predicates);
        lateral_subquery.match_expression_predicates = &.{};
    }
    if (lateral_subquery.match_expression_or_predicates.len > 0) {
        try match_expression_or_predicates.appendSlice(alloc, lateral_subquery.match_expression_or_predicates);
        alloc.free(lateral_subquery.match_expression_or_predicates);
        lateral_subquery.match_expression_or_predicates = &.{};
    }
    if (lateral_subquery.match_expression_not_predicates.len > 0) {
        try match_expression_not_predicates.appendSlice(alloc, lateral_subquery.match_expression_not_predicates);
        alloc.free(lateral_subquery.match_expression_not_predicates);
        lateral_subquery.match_expression_not_predicates = &.{};
    }
    if (lateral_subquery.match_expression_array_contains.len > 0) {
        try match_expression_array_contains.appendSlice(alloc, lateral_subquery.match_expression_array_contains);
        alloc.free(lateral_subquery.match_expression_array_contains);
        lateral_subquery.match_expression_array_contains = &.{};
    }

    const left_table_name = try alloc.dupe(u8, left_table.name);
    var left_table_name_transferred = false;
    errdefer if (!left_table_name_transferred) alloc.free(left_table_name);
    const right_table_name = try alloc.dupe(u8, lateral_subquery.table.name);
    var right_table_name_transferred = false;
    errdefer if (!right_table_name_transferred) alloc.free(right_table_name);
    const plan_left_table_name = try alloc.dupe(u8, left_table.name);
    var plan_left_table_name_transferred = false;
    errdefer if (!plan_left_table_name_transferred) alloc.free(plan_left_table_name);
    const plan_right_table_name = try alloc.dupe(u8, lateral_subquery.table.name);
    var plan_right_table_name_transferred = false;
    errdefer if (!plan_right_table_name_transferred) alloc.free(plan_right_table_name);

    const left_owned_predicates = try left_predicates.toOwnedSlice(alloc);
    const left_owned_json_contains = try left_json_contains.toOwnedSlice(alloc);
    const left_owned_json_path_exists = try left_json_path_exists.toOwnedSlice(alloc);
    const left_owned_array_contains = try left_array_contains.toOwnedSlice(alloc);
    const left_owned_array_eq = try left_array_eq.toOwnedSlice(alloc);
    const left_owned_in_predicates = try left_in_predicates.toOwnedSlice(alloc);
    const left_owned_text_patterns = try left_text_patterns.toOwnedSlice(alloc);
    const left_owned_expression_predicates = try left_expression_predicates.toOwnedSlice(alloc);
    const left_owned_expression_or_predicates = try left_expression_or_predicates.toOwnedSlice(alloc);
    const left_owned_expression_not_predicates = try left_expression_not_predicates.toOwnedSlice(alloc);
    const left_owned_expression_array_contains = try left_expression_array_contains.toOwnedSlice(alloc);
    const match_owned_expression_predicates = try match_expression_predicates.toOwnedSlice(alloc);
    const match_owned_expression_or_predicates = try match_expression_or_predicates.toOwnedSlice(alloc);
    const match_owned_expression_not_predicates = try match_expression_not_predicates.toOwnedSlice(alloc);
    const match_owned_expression_array_contains = try match_expression_array_contains.toOwnedSlice(alloc);
    const select_owned = try select.toOwnedSlice(alloc);
    const order_owned = try order_by.toOwnedSlice(alloc);

    const right_predicates = lateral_subquery.predicates;
    const right_json_contains = lateral_subquery.json_contains;
    const right_json_path_exists = lateral_subquery.json_path_exists;
    const right_array_contains = lateral_subquery.array_contains;
    const right_array_eq = lateral_subquery.array_eq;
    const right_in_predicates = lateral_subquery.in_predicates;
    const right_text_patterns = lateral_subquery.text_patterns;
    const right_expression_predicates = lateral_subquery.expression_predicates;
    const right_expression_or_predicates = lateral_subquery.expression_or_predicates;
    const right_expression_not_predicates = lateral_subquery.expression_not_predicates;
    const right_expression_array_contains = lateral_subquery.expression_array_contains;
    const correlations = lateral_subquery.correlations;
    const right_order_by = lateral_subquery.order_by;
    const right_limit = lateral_subquery.limit;
    const right_offset = lateral_subquery.offset;
    lateral_subquery.predicates = &.{};
    lateral_subquery.json_contains = &.{};
    lateral_subquery.json_path_exists = &.{};
    lateral_subquery.array_contains = &.{};
    lateral_subquery.array_eq = &.{};
    lateral_subquery.in_predicates = &.{};
    lateral_subquery.text_patterns = &.{};
    lateral_subquery.expression_predicates = &.{};
    lateral_subquery.expression_or_predicates = &.{};
    lateral_subquery.expression_not_predicates = &.{};
    lateral_subquery.expression_array_contains = &.{};
    lateral_subquery.correlations = &.{};
    lateral_subquery.order_by = &.{};
    ddl_plan.freeDdlRelationalColumns(alloc, lateral_subquery.output_columns);
    lateral_subquery.output_columns = &.{};
    plan_mod.freeTableAlias(alloc, lateral_subquery.table);
    lateral_subquery.table = .{ .name = "", .alias = "" };

    left_table_name_transferred = true;
    right_table_name_transferred = true;
    plan_left_table_name_transferred = true;
    plan_right_table_name_transferred = true;
    return .{
        .left_table_name = left_table_name,
        .right_table_name = right_table_name,
        .plan = .{
            .left_table = plan_left_table_name,
            .right_table = plan_right_table_name,
            .lateral = .{
                .left = .{
                    .predicates = left_owned_predicates,
                    .json_contains = left_owned_json_contains,
                    .json_path_exists = left_owned_json_path_exists,
                    .array_contains = left_owned_array_contains,
                    .array_eq = left_owned_array_eq,
                    .in_predicates = left_owned_in_predicates,
                    .text_patterns = left_owned_text_patterns,
                    .expression_predicates = left_owned_expression_predicates,
                    .expression_or_predicates = left_owned_expression_or_predicates,
                    .expression_not_predicates = left_owned_expression_not_predicates,
                    .expression_array_contains = left_owned_expression_array_contains,
                    .select_all = true,
                },
                .right = .{
                    .predicates = right_predicates,
                    .json_contains = right_json_contains,
                    .json_path_exists = right_json_path_exists,
                    .array_contains = right_array_contains,
                    .array_eq = right_array_eq,
                    .in_predicates = right_in_predicates,
                    .text_patterns = right_text_patterns,
                    .expression_predicates = right_expression_predicates,
                    .expression_or_predicates = right_expression_or_predicates,
                    .expression_not_predicates = right_expression_not_predicates,
                    .expression_array_contains = right_expression_array_contains,
                    .select_all = true,
                    .order_by = right_order_by,
                    .limit = right_limit,
                    .offset = right_offset,
                },
                .correlations = correlations,
                .match_expression_predicates = match_owned_expression_predicates,
                .match_expression_or_predicates = match_owned_expression_or_predicates,
                .match_expression_not_predicates = match_owned_expression_not_predicates,
                .match_expression_array_contains = match_owned_expression_array_contains,
                .select = select_owned,
                .order_by = order_owned,
                .limit = limit,
                .offset = offset,
            },
        },
    };
}

pub fn parseQueryPlanAlloc(
    alloc: std.mem.Allocator,
    tokens: []const Token,
    pos: *usize,
    params: []const value_mod.SqlValue,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
    cte_hooks: plan_mod.CteSelectParserHooks,
    query_hooks: QueryPlanParserHooks,
    tail_hooks: plan_mod.SimpleSelectSetTailHooks,
) !plan_mod.LoweredQueryPlan {
    if (!parser.peekKeyword(tokens, pos.*, "with")) {
        var lowered = try parseQueryPlanSelectWithContext(query_hooks, &.{}, true, false);
        errdefer lowered.deinit(alloc);
        var parsed_set_operation = false;
        while (grammar.nextIsSelectSetOperationKeyword(tokens, pos.*)) {
            parsed_set_operation = true;
            if (lowered.ctes.len != 0) return error.UnsupportedSqlShape;
            const generated_op = try parseGeneratedSelectSetOperation(tokens, pos, generated_read_ast);
            const op = generated_op orelse try grammar.parseSelectSetOperation(tokens, pos);
            var rhs = try parseQueryPlanSelectWithContext(query_hooks, &.{}, true, true);
            defer rhs.deinit(alloc);
            if (rhs.ctes.len != 0) return error.UnsupportedSqlShape;
            if (lowered.system_time_as_of_sequence != null or rhs.system_time_as_of_sequence != null or
                lowered.system_time_as_of_timestamp_ns != null or rhs.system_time_as_of_timestamp_ns != null) return error.UnsupportedSqlShape;
            try select_set.applySimpleSelectSetOperationAlloc(alloc, &lowered, rhs, op);
        }
        if (parsed_set_operation and !parser.atEnd(tokens, pos.*)) {
            try plan_mod.parseSimpleSelectSetResultTailAlloc(alloc, tokens, pos, params, generated_read_ast, &lowered, tail_hooks);
        }
        if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
        var base_table_name: ?[]const u8 = null;
        defer if (base_table_name) |table| alloc.free(table);
        if (lowered.ctes.len != 0) try plan_mod.resolveSelectSourceForPlanAlloc(alloc, &lowered, lowered.ctes, &base_table_name);
        const table_name = if (lowered.ctes.len != 0) blk: {
            const base = base_table_name orelse return error.UnsupportedSqlShape;
            base_table_name = null;
            alloc.free(lowered.table_name);
            lowered.table_name = "";
            break :blk base;
        } else blk: {
            const table = lowered.table_name;
            lowered.table_name = "";
            break :blk table;
        };
        const ctes = lowered.ctes;
        const system_time_as_of_sequence = lowered.system_time_as_of_sequence;
        const system_time_as_of_timestamp_ns = lowered.system_time_as_of_timestamp_ns;
        lowered.ctes = &.{};
        lowered.clearSelectOutputs(alloc);
        return .{
            .table_name = table_name,
            .plan = .{
                .ctes = ctes,
                .query = lowered.query,
            },
            .system_time_as_of_sequence = system_time_as_of_sequence,
            .system_time_as_of_timestamp_ns = system_time_as_of_timestamp_ns,
        };
    }

    var base_table_name: ?[]const u8 = null;
    defer if (base_table_name) |table| alloc.free(table);
    const ctes = try plan_mod.parseCtesForPlanAlloc(alloc, tokens, pos, &base_table_name, cte_hooks);
    var ctes_transferred = false;
    errdefer if (!ctes_transferred) plan_mod.freePlanCtes(alloc, ctes);

    var final = try parseQueryPlanSelectWithContext(query_hooks, ctes, true, false);
    errdefer final.deinit(alloc);
    try plan_mod.resolveSelectSourceForPlanAlloc(alloc, &final, ctes, &base_table_name);
    var parsed_set_operation = false;
    while (grammar.nextIsSelectSetOperationKeyword(tokens, pos.*)) {
        parsed_set_operation = true;
        const generated_op = try parseGeneratedSelectSetOperation(tokens, pos, generated_read_ast);
        const op = generated_op orelse try grammar.parseSelectSetOperation(tokens, pos);
        var rhs = try parseQueryPlanSelectWithContext(query_hooks, ctes, true, true);
        defer rhs.deinit(alloc);
        try plan_mod.resolveSelectSourceForPlanAlloc(alloc, &rhs, ctes, &base_table_name);
        if (final.system_time_as_of_sequence != null or rhs.system_time_as_of_sequence != null or
            final.system_time_as_of_timestamp_ns != null or rhs.system_time_as_of_timestamp_ns != null) return error.UnsupportedSqlShape;
        try select_set.applySimpleSelectSetOperationAlloc(alloc, &final, rhs, op);
    }
    if (parsed_set_operation and !parser.atEnd(tokens, pos.*)) {
        try plan_mod.parseSimpleSelectSetResultTailAlloc(alloc, tokens, pos, params, generated_read_ast, &final, tail_hooks);
    }
    if (parser.matchToken(tokens, pos, .semicolon) != null and !parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;
    if (!parser.atEnd(tokens, pos.*)) return error.UnsupportedSqlShape;

    const table_name = base_table_name orelse return error.UnsupportedSqlShape;
    const system_time_as_of_sequence = final.system_time_as_of_sequence;
    const system_time_as_of_timestamp_ns = final.system_time_as_of_timestamp_ns;
    base_table_name = null;
    alloc.free(final.table_name);
    final.table_name = "";
    final.clearSelectOutputs(alloc);
    ctes_transferred = true;
    return .{
        .table_name = table_name,
        .plan = .{
            .ctes = ctes,
            .query = final.query,
        },
        .system_time_as_of_sequence = system_time_as_of_sequence,
        .system_time_as_of_timestamp_ns = system_time_as_of_timestamp_ns,
    };
}

fn parseGeneratedSelectSetOperation(
    tokens: []const Token,
    pos: *usize,
    generated_read_ast: ?*const generated_parser.GeneratedSqlReadAst,
) !?ast.SelectSetOperation {
    const read = generated_read_ast orelse return null;
    const range = read.set_operation_tokens orelse return error.UnsupportedSqlShape;
    if (range.start != pos.*) {
        if (pos.* > range.start and pos.* < range.end) return null;
        return error.UnsupportedSqlShape;
    }
    if (range.start >= range.end or range.end > tokens.len) return error.UnsupportedSqlShape;
    const operator_tokens = read.set_operation.operator_tokens orelse return error.UnsupportedSqlShape;
    if (operator_tokens.start != range.start or operator_tokens.end != operator_tokens.start + 1 or operator_tokens.end > range.end) return error.UnsupportedSqlShape;
    const right_query = read.set_operation.right_query_tokens orelse return error.UnsupportedSqlShape;
    if (right_query.start < operator_tokens.end or right_query.end > range.end) return error.UnsupportedSqlShape;
    if (!tokens[right_query.start].matchesKeywordTag(.select)) return error.UnsupportedSqlShape;

    const op: ast.SelectSetOperation = switch (read.set_operation.kind orelse return error.UnsupportedSqlShape) {
        .@"union" => blk: {
            if (!tokens[operator_tokens.start].matchesKeywordTag(.@"union")) return error.UnsupportedSqlShape;
            if (read.set_operation.all_tokens) |all_tokens| {
                if (all_tokens.start != operator_tokens.end or all_tokens.end != all_tokens.start + 1 or all_tokens.end != right_query.start) return error.UnsupportedSqlShape;
                if (!tokens[all_tokens.start].matchesKeywordTag(.all)) return error.UnsupportedSqlShape;
                break :blk .union_all;
            }
            if (right_query.start == operator_tokens.end) break :blk .union_distinct;
            if (right_query.start == operator_tokens.end + 1 and tokens[operator_tokens.end].matchesKeywordTag(.distinct)) break :blk .union_distinct;
            return error.UnsupportedSqlShape;
        },
        .intersect => blk: {
            if (!tokens[operator_tokens.start].matchesKeywordTag(.intersect) or read.set_operation.all_tokens != null) return error.UnsupportedSqlShape;
            if (right_query.start == operator_tokens.end) break :blk .intersect;
            if (right_query.start == operator_tokens.end + 1 and tokens[operator_tokens.end].matchesKeywordTag(.distinct)) break :blk .intersect;
            return error.UnsupportedSqlShape;
        },
        .except => blk: {
            if (!tokens[operator_tokens.start].matchesKeywordTag(.except) or read.set_operation.all_tokens != null) return error.UnsupportedSqlShape;
            if (right_query.start == operator_tokens.end) break :blk .except;
            if (right_query.start == operator_tokens.end + 1 and tokens[operator_tokens.end].matchesKeywordTag(.distinct)) break :blk .except;
            return error.UnsupportedSqlShape;
        },
    };
    pos.* = right_query.start;
    return op;
}

fn parseQueryPlanSelectWithContext(
    hooks: QueryPlanParserHooks,
    available_ctes: []const db_mod.types.RelationalRowsCte,
    allow_select_set_boundary: bool,
    allow_select_set_result_tail_boundary: bool,
) !plan_mod.LoweredSelect {
    const previous_context = hooks.context_hooks.get_context(hooks.context_hooks.ptr);
    var context = previous_context;
    context.available_ctes = available_ctes;
    context.allow_select_set_boundary = allow_select_set_boundary;
    context.allow_select_set_result_tail_boundary = allow_select_set_result_tail_boundary;
    hooks.context_hooks.set_context(hooks.context_hooks.ptr, context);
    defer hooks.context_hooks.set_context(hooks.context_hooks.ptr, previous_context);

    return try hooks.parse_select(hooks.ptr);
}

fn stringSlicesEqual(a: []const []const u8, b: []const []const u8) bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| {
        if (!std.mem.eql(u8, left, right)) return false;
    }
    return true;
}

fn stringSlicesContains(values: []const []const u8, value: []const u8) bool {
    for (values) |candidate| {
        if (std.mem.eql(u8, candidate, value)) return true;
    }
    return false;
}

fn stringSlicesIntersect(a: []const []const u8, b: []const []const u8) bool {
    for (a) |value| {
        if (stringSlicesContains(b, value)) return true;
    }
    return false;
}

pub fn peekWindowOutputOrderExpression(tokens: []const Token, pos: usize) bool {
    return expr_aggregate.peekOutputOrderExpression(tokens, pos);
}

pub fn peekAggregateHavingExpression(tokens: []const Token, pos: usize) bool {
    if (expr_aggregate.nextIsFunction(tokens, pos)) return false;
    if (pos >= tokens.len) return false;
    const token = tokens[pos];
    if (expr_aggregate.peekParenthesizedExpressionCondition(tokens, pos)) return true;
    if (token.kind == .identifier) {
        if (pos + 1 >= tokens.len) return false;
        const next = tokens[pos + 1];
        if (next.kind == .eq or next.kind == .neq or next.kind == .gt or next.kind == .gte or next.kind == .lt or next.kind == .lte) return false;
        if (next.matchesKeywordTag(.is)) return false;
        return true;
    }
    return token.kind == .minus or
        token.kind == .number or
        parser.peekKeyword(tokens, pos, "lower") or
        parser.peekKeyword(tokens, pos, "upper") or
        parser.peekKeyword(tokens, pos, "trim") or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTrimVariantFunction) or
        parser.peekKeyword(tokens, pos, "replace") or
        parser.peekKeyword(tokens, pos, "regexp_replace") or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpSubstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpMatchFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpCountFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRegexpInstrFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsTranslateFunction) or
        parser.peekKeyword(tokens, pos, "case") or
        parser.peekKeyword(tokens, pos, "cast") or
        parser.peekKeyword(tokens, pos, "coalesce") or
        parser.peekKeyword(tokens, pos, "nullif") or
        expr_token.peekTextLengthFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsAsciiFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsChrFunction) or
        expr_token.peekSubstringFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsOverlayFunction) or
        expr_token.peekSplitPartFunctionKeyword(tokens, pos) or
        expr_token.peekStrposFunctionKeyword(tokens, pos) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsLeftRightFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsPadFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsRepeatFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsReverseFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsMd5Function) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsStartsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsEndsWithFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateTruncFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDateBinFunction) or
        expr_token.peekFunctionCallTokenIf(tokens, pos, expr_token.sqlTokenIsDatePartFunction) or
        parser.peekKeyword(tokens, pos, "position") or
        parser.peekKeyword(tokens, pos, "abs") or
        parser.peekKeyword(tokens, pos, "round") or
        expr_token.peekFunctionCallTag(tokens, pos, .trunc) or
        expr_token.peekFunctionCallTag(tokens, pos, .floor) or
        expr_token.peekFunctionCallTag(tokens, pos, .ceil) or
        expr_token.peekFunctionCallTag(tokens, pos, .sqrt) or
        expr_token.peekFunctionCallTag(tokens, pos, .sign) or
        expr_token.peekFunctionCallTag(tokens, pos, .mod) or
        expr_token.peekFunctionCallTag(tokens, pos, .power) or
        parser.peekKeyword(tokens, pos, "greatest") or
        parser.peekKeyword(tokens, pos, "least");
}

test "sql adapter expression keyword predicates classify function and tail tokens" {
    const length_tokens = [_]Token{
        .{ .kind = .identifier, .text = "char_length" },
        .{ .kind = .lparen, .text = "(" },
    };
    var length_pos: usize = 0;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.length, try expr_token.parseTextLengthFunctionCallStart(length_tokens[0..], &length_pos));
    try std.testing.expectEqual(@as(usize, 2), length_pos);

    const abs_tokens = [_]Token{
        .{ .kind = .identifier, .text = "abs" },
        .{ .kind = .lparen, .text = "(" },
    };
    var abs_pos: usize = 0;
    try expr_token.parseFixedUnaryFunctionCallStart(abs_tokens[0..], &abs_pos, .abs);
    try std.testing.expectEqual(@as(usize, 2), abs_pos);

    const mod_tokens = [_]Token{
        .{ .kind = .identifier, .text = "mod" },
        .{ .kind = .lparen, .text = "(" },
    };
    var mod_pos: usize = 0;
    try expr_token.parseFixedBinaryFunctionCallStart(mod_tokens[0..], &mod_pos, .mod);
    try std.testing.expectEqual(@as(usize, 2), mod_pos);

    const greatest_tokens = [_]Token{
        .{ .kind = .identifier, .text = "greatest" },
        .{ .kind = .lparen, .text = "(" },
    };
    var greatest_pos: usize = 0;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.greatest, try expr_token.parseGreatestLeastFunctionCallStart(greatest_tokens[0..], &greatest_pos));
    try std.testing.expectEqual(@as(usize, 2), greatest_pos);
    try std.testing.expect(expr_token.peekGreatestLeastFunctionCall(greatest_tokens[0..], 0));

    const case_fold_start_tokens = [_]Token{
        .{ .kind = .identifier, .text = "LTRIM", .keyword = .ltrim },
        .{ .kind = .lparen, .text = "(" },
    };
    var case_fold_start_pos: usize = 0;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.ltrim, try expr_token.parseCaseFoldFunctionCallStart(case_fold_start_tokens[0..], &case_fold_start_pos));
    try std.testing.expectEqual(@as(usize, 2), case_fold_start_pos);
    const quoted_case_fold_start_tokens = [_]Token{
        .{ .kind = .identifier, .text = "ltrim", .source_start = 0, .source_end = 7 },
