    ));
    var distinct_grouped_aggregate = try lowerAggregateForLowerExprTestAlloc(
        alloc,
        "SELECT DISTINCT customer, COUNT(*) AS row_count FROM usage_records GROUP BY customer HAVING COUNT(*) > 0 ORDER BY COUNT(*) DESC",
