test "sql adapter lower expr lowers grouped aggregate queries with generated group validation" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const schema = try runtimeSchemaFromJsonForLowerExprTestAlloc(alloc, schema_json);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerAggregateForLowerExprTestAlloc(
        alloc,
        "SELECT status, SUM(amount) AS total FROM usage_records GROUP BY status ORDER BY total DESC LIMIT 5",
        schema,
        &.{},
    );
    defer lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), lowered.aggregate.group_by.len);
    try std.testing.expectEqualStrings("status", lowered.aggregate.group_by[0]);

    var malformed_group = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT status, SUM(amount) AS total FROM usage_records GROUP BY status ORDER BY total DESC LIMIT 5",
    );
    defer malformed_group.deinit(alloc);
    try corruptGeneratedReadFirstGroupExpressionItem(&malformed_group);
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedAggregateForLowerExprTestAlloc(
        alloc,
        &malformed_group,
        schema,
        &.{},
    ));

    var malformed_group_kind = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT status, SUM(amount) AS total FROM usage_records GROUP BY status ORDER BY total DESC LIMIT 5",
    );
    defer malformed_group_kind.deinit(alloc);
    try corruptGeneratedReadFirstGroupExpressionKind(&malformed_group_kind, .current_date);
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedAggregateForLowerExprTestAlloc(
        alloc,
        &malformed_group_kind,
        schema,
        &.{},
    ));

    var malformed_group_operator = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT amount + 1 AS amount_bucket, COUNT(*) AS total FROM usage_records GROUP BY amount + 1 ORDER BY total DESC LIMIT 5",
    );
    defer malformed_group_operator.deinit(alloc);
    try corruptGeneratedReadFirstGroupExpressionOperatorToTokens(&malformed_group_operator);
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedAggregateForLowerExprTestAlloc(
        alloc,
        &malformed_group_operator,
        schema,
        &.{},
    ));

    var malformed_group_arithmetic_kind = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT amount + 1 AS amount_bucket, COUNT(*) AS total FROM usage_records GROUP BY amount + 1 ORDER BY total DESC LIMIT 5",
    );
    defer malformed_group_arithmetic_kind.deinit(alloc);
    try corruptGeneratedReadFirstGroupExpressionKind(&malformed_group_arithmetic_kind, .subtractive);
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedAggregateForLowerExprTestAlloc(
        alloc,
        &malformed_group_arithmetic_kind,
        schema,
        &.{},
    ));

    var malformed_projection = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT status, SUM(amount) AS total FROM usage_records GROUP BY status ORDER BY total DESC LIMIT 5",
    );
    defer malformed_projection.deinit(alloc);
    try corruptGeneratedReadFirstProjectionExpressionItem(&malformed_projection);
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedAggregateForLowerExprTestAlloc(
        alloc,
        &malformed_projection,
        schema,
        &.{},
    ));

    var malformed_projection_item_end = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT status AS state, SUM(amount) AS total FROM usage_records GROUP BY status ORDER BY total DESC LIMIT 5",
    );
    defer malformed_projection_item_end.deinit(alloc);
    try corruptGeneratedReadFirstProjectionItemEndToExpressionEnd(&malformed_projection_item_end);
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedAggregateForLowerExprTestAlloc(
        alloc,
        &malformed_projection_item_end,
        schema,
        &.{},
    ));

    var malformed_orphan_child_kind = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT status, SUM(amount) AS total FROM usage_records GROUP BY status ORDER BY total DESC LIMIT 5",
    );
    defer malformed_orphan_child_kind.deinit(alloc);
    try corruptGeneratedReadFirstProjectionOrphanChildKind(&malformed_orphan_child_kind);
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedAggregateForLowerExprTestAlloc(
        alloc,
        &malformed_orphan_child_kind,
        schema,
        &.{},
    ));

    var malformed_stale_operator = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT status, SUM(amount) AS total FROM usage_records GROUP BY status ORDER BY total DESC LIMIT 5",
    );
    defer malformed_stale_operator.deinit(alloc);
    try corruptGeneratedReadFirstProjectionStaleOperatorTokens(&malformed_stale_operator);
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedAggregateForLowerExprTestAlloc(
        alloc,
        &malformed_stale_operator,
        schema,
