test "sql adapter lower expr lowers case-fold expression predicates" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"email":{"type":"keyword"}},"required":["id","email"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const schema = try runtimeSchemaFromJsonForLowerExprTestAlloc(alloc, schema_json);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT id FROM users WHERE lower(email) = $1",
        schema,
        &.{.{ .string = "ada@example.test" }},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 0), lowered.plan.query.predicates.len);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, lowered.plan.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqualStrings("email", lowered.plan.query.expression_predicates[0].lhs.operands[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, lowered.plan.query.expression_predicates[0].op);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.expression_predicates[0].rhs.len);
    try std.testing.expectEqualStrings("\"ada@example.test\"", lowered.plan.query.expression_predicates[0].rhs[0].value_json);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT id FROM users WHERE lower(email) = 3",
        schema,
        &.{},
    ));

    var upper_lowered = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT upper(email) AS email_upper FROM users WHERE upper(email) = $1",
        schema,
        &.{.{ .string = "ADA@EXAMPLE.TEST" }},
    );
    defer upper_lowered.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), upper_lowered.plan.query.expressions.len);
    try std.testing.expectEqualStrings("email_upper", upper_lowered.plan.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.upper, upper_lowered.plan.query.expressions[0].expression.kind);
    try std.testing.expectEqual(@as(usize, 0), upper_lowered.plan.query.predicates.len);
    try std.testing.expectEqual(@as(usize, 1), upper_lowered.plan.query.expression_predicates.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.upper, upper_lowered.plan.query.expression_predicates[0].lhs.kind);
    try std.testing.expectEqualStrings("email", upper_lowered.plan.query.expression_predicates[0].lhs.operands[0].field);
    try std.testing.expectEqualStrings("\"ADA@EXAMPLE.TEST\"", upper_lowered.plan.query.expression_predicates[0].rhs[0].value_json);

    var in_lowered = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT id FROM users WHERE lower(email) IN ($1, 'grace@example.test')",
        schema,
        &.{.{ .string = "ada@example.test" }},
    );
    defer in_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), in_lowered.plan.query.predicates.len);
    try std.testing.expectEqual(@as(usize, 0), in_lowered.plan.query.expression_predicates.len);
    try std.testing.expectEqual(@as(usize, 2), in_lowered.plan.query.expression_or_predicates.len);
    try std.testing.expectEqual(@as(usize, 1), in_lowered.plan.query.expression_or_predicates[0].conditions.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, in_lowered.plan.query.expression_or_predicates[0].conditions[0].lhs.kind);
    try std.testing.expectEqualStrings("email", in_lowered.plan.query.expression_or_predicates[0].conditions[0].lhs.operands[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.eq, in_lowered.plan.query.expression_or_predicates[0].conditions[0].op);
    try std.testing.expectEqualStrings("\"ada@example.test\"", in_lowered.plan.query.expression_or_predicates[0].conditions[0].rhs[0].value_json);
    try std.testing.expectEqual(@as(usize, 1), in_lowered.plan.query.expression_or_predicates[1].conditions.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, in_lowered.plan.query.expression_or_predicates[1].conditions[0].lhs.kind);
    try std.testing.expectEqualStrings("\"grace@example.test\"", in_lowered.plan.query.expression_or_predicates[1].conditions[0].rhs[0].value_json);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT id FROM users WHERE lower(email) IN ('ada@example.test', 3)",
        schema,
        &.{},
    ));

    var any_lowered = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT id FROM users WHERE lower(email) = ANY($1::text[])",
        schema,
        &.{.{ .json = "[\"ada@example.test\",\"grace@example.test\"]" }},
    );
    defer any_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), any_lowered.plan.query.predicates.len);
    try std.testing.expectEqual(@as(usize, 0), any_lowered.plan.query.expression_predicates.len);
    try std.testing.expectEqual(@as(usize, 2), any_lowered.plan.query.expression_or_predicates.len);
    try std.testing.expectEqual(@as(usize, 1), any_lowered.plan.query.expression_or_predicates[0].conditions.len);
