test "sql adapter lower expr lowers temporal range predicates and bound projections" {
    const alloc = std.testing.allocator;
    const date_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"product_id":{"type":"numeric"},"product_name":{"type":"keyword"},"price":{"type":"numeric"},"valid_at_start":{"type":"datetime"},"valid_at_end":{"type":"datetime"}},"required":["product_id","product_name"],"additionalProperties":false}}},"periods":[{"name":"valid_at","start_column":"valid_at_start","end_column":"valid_at_end","range_type":"daterange"}],"primary_key":{"columns":["product_id"],"without_overlaps_period":"valid_at"}}
    ;
    const date_schema = try runtimeSchemaFromJsonForLowerExprTestAlloc(alloc, date_schema_json);
    defer runtime_schema.freeSchema(alloc, date_schema);

    var date_contains = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT product_id FROM products WHERE valid_at @> '2025-02-15'::date ORDER BY product_id ASC LIMIT 5",
        date_schema,
        &.{},
    );
    defer date_contains.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), date_contains.plan.query.or_predicates.len);
    try std.testing.expectEqualStrings("valid_at_start", date_contains.plan.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.lte, date_contains.plan.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("1739577600000000000", date_contains.plan.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("valid_at_end", date_contains.plan.query.or_predicates[1].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.gt, date_contains.plan.query.or_predicates[1].predicates[0].op);
    try std.testing.expectEqualStrings("1739577600000000000", date_contains.plan.query.or_predicates[1].predicates[0].value_json.?);

    var date_overlap = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT product_id FROM products WHERE valid_at && daterange('2025-02-01'::date, '2025-04-01'::date) ORDER BY product_id ASC LIMIT 5",
        date_schema,
        &.{},
    );
    defer date_overlap.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), date_overlap.plan.query.or_predicates.len);
    try std.testing.expectEqualStrings("valid_at_start", date_overlap.plan.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.lt, date_overlap.plan.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("1743465600000000000", date_overlap.plan.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("valid_at_end", date_overlap.plan.query.or_predicates[1].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.gt, date_overlap.plan.query.or_predicates[1].predicates[0].op);
    try std.testing.expectEqualStrings("1738368000000000000", date_overlap.plan.query.or_predicates[1].predicates[0].value_json.?);

    var inclusive_date_overlap = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT product_id FROM products WHERE valid_at && daterange('2025-02-01'::date, '2025-04-01'::date, '[]') ORDER BY product_id ASC LIMIT 5",
        date_schema,
        &.{},
    );
    defer inclusive_date_overlap.deinit(alloc);
    try std.testing.expectEqualStrings("1743552000000000000", inclusive_date_overlap.plan.query.or_predicates[0].predicates[0].value_json.?);

    const numeric_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"sku":{"type":"keyword"},"price":{"type":"numeric"},"valid_at_start":{"type":"numeric"},"valid_at_end":{"type":"numeric"}},"required":["sku"],"additionalProperties":false}}},"periods":[{"name":"valid_at","start_column":"valid_at_start","end_column":"valid_at_end","range_type":"numrange"}],"primary_key":{"columns":["sku"],"without_overlaps_period":"valid_at"}}
    ;
    const numeric_schema = try runtimeSchemaFromJsonForLowerExprTestAlloc(alloc, numeric_schema_json);
    defer runtime_schema.freeSchema(alloc, numeric_schema);

    var bound_query = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT lower(p.valid_at) AS valid_start, upper(p.valid_at) AS valid_end FROM price_intervals AS p WHERE lower(p.valid_at) >= 1 AND upper(p.valid_at) IS NOT NULL ORDER BY upper(p.valid_at) DESC LIMIT 5",
        numeric_schema,
        &.{},
    );
    defer bound_query.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), bound_query.plan.query.expressions.len);
    try std.testing.expectEqualStrings("valid_start", bound_query.plan.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.field, bound_query.plan.query.expressions[0].expression.kind);
    try std.testing.expectEqualStrings("valid_at_start", bound_query.plan.query.expressions[0].expression.field);
    try std.testing.expectEqualStrings("valid_end", bound_query.plan.query.expressions[1].output);
    try std.testing.expectEqualStrings("valid_at_end", bound_query.plan.query.expressions[1].expression.field);
    try std.testing.expectEqual(@as(usize, 2), bound_query.plan.query.expression_predicates.len);
    try std.testing.expectEqualStrings("valid_at_start", bound_query.plan.query.expression_predicates[0].lhs.field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.gte, bound_query.plan.query.expression_predicates[0].op);
    try std.testing.expectEqualStrings("1", bound_query.plan.query.expression_predicates[0].rhs[0].value_json);
    try std.testing.expectEqual(@as(usize, 1), bound_query.plan.query.order_by.len);
    try std.testing.expectEqualStrings("valid_at_end", bound_query.plan.query.order_by[0].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderDirection.desc, bound_query.plan.query.order_by[0].direction);

    var period_contains = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT sku FROM price_intervals WHERE valid_at @> 7 ORDER BY sku ASC LIMIT 5",
        numeric_schema,
        &.{},
    );
    defer period_contains.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), period_contains.plan.query.or_predicates.len);
    try std.testing.expectEqualStrings("valid_at_start", period_contains.plan.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.lte, period_contains.plan.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("7", period_contains.plan.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("valid_at_end", period_contains.plan.query.or_predicates[1].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.gt, period_contains.plan.query.or_predicates[1].predicates[0].op);
    try std.testing.expectEqualStrings("7", period_contains.plan.query.or_predicates[1].predicates[0].value_json.?);

    var period_overlap = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT sku FROM price_intervals WHERE valid_at && numrange(5, 9) ORDER BY sku ASC LIMIT 5",
        numeric_schema,
        &.{},
    );
    defer period_overlap.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), period_overlap.plan.query.or_predicates.len);
    try std.testing.expectEqualStrings("valid_at_start", period_overlap.plan.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.lt, period_overlap.plan.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("9", period_overlap.plan.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("valid_at_end", period_overlap.plan.query.or_predicates[1].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.gt, period_overlap.plan.query.or_predicates[1].predicates[0].op);
    try std.testing.expectEqualStrings("5", period_overlap.plan.query.or_predicates[1].predicates[0].value_json.?);

    var unbounded_overlap = try lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT sku FROM price_intervals WHERE valid_at && '[,9)'::numrange",
        numeric_schema,
        &.{},
    );
    defer unbounded_overlap.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), unbounded_overlap.plan.query.or_predicates.len);
    try std.testing.expectEqualStrings("valid_at_start", unbounded_overlap.plan.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.lt, unbounded_overlap.plan.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("9", unbounded_overlap.plan.query.or_predicates[0].predicates[0].value_json.?);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT sku FROM price_intervals WHERE NOT (valid_at @> 7)",
        numeric_schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT sku FROM price_intervals WHERE NOT (valid_at && numrange(5, 9))",
        numeric_schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanForLowerExprTestAlloc(
        alloc,
        "SELECT sku FROM price_intervals WHERE valid_at && numrange(5, 5)",
        numeric_schema,
        &.{},
    ));
}

test "sql adapter lower expr assembles boolean predicate groups" {
    const alloc = std.testing.allocator;

    var join_side_checks = std.ArrayListUnmanaged(runtime_schema.RelationalCheck).empty;
    defer {
        freeRelationalChecks(alloc, join_side_checks.items);
        join_side_checks.deinit(alloc);
    }
    var join_on_expressions = std.ArrayListUnmanaged(runtime_schema.RelationalRowsExpressionCondition).empty;
    defer {
        freeExpressionConditions(alloc, join_on_expressions.items);
        join_on_expressions.deinit(alloc);
    }
    try expr_predicate.appendJoinOnScalarPredicateAlloc(alloc, &join_side_checks, &join_on_expressions, .inner, .right, "status", .eq, try alloc.dupe(u8, "\"open\""), null);
    try std.testing.expectEqual(@as(usize, 1), join_side_checks.items.len);
    try std.testing.expectEqualStrings("status", join_side_checks.items[0].field);
    try std.testing.expectEqualStrings("\"open\"", join_side_checks.items[0].value_json.?);
    try expr_predicate.appendJoinOnScalarPredicateAlloc(alloc, &join_side_checks, &join_on_expressions, .left, .left, "status", .eq, try alloc.dupe(u8, "\"queued\""), null);
    try std.testing.expectEqual(@as(usize, 1), join_on_expressions.items.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionFieldSource.row, join_on_expressions.items[0].lhs.field_source);
    try std.testing.expectEqualStrings("status", join_on_expressions.items[0].lhs.field);
    try std.testing.expectEqualStrings("\"queued\"", join_on_expressions.items[0].rhs[0].value_json);

    const json_extract_expression = try expr_projection.expressionFromJsonExtractProjectionAlloc(alloc, .{
        .output = "metadata_source",
        .field = "metadata",
        .path = "source",
        .as_text = true,
    });
    defer freeExpression(alloc, json_extract_expression);
    try std.testing.expectEqual(runtime_schema.RelationalRowsExpressionKind.json_extract, json_extract_expression.kind);
    try std.testing.expectEqualStrings("source", json_extract_expression.json_path);
    try std.testing.expect(json_extract_expression.json_as_text);
    try std.testing.expectEqualStrings("metadata", json_extract_expression.operands[0].field);

    const array_length_expression = try expr_projection.expressionFromArrayLengthProjectionAlloc(alloc, .{
        .output = "tag_count",
        .field = "tags",
    });
    defer freeExpression(alloc, array_length_expression);
    try std.testing.expectEqual(runtime_schema.RelationalRowsExpressionKind.array_length, array_length_expression.kind);
    try std.testing.expectEqualStrings("tags", array_length_expression.operands[0].field);

    const coalesce_expression = try expr_projection.expressionFromCoalesceProjectionAlloc(alloc, .{
        .output = "status_coalesced",
        .operands = &.{
            .{ .kind = .field, .field = "status" },
            .{ .kind = .value, .value_json = "\"unknown\"" },
        },
    });
    defer freeExpression(alloc, coalesce_expression);
    try std.testing.expectEqual(runtime_schema.RelationalRowsExpressionKind.coalesce, coalesce_expression.kind);
    try std.testing.expectEqualStrings("status", coalesce_expression.operands[0].field);
    try std.testing.expectEqualStrings("\"unknown\"", coalesce_expression.operands[1].value_json);

    const order_schema: runtime_schema.TableSchema = .{
        .storage_mode = .relational,
        .relational_columns = &.{
            .{ .name = "id", .path = "id", .field_type = .keyword },
            .{ .name = "status", .path = "status", .field_type = .keyword, .collation = "antfly.case_insensitive" },
            .{ .name = "tenant_id", .path = "tenant_id", .field_type = .keyword, .collation = "tenant.case_insensitive" },
        },
    };
    const order_select: plan_mod.SelectList = .{
        .fields = &.{},
        .json_extract = &.{.{ .output = "tier", .field = "payload", .path = "$.tier", .as_text = true }},
        .field_aliases = &.{
            .{ .field = "status", .output = "projected_status" },
            .{ .field = "tenant_id", .output = "tenant" },
        },
        .expressions = &.{.{ .output = "always_true", .expression = .{ .kind = .value, .value_json = "true" } }},
        .scalar_subqueries = &.{.{ .output = "first_status", .output_field = "status" }},
        .outputs = &.{
            .{ .kind = .field_alias, .index = 0 },
            .{ .kind = .json_extract, .index = 0 },
            .{ .kind = .field_alias, .index = 1 },
            .{ .kind = .expression, .index = 0 },
            .{ .kind = .scalar_subquery, .index = 0 },
        },
        .select_all = true,
    };
    var ordinal_base_order = try expr_projection.selectOutputOrderByOrdinalAlloc(alloc, order_schema, order_select, 1);
    defer freeOrderBy(alloc, (&ordinal_base_order)[0..1]);
    try std.testing.expectEqualStrings("id", ordinal_base_order.field);
    var ordinal_star_order = try expr_projection.selectOutputOrderByOrdinalAlloc(alloc, order_schema, order_select, 3);
    defer freeOrderBy(alloc, (&ordinal_star_order)[0..1]);
    try std.testing.expectEqualStrings("tenant_id", ordinal_star_order.field);
    try std.testing.expectEqualStrings("tenant.case_insensitive", ordinal_star_order.collation.?);
    var ordinal_projected_order = try expr_projection.selectOutputOrderByOrdinalAlloc(alloc, order_schema, order_select, 4);
    defer freeOrderBy(alloc, (&ordinal_projected_order)[0..1]);
    try std.testing.expectEqualStrings("status", ordinal_projected_order.field);
    try std.testing.expectEqualStrings("antfly.case_insensitive", ordinal_projected_order.collation.?);
    var alias_pos: usize = 0;
    const alias_tokens = [_]Token{.{ .kind = .identifier, .text = "tenant", .source_start = 0, .source_end = 6 }};
    var alias_order = (try expr_projection.parseSelectOutputOrderByNameMaybeAlloc(alloc, alias_tokens[0..], &alias_pos, order_schema, order_select)).?;
    defer freeOrderBy(alloc, (&alias_order)[0..1]);
    try std.testing.expectEqual(@as(usize, 1), alias_pos);
    try std.testing.expectEqualStrings("tenant_id", alias_order.field);
    try std.testing.expectEqualStrings("tenant.case_insensitive", alias_order.collation.?);
    var expression_pos: usize = 0;
    const expression_tokens = [_]Token{.{ .kind = .identifier, .text = "always_true", .source_start = 0, .source_end = 11 }};
    var expression_order = (try expr_projection.parseSelectOutputOrderByNameMaybeAlloc(alloc, expression_tokens[0..], &expression_pos, order_schema, order_select)).?;
    defer freeOrderBy(alloc, (&expression_order)[0..1]);
    try std.testing.expectEqual(@as(usize, 1), expression_pos);
    try std.testing.expect(expression_order.expression != null);
    try std.testing.expectEqualStrings("true", expression_order.expression.?.value_json);
    var ordinal_scalar_order = try expr_projection.selectOutputOrderByOrdinalAlloc(alloc, order_schema, order_select, 8);
    defer freeOrderBy(alloc, (&ordinal_scalar_order)[0..1]);
    try std.testing.expectEqualStrings("first_status", ordinal_scalar_order.field);
    try std.testing.expect(ordinal_scalar_order.collation == null);
    var scalar_pos: usize = 0;
    const scalar_tokens = [_]Token{.{ .kind = .identifier, .text = "first_status", .source_start = 0, .source_end = 12 }};
    var scalar_order = (try expr_projection.parseSelectOutputOrderByNameMaybeAlloc(alloc, scalar_tokens[0..], &scalar_pos, order_schema, order_select)).?;
    defer freeOrderBy(alloc, (&scalar_order)[0..1]);
    try std.testing.expectEqual(@as(usize, 1), scalar_pos);
    try std.testing.expectEqualStrings("first_status", scalar_order.field);
    try std.testing.expect(scalar_order.collation == null);
    var operator_pos: usize = 0;
    const operator_tokens = [_]Token{
        .{ .kind = .identifier, .text = "tenant", .source_start = 0, .source_end = 6 },
        .{ .kind = .plus, .text = "+", .source_start = 7, .source_end = 8 },
    };
    try std.testing.expect((try expr_projection.parseSelectOutputOrderByNameMaybeAlloc(alloc, operator_tokens[0..], &operator_pos, order_schema, order_select)) == null);
    try std.testing.expectEqual(@as(usize, 0), operator_pos);
}

test "sql adapter lower expr validates aggregate helpers" {
    const alloc = std.testing.allocator;

    const lower_status: runtime_schema.RelationalRowsExpression = .{
        .kind = .lower,
        .operands = &.{.{ .kind = .field, .field = "status" }},
    };
    const order_by = [_]db_mod.types.RelationalRowsQueryOrder{.{
        .field = "status",
        .expression = lower_status,
        .direction = .asc,
    }};
    const filters = [_]runtime_schema.RelationalCheck{.{
        .name = "status_check",
        .field = "status",
        .op = .eq,
        .value_json = "\"open\"",
    }};
    const json_filters = [_]db_mod.types.RelationalRowsJsonContainsPredicate{.{
        .field = "metadata",
        .value_json = "{\"source\":\"sql\"}",
    }};
    try std.testing.expectEqual(db_mod.types.RelationalRowsAggregateOp.percentile_cont, expr_aggregate.opForName("PERCENTILE_CONT").?);
    try std.testing.expectEqualStrings("array_agg", expr_aggregate.opName(.array_agg));
    try expr_aggregate.validatePercentile(0);
    try expr_aggregate.validatePercentile(1);
    try std.testing.expectError(error.UnsupportedSqlShape, expr_aggregate.validatePercentile(-0.01));
    try std.testing.expectError(error.UnsupportedSqlShape, expr_aggregate.validatePercentile(1.01));
    try std.testing.expectError(error.UnsupportedSqlShape, expr_aggregate.validatePercentile(std.math.inf(f64)));
    const explicit_alias = try expr_aggregate.aliasOrDefaultAlloc(alloc, "total_amount", .sum, "amount");
    defer alloc.free(explicit_alias);
    try std.testing.expectEqualStrings("total_amount", explicit_alias);
    const field_alias = try expr_aggregate.aliasOrDefaultAlloc(alloc, null, .sum, "amount");
    defer alloc.free(field_alias);
    try std.testing.expectEqualStrings("sum_amount", field_alias);
    const op_alias = try expr_aggregate.aliasOrDefaultAlloc(alloc, null, .count, null);
    defer alloc.free(op_alias);
    try std.testing.expectEqualStrings("count", op_alias);
    try std.testing.expect(expr_aggregate.isPercentileOp(.percentile_disc));
    try std.testing.expect(!expr_aggregate.isPercentileOp(.array_agg));
    try std.testing.expectEqual(@as(?f64, 1.5), expr_aggregate.sqlJsonNumberAsF64(.{ .number_string = "1.5" }));
    try std.testing.expect(expr_aggregate.sqlJsonNumberAsF64(.{ .string = "1.5" }) == null);

    const group_projection: db_mod.types.RelationalRowsExpressionProjection = .{
        .output = "status_lower",
        .expression = lower_status,
    };
    const field_alias_projection: db_mod.types.RelationalRowsFieldAliasProjection = .{
        .output = "status",
        .field = "status",
    };
    try std.testing.expectEqual(runtime_schema.AntflyType.keyword, (try expr_projection.jsonValueProjectedType(alloc, "\"open\"")).field_type);
    try std.testing.expectEqual(runtime_schema.AntflyType.numeric, (try expr_projection.jsonValueProjectedType(alloc, "42")).field_type);
    try std.testing.expectEqual(runtime_schema.AntflyType.boolean, (try expr_projection.jsonValueProjectedType(alloc, "true")).field_type);
    try std.testing.expectError(error.UnsupportedSqlShape, expr_projection.jsonValueProjectedType(alloc, "null"));
    const coalesce_columns = [_]runtime_schema.RelationalColumn{.{
        .name = "status",
        .path = "status",
        .field_type = .keyword,
        .array_item_type = null,
    }};
    try std.testing.expectEqual(runtime_schema.AntflyType.keyword, (try expr_projection.coalesceOutputType(alloc, &coalesce_columns, .{
        .output = "status_coalesced",
        .operands = &.{.{ .kind = .field, .field = "status" }},
    })).field_type);
    const projected_column = try expr_projection.projectedColumnAlloc(alloc, "status", .keyword, null, true);
    defer {
        alloc.free(projected_column.name);
        alloc.free(projected_column.path);
    }
    try std.testing.expectEqualStrings("status", projected_column.name);
    try std.testing.expectEqualStrings("status", projected_column.path);
    try std.testing.expectEqual(runtime_schema.AntflyType.keyword, projected_column.field_type);
    try std.testing.expect(projected_column.nullable);
    try std.testing.expectEqual(@as(usize, 1), expr_projection.selectListOutputCount(&.{"status"}, &.{}, &.{}, &.{}, &.{}, &.{}, &.{}, "status"));
    try std.testing.expectEqual(@as(usize, 2), expr_projection.selectListOutputCount(&.{"status"}, &.{}, &.{}, &.{}, &.{field_alias_projection}, &.{}, &.{}, "status"));
    const select_schema = runtime_schema.TableSchema{
        .storage_mode = .relational,
        .relational_columns = &.{.{ .name = "status", .path = "status", .field_type = .keyword, .collation = "status_collation" }},
    };
    try expr_projection.validateSelectListOutputs(select_schema, false, &.{"status"}, &.{}, &.{}, &.{}, &.{}, &.{}, &.{});
    try expr_projection.validateSelectListOutputs(select_schema, false, &.{}, &.{.{
        .output = "status_json",
        .field = "payload",
        .path = "$.status",
        .as_text = true,
    }}, &.{}, &.{}, &.{}, &.{}, &.{});
    try std.testing.expectError(error.UnsupportedSqlShape, expr_projection.validateSelectListOutputs(select_schema, false, &.{"status"}, &.{}, &.{}, &.{}, &.{field_alias_projection}, &.{}, &.{}));
    var disambiguated_status: []const u8 = try alloc.dupe(u8, "status");
    defer alloc.free(disambiguated_status);
    try expr_projection.disambiguateSelectProjectionOutputIfNeededAlloc(alloc, select_schema, true, &.{}, &.{}, &.{}, &.{}, &.{}, &.{}, &.{}, &disambiguated_status);
    try std.testing.expectEqualStrings("status_2", disambiguated_status);
    var disambiguated_status_again: []const u8 = try alloc.dupe(u8, "status");
    defer alloc.free(disambiguated_status_again);
    try expr_projection.disambiguateSelectProjectionOutputIfNeededAlloc(alloc, select_schema, true, &.{}, &.{.{
        .output = "status_2",
        .field = "payload",
        .path = "$.status",
        .as_text = true,
    }}, &.{}, &.{}, &.{}, &.{}, &.{}, &disambiguated_status_again);
    try std.testing.expectEqualStrings("status_3", disambiguated_status_again);
    try std.testing.expectError(error.UnsupportedSqlShape, expr_projection.validateSelectListOutputs(select_schema, true, &.{}, &.{.{
        .output = "status",
        .field = "payload",
        .path = "$.status",
        .as_text = true,
    }}, &.{}, &.{}, &.{}, &.{}, &.{}));
    try expr_projection.validateSelectListOutputs(select_schema, true, &.{}, &.{.{
        .output = "status_2",
        .field = "payload",
        .path = "$.status",
        .as_text = true,
    }}, &.{}, &.{}, &.{}, &.{}, &.{});
    const select_columns = try expr_projection.selectOutputColumnsAlloc(alloc, .{ .alloc = alloc, .schema = select_schema }, .{
        .fields = &.{"status"},
        .json_extract = &.{.{ .output = "status_json", .field = "payload", .path = "$.status", .as_text = true }},
        .array_length = &.{.{ .output = "tag_count", .field = "tags" }},
        .expressions = &.{.{ .output = "enabled", .expression = .{ .kind = .value, .value_json = "true" } }},
        .outputs = &.{
            .{ .kind = .field, .index = 0 },
            .{ .kind = .json_extract, .index = 0 },
            .{ .kind = .array_length, .index = 0 },
            .{ .kind = .expression, .index = 0 },
        },
    });
    defer ddl_plan.freeDdlRelationalColumns(alloc, select_columns);
    try std.testing.expectEqual(@as(usize, 4), select_columns.len);
    try std.testing.expectEqualStrings("status", select_columns[0].name);
    try std.testing.expectEqual(runtime_schema.AntflyType.keyword, select_columns[0].field_type);
    try std.testing.expectEqualStrings("status_collation", select_columns[0].collation.?);
    try std.testing.expectEqualStrings("status_json", select_columns[1].name);
    try std.testing.expectEqual(runtime_schema.AntflyType.keyword, select_columns[1].field_type);
    try std.testing.expectEqualStrings("tag_count", select_columns[2].name);
    try std.testing.expectEqual(runtime_schema.AntflyType.numeric, select_columns[2].field_type);
    try std.testing.expectEqualStrings("enabled", select_columns[3].name);
    try std.testing.expectEqual(runtime_schema.AntflyType.boolean, select_columns[3].field_type);
    try std.testing.expectError(error.UnsupportedSqlShape, expr_projection.selectOutputColumnsAlloc(alloc, .{ .alloc = alloc, .schema = select_schema }, .{
        .fields = &.{"status"},
        .outputs = &.{.{ .kind = .field, .index = 1 }},
    }));
    try expr_aggregate.validateGroupBy(&.{"status"}, &.{group_projection}, &.{"status"}, &.{group_projection});
    try std.testing.expectError(error.UnsupportedSqlShape, expr_aggregate.validateGroupBy(&.{"status"}, &.{}, &.{"tenant_id"}, &.{}));

    const aggregate_specs = [_]db_mod.types.RelationalRowsAggregateSpec{.{
        .name = "statuses",
        .op = .array_agg,
        .field = "status",
        .filter_json_contains = &json_filters,
    }};
    const duplicate_aggregate_specs = [_]db_mod.types.RelationalRowsAggregateSpec{.{
        .name = "status",
        .op = .count,
    }};
    try std.testing.expect(expr_aggregate.outputFieldIsUnique(&.{"status"}, &.{group_projection}, &aggregate_specs, "statuses"));
    try std.testing.expect(!expr_aggregate.outputFieldIsUnique(&.{"status"}, &.{group_projection}, &duplicate_aggregate_specs, "status"));
    const output_columns = [_]runtime_schema.RelationalColumn{.{ .name = "statuses", .path = "statuses", .field_type = .array }};
    try std.testing.expect(expr_projection.outputColumnExists(&output_columns, "statuses"));
    try std.testing.expect(!expr_projection.outputColumnExists(&output_columns, "missing"));
    try expr_aggregate.validateSelectListOutputs(&.{"status"}, &.{group_projection}, &aggregate_specs);
    try std.testing.expectError(error.UnsupportedSqlShape, expr_aggregate.validateSelectListOutputs(&.{"status"}, &.{group_projection}, &.{.{
