test "sql adapter lower expr lowers equality join queries" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"kind":{"type":"keyword"},"tenant":{"type":"keyword"},"id":{"type":"keyword"},"customer_id":{"type":"keyword"},"name":{"type":"keyword"},"scope":{"type":"keyword"},"amount":{"type":"numeric"},"enabled":{"type":"boolean"},"tags":{"type":"array","items":{"type":"keyword"}},"metadata":{"type":"json"}},"required":["kind","tenant","id"],"additionalProperties":false}}},"primary_key":{"columns":["kind","tenant","id"]}}
    ;
    const schema = try runtimeSchemaFromJsonForLowerExprTestAlloc(alloc, schema_json);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerJoinForLowerExprTestAlloc(
        alloc,
        "SELECT o.id AS order_id, c.name AS customer_name, o.amount AS amount FROM usage_records AS o LEFT JOIN usage_records AS c ON o.tenant = c.tenant AND o.customer_id = c.id WHERE o.kind = 'order' AND c.kind = 'customer' ORDER BY amount DESC LIMIT 5",
        schema,
        &.{},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqualStrings("usage_records", lowered.left_table_name);
    try std.testing.expectEqualStrings("usage_records", lowered.right_table_name);
    const lowered_plan = lowered.asPlan();
    try std.testing.expectEqualStrings("usage_records", lowered_plan.left_table);
    try std.testing.expectEqualStrings("usage_records", lowered_plan.right_table);
    try std.testing.expectEqual(db_mod.types.RelationalRowsJoinType.left, lowered.join.join_type);
    try std.testing.expectEqual(@as(usize, 2), lowered.join.on.len);
    try std.testing.expectEqualStrings("tenant", lowered.join.on[0].left_field);
    try std.testing.expectEqualStrings("tenant", lowered.join.on[0].right_field);
    try std.testing.expectEqualStrings("customer_id", lowered.join.on[1].left_field);
    try std.testing.expectEqualStrings("id", lowered.join.on[1].right_field);
    try std.testing.expectEqual(@as(usize, 1), lowered.join.left.predicates.len);
    try std.testing.expectEqualStrings("kind", lowered.join.left.predicates[0].field);
    try std.testing.expectEqualStrings("\"order\"", lowered.join.left.predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 1), lowered.join.right.predicates.len);
    try std.testing.expectEqualStrings("kind", lowered.join.right.predicates[0].field);
    try std.testing.expectEqualStrings("\"customer\"", lowered.join.right.predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 3), lowered.join.select.len);
    try std.testing.expectEqualStrings("order_id", lowered.join.select[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsJoinProjectionSide.left, lowered.join.select[0].side);
    try std.testing.expectEqualStrings("id", lowered.join.select[0].field);
    try std.testing.expectEqualStrings("customer_name", lowered.join.select[1].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsJoinProjectionSide.right, lowered.join.select[1].side);
    try std.testing.expectEqualStrings("name", lowered.join.select[1].field);
    try std.testing.expectEqual(@as(usize, 1), lowered.join.order_by.len);
    try std.testing.expectEqualStrings("amount", lowered.join.order_by[0].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsQueryOrderDirection.desc, lowered.join.order_by[0].direction);
    try std.testing.expectEqual(@as(u32, 5), lowered.join.limit.?);

    var fetch_paginated_join = try lowerJoinForLowerExprTestAlloc(
        alloc,
        "SELECT o.id AS order_id, c.name AS customer_name FROM usage_records AS o LEFT JOIN usage_records AS c ON o.tenant = c.tenant AND o.customer_id = c.id WHERE o.kind = 'order' AND c.kind = 'customer' ORDER BY order_id ASC OFFSET 2 ROWS FETCH NEXT 4 ROWS ONLY",
        schema,
        &.{},
    );
    defer fetch_paginated_join.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 4), fetch_paginated_join.join.limit.?);
    try std.testing.expectEqual(@as(u32, 2), fetch_paginated_join.join.offset);

    var malformed_generated_join_fetch_count_payload = try tokenized.ParsedSql.initAlloc(
        alloc,
        "SELECT o.id AS order_id, c.name AS customer_name FROM usage_records AS o LEFT JOIN usage_records AS c ON o.tenant = c.tenant AND o.customer_id = c.id WHERE o.kind = 'order' AND c.kind = 'customer' ORDER BY order_id ASC OFFSET 2 ROWS FETCH NEXT 4 ROWS ONLY",
    );
    defer malformed_generated_join_fetch_count_payload.deinit(alloc);
    if (malformed_generated_join_fetch_count_payload.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| switch (generated_ast.*) {
            .read => |read| {
                if (read.fetch_count_tokens == null or read.fetch_count_expression.tokens == null) return error.TestUnexpectedResult;
                read.fetch_count_expression.kind = .function_call;
            },
            else => return error.TestUnexpectedResult,
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(error.UnsupportedSqlShape, lowerParsedJoinForLowerExprTestAlloc(
        alloc,
        &malformed_generated_join_fetch_count_payload,
        schema,
        &.{},
    ));

    var natural_join = try lowerJoinForLowerExprTestAlloc(
        alloc,
        "SELECT o.id AS order_id, c.name AS customer_name FROM usage_records AS o NATURAL JOIN usage_records AS c WHERE o.kind = 'order' ORDER BY order_id LIMIT 2",
        schema,
        &.{},
    );
    defer natural_join.deinit(alloc);
    try std.testing.expectEqual(db_mod.types.RelationalRowsJoinType.inner, natural_join.join.join_type);
    try std.testing.expect(natural_join.join.on.len > 0);
    try std.testing.expectEqualStrings("kind", natural_join.join.on[0].left_field);
    try std.testing.expectEqualStrings("kind", natural_join.join.on[0].right_field);
    try std.testing.expectEqual(@as(usize, 1), natural_join.join.left.predicates.len);
    try std.testing.expectEqualStrings("kind", natural_join.join.left.predicates[0].field);
    try std.testing.expectEqualStrings("\"order\"", natural_join.join.left.predicates[0].value_json.?);
    try std.testing.expectEqual(@as(u32, 2), natural_join.join.limit.?);

    var right_join = try lowerJoinForLowerExprTestAlloc(
        alloc,
        "SELECT o.id AS order_id, c.name AS customer_name FROM usage_records AS o RIGHT JOIN usage_records AS c ON o.customer_id = c.id WHERE o.kind = 'order' AND c.kind = 'customer'",
        schema,
        &.{},
    );
    defer right_join.deinit(alloc);
    try std.testing.expectEqual(db_mod.types.RelationalRowsJoinType.left, right_join.join.join_type);
    try std.testing.expectEqual(@as(usize, 1), right_join.join.on.len);
    try std.testing.expectEqualStrings("id", right_join.join.on[0].left_field);
    try std.testing.expectEqualStrings("customer_id", right_join.join.on[0].right_field);
    try std.testing.expectEqual(@as(usize, 1), right_join.join.left.predicates.len);
    try std.testing.expectEqualStrings("kind", right_join.join.left.predicates[0].field);
    try std.testing.expectEqualStrings("\"customer\"", right_join.join.left.predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 1), right_join.join.right.predicates.len);
    try std.testing.expectEqualStrings("kind", right_join.join.right.predicates[0].field);
    try std.testing.expectEqualStrings("\"order\"", right_join.join.right.predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 2), right_join.join.select.len);
    try std.testing.expectEqualStrings("order_id", right_join.join.select[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsJoinProjectionSide.right, right_join.join.select[0].side);
    try std.testing.expectEqualStrings("id", right_join.join.select[0].field);
    try std.testing.expectEqualStrings("customer_name", right_join.join.select[1].output);
